pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size)
    // are unusable -> heavy penalty proportional to how "dead" they are.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize wasting a large bin on a small item (large post_residual).
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual as f64 >= item_size as f64 {
            score -= 10.0; // leftover still usable for similarly sized items
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral-ish baseline; open a new bin only when the
    // item would leave a large, well-usable residual and existing fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 - post_residual as f64 * 0.3;
        // With few open bins, opening fresh bins is cheap.
        if open_bins_count <= 2 {
            score -= 12.0;
        }
        // If lookahead item could pair with this item in the new bin, favor it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins with tiny residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && post_residual < 20 {
            score += 15.0;
        }
    }

    // Coupling with mean residual: bins far below mean residual are "loose";
    // prefer filling bins that are already tight (below mean) to compact them.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead synergy: if next item fits exactly into the post_residual,
    // reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    score
}

