pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are heavily penalized (non-linearly).
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64).powf(2.0) * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into
    // existing bins, penalize candidates that leave large slack.
    let bin_pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score += bin_pressure * (post_residual as f64 / 10.0);

    // Lookahead: if the next item fits in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual likely wasted for the known next item.
        score += (post_residual as f64) * 0.3;
    }

    // Mean-residual coupling: if this bin's post residual is far below
    // the mean, it is a tight fit worth encouraging.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Slight baseline cost so a new bin is only chosen when it
        // genuinely beats poor fits into existing bins.
        score += 30.0;
        // Late in the stream, opening new bins is fine (no need to
        // leave many half-empty bins behind).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: post_residual that is too small to be usable
    // (smaller than the minimum plausible item) is wasted space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        // Unusable gap for the known next item -> penalize heavily,
        // scaled by how small the gap is relative to capacity.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 150.0 * (1.0 - gap_frac);
    }

    // Gap that cannot fit the next item but is large enough for future
    // unknown items is only mildly wasteful; small reward for keeping gaps
    // that still fit the lookahead item (chained placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    }

    // Last-chance bin pressure: if this is the only bin that fits,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it attractive only when the
    // item is large relative to residuals elsewhere, otherwise penalize
    // opening new bins slightly so existing bins get filled first.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * mean_residual;
        // Large items are safer in a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Mild alignment with mean residual: bins below mean residual are
    // already tight; favor them to consolidate space.
    score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Tight fit reward: residual just below next typical item size.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening a new bin when
    // the item fits an existing bin reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // penalize new bin, scaled by how many alternatives exist
            score += 40.0 + 10.0 * fitting_bins_count as f64;
        } else {
            // forced new bin: neutral-to-good
            score -= 30.0;
        }
    } else {
        // Open-bin pressure: prefer filling bins when many are open.
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits, slight penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Late-stream urgency: close out bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the minimum item (size 1) usefully,
    // i.e., gaps below a small threshold are penalized quadratically.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // penalize gaps that are small relative to capacity
        let small_gap_threshold = 15.0;
        if gap < small_gap_threshold {
            score += (small_gap_threshold - gap).powi(2) * 1.5;
        }
        // large leftover space is mildly penalized (wasteful placement)
        score += gap * 0.1;
    }

    // Reward using a bin whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open bins pressure: discourage spreading across many bins unless fit is good
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.05 + 0.1 * (1.0 - progress));

    // Mean residual coupling: prefer bins whose residual is below mean (more filled bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would NOT fit in post residual but fits in current residual,
    // penalize consuming space needed by the next item
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 5.0;
    }

    // New-bin candidate baseline: empty bin gets a neutral-ish but slightly
    // penalized score so it's chosen only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in stream or many open bins: opening new bins is cheaper
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover space exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Reward when the next item can also fit into the remaining space
    // (chain-friendliness), scaled by how snug the chain is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack.min(100.0);
    }

    // Penalize small unusable dead space (waste that likely can't fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins whose residual is close to the item (snug fit) relative to mean residual.
    let snugness = (bin_residual as f64 - item_size as f64).abs();
    score += snugness * 0.3;

    // Compare post_residual to mean residual: leaving less than average is good.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Early in the stream, be more conservative about filling bins tightly;
    // late in the stream, aggressively minimize residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless open bins are poor fits.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual is capacity - item_size, already in score.
        // Add a fixed opening cost so it's chosen only when clearly better.
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin supports the lookahead item well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    let gap = post_residual as f64;
    if post_residual > 0 {
        // Penalize gaps that are too small for the smallest plausible item (1..100).
        // A gap of 1..=10 is dead space unless the next item fits it.
        if post_residual < 10 {
            score += 60.0 * (1.0 - gap / 10.0) + 15.0;
        } else if post_residual < 25 {
            score += 25.0 * (1.0 - (gap - 10.0) / 15.0);
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Reward bins whose gap can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: it's likely dead space.
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few bins needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing),
    // but reward using bins with larger residuals when mean residual is high.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 40.0 + 1.5 * open_bins_count as f64 * progress;
        score = base + item_size as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is mandatory anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit bonus: strongly favor bins that end (nearly) empty.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward residuals that match the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post - next).abs();
        if next <= post {
            // Next item fits exactly into the leftover space -> chain bonus.
            score -= 25.0 * (1.0 - diff / cap.max(1.0));
        } else {
            // Next item would not fit: penalize proportionally to wasted potential.
            score += 10.0 * (next - post) / cap.max(1.0);
        }
        // Dead-space penalty: leftover too small for typical items (1..100).
        if post > 0.0 && post < next.min(20.0) {
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins that keep residual distribution tight,
    // and avoid leaving far more space than average (fragmentation risk).
    let dev = post - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    // (post_residual large relative to item size) and many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = post / (item_size.max(1) as f64);
        let pressure = open_bins_count as f64 / 10.0;
        score += 35.0 - 10.0 * pressure - 5.0 * (poor_fit - 1.0).min(3.0);
        // Late in the stream, slightly discourage opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100, assume ~10).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0; // severe penalty for creating tiny dead space
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
