    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item can still fit after this placement
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // penalizing placement into already-loose bins when alternatives exist.
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin has high residual; make it moderately
    // attractive only when it beats creating dead space in open bins.
    if bin_residual == bin_capacity {
