    // ---- Last-chance bin: strongly favor using the only fitting bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline penalty so it's only chosen when open bins
        // are genuinely bad fits. Relax the penalty late in the stream / with many bins.
        let mut new_penalty = 55.0;
        // If no open bin fits, fitting_bins_count counts only this new bin.
        if fitting_bins_count == 1 {
            new_penalty -= 40.0;
        }
        // Slightly cheaper to open bins when many are already open (spread load).
        new_penalty -= (open_bins_count as f64).min(10.0) * 0.5;
        // Early in the stream, opening bins is fine.
        new_penalty -= 15.0 * progress;
        score += new_penalty.max(0.0);
    }

    // ---- Tightness reward: residual consumed relative to item size ----
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Small tie-breaker toward tighter absolute post residual.
    score += 0.05 * post_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared post-residual penalizes leaving mid-range gaps.
    score += 0.35 * (post_residual as f64).powi(2) / 100.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual >= 40 {
        // Large dead space is nearly unusable later.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0 + 20.0 * t;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin is extremely valuable; if post-residual is too small for the
    // next item AND next item fits nothing else, prefer conserving space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * (next_item_size as f64);
        } else {
            score += 8.0;
        }
    }

    // Global state: penalize proliferating bins when mean residual is high
    // (existing bins have room to absorb items).
    if mean_residual > item_size as f64 + 10.0 {
        score -= 10.0;
    } else if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: an empty bin has high raw post_residual;
    // keep it competitive only when the item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let large_item = item_size >= 60;
        let poor_fits = fitting_bins_count <= 1;
        if large_item || poor_fits {
            score -= 30.0;
        } else {
            score += 25.0 + 20.0 * (1.0 - t);
        }
    }

    // Mild early-stream conservatism: keep bins flexible when many items remain.
    score += (1.0 - t) * 0.05 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        + 30.0 * pr_norm * pr_norm * pr_norm;

    // Tight fits are rewarded quadratically
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Smooth interaction: post-residual value decays in usefulness as stream progresses
    // (dead space matters more later), modeled as polynomial coupling.
    let decay = 0.5 + 0.5 * progress;
    score += 20.0 * pr_norm * decay;

    // Penalize bins whose residual deviates from mean residual (smoothly)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus (only fitting bin) — smooth sigmoid-like gate
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward post_residual that still accommodates next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // New-bin candidate: make empty bin mildly unattractive unless residual is hopeless
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 10.0 * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic-class logic: classify residual space and future demand into
    // discrete capacity fractions (harmonics of bin_capacity).

    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: which capacity fraction remains? ---
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0.0 .. 1.0

    // Class boundaries at 1/4, 1/2, 3/4 of capacity.
    // Small post_residual (tight fit) is good -> big reward.
    if post_residual == 0 {
        score -= 40.0; // perfect packing
    } else if frac <= 0.125 {
        score -= 25.0; // nearly full: excellent
    } else if frac <= 0.25 {
        score -= 12.0; // quarter-class residual: acceptable
    } else if frac <= 0.5 {
        score -= 4.0;  // half-class: neutral
    } else if frac <= 0.75 {
        score += 6.0;  // wasteful
    } else {
        score += 14.0; // mostly empty bin used for one item: bad
    }

    // --- Integer-division harmonic of post_residual (dead-space granularity) ---
    // Residuals that cannot host the smallest plausible item (<= ~10) are dead.
    // Modulo classes: post_residual divisible by common item sizes is reusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 18.0; // dead space
        } else if post_residual % 10 == 0 {
            score -= 6.0;  // harmonic residual: likely reusable exactly
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // --- Lookahead coupling: can next_item_size land in this residual class? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits here: reward proportional to how snugly it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - nest / cap);
            // Harmonic bonus: next item exactly consumes the residual class.
            if post_residual == next_item_size {
                score -= 15.0;
            } else if (post_residual - next_item_size) < 10 {
                score -= 8.0; // creates a near-perfect double fit
            }
        } else {
            // Next item cannot use this residual: penalize slightly more for
            // large stranded residuals that block the lookahead.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
        // If next item is large (> half capacity), prefer keeping big residuals open.
        if nxt > cap * 0.5 && post_residual < next_item_size as u32 + 10 && post_residual > 40 {
            score += 8.0;
        }
    }

    // --- Last-chance logic: this is the only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // strongly prefer using the last fitting bin over a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // open-bin residuals are poor fits (high mean residual fragmentation).
        let pressure = (mean_residual / cap).max(0.0);
        score = cap - item_size as f64; // baseline: wasted capacity = capacity - item
        // Penalize opening bins early in the stream or when many bins are open.
        score += (open_bins_count as f64) * 2.0;
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If mean residual is already high (fragmented), a new bin is less bad.
        score -= pressure * 5.0;
        // Small items should almost never open new bins.
        if item_size <= 25 {
            score += 25.0;
        }
        // Large items with no good harmonic fit may justify a fresh bin.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // --- Mild stream-position modulation: pack tighter toward the end ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to be useful are heavily penalized.
    // Treat gaps below ~12 units as dead space (min practical item footprint).
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 15.0;
    }
    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0; // bin still usable for lookahead
        } else {
            score += 8.0; // lookahead cannot use this bin's remainder
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate and spread-out choices).
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Mean residual coupling: if open bins are on average slack, be pickier about fits.
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    // Early in the stream, allow slightly looser packing to build useful partial bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimizes dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post-residual,
    // penalize if the leftover is just slightly too small for the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= (60.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            // Leftover unusable by next item: penalize proportionally to how close it was.
            score += 10.0 + 30.0 * (1.0 - overshoot / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (consolidate fullness), penalize dipping into roomy bins.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid).min(50.0);
    } else {
        score += 0.3 * (resid - mean_residual).min(50.0);
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = post_residual as f64 > 40.0;
        if fitting_bins_count == 0 || (poor_fit && progress < 0.5) {
            score -= 120.0;
        } else {
            // Discard new-bin option when decent placements exist.
            score += 250.0;
        }
    }

    // Mild pressure to close out bins as the stream matures.
    score += 0.05 * (bin_residual as f64) * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Penalize dead space: post-residual too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual exactly / well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty scaled by how close.
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: prefer filling bins when many are open (consolidation pressure).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.05 * pressure * (item_size as f64 / bin_capacity as f64);

    // Time horizon: later in the stream, be greedier about tight fits; early on, allow exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: make empty bin attractive only if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when open bins are fragmented.
        let mut new_bin_cost = 30.0;
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0; // forced open
        } else if mean_residual > bin_capacity as f64 * 0.5 {
            // Open bins are quite full; opening may be reasonable.
            new_bin_cost -= 10.0;
        }
        if progress > 0.8 {
            new_bin_cost *= 0.7; // endgame: consolidation matters less than flow
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * progress;
    score += 8.0 * poly;
    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + 3.0 * progress) * (item_size as f64 / cap);
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 2.0 * progress);
        } else {
            score -= 0.3 * (pr - nx) / cap;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }
    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * progress;
    // Alignment with mean residual: prefer bins near the mean early, tighter later
    score += (mean_residual - pr).abs() / cap * (1.0 - 2.0 * progress).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (integer division buckets of 10).
    let res_class = post_residual / 10;
    let cap_class = bin_capacity / 10;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small residuals generally (waste minimization), with harmonic shaping.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Penalize "dead" residuals that few item sizes can use (classes below 10 are unusable
    // for items >= 10 in the classic regime; for 1..100 regime, tiny slivers are bad).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability bonus: scaled by how snugly the next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 - snug * 0.15;
        } else {
            // Next item won't chain here: mild penalty, worse if residual is large but unusable.
            let waste = post_residual as f64;
            score += 4.0 + waste * 0.02;
        }
    }

    // Modulo-arithmetic class matching: residual class congruent with item class
    // suggests repeated partitioning of the same harmonic cell.
    if (item_size / 10) == res_class && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when mean residual across open bins is low
    // (open bins are nearly full) or nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fit_gap = mean_residual - item_size as f64;
        // Penalize opening a new bin when open bins have usable space.
        score += 60.0 + mean_fit_gap.max(0.0) * 2.0;
        // Late in the stream, opening fresh bins is less harmful (fewer future items to strand).
        score -= progress * 20.0;
        // If many bins are open but none fit snugly, allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Discard the harmonic-class bonus structure for the fresh bin.
        score += res_class as f64 * 0.5;
    }

    // Congestion-aware tiebreak: with many open bins, prefer tighter fits.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Moderate dead space also penalized, scaled by fraction of capacity wasted.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 40.0;

    // Prefer bins whose residual was already small (tight packing pressure).
    score += (bin_residual as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // unless the fit is perfect; when few bins, opening is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        // Dead space that the next item cannot use: penalize extra.
        score += 8.0;
    }

    // New-bin candidate: make it attractive only when current fits are poor
    // (large waste) or the bin count is low; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if post_residual == bin_capacity {
            // empty bin receiving the item directly: neutral baseline
            score -= 20.0;
        }
    }

    // Alignment with mean residual: prefer bins closer to the mean state
    // to keep capacity balanced across open bins.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover space exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Reward when the next item can also fit into the remaining space
    // (chain-friendliness), scaled by how snug the chain is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack.min(100.0);
    }

    // Penalize small unusable dead space (waste that likely can't fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins whose residual is close to the item (snug fit) relative to mean residual.
    let snugness = (bin_residual as f64 - item_size as f64).abs();
    score += snugness * 0.3;

    // Compare post_residual to mean residual: leaving less than average is good.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Early in the stream, be more conservative about filling bins tightly;
    // late in the stream, aggressively minimize residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless open bins are poor fits.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual is capacity - item_size, already in score.
        // Add a fixed opening cost so it's chosen only when clearly better.
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin supports the lookahead item well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: strongly discount small post_residual
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize wasteful placements: leaving a residual that is too small for
    // typical future items (below the minimum item size) is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // post-residual too small for the next item: mild penalty proportional to waste
            score += (post_residual as f64) * 0.3;
        }
        // If next item exactly fills the leftover, extra reward
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    // Opening a new bin is attractive only when the item is large relative to
    // capacity or existing bins are very full / fragmented.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, amortized by stream progress
        let mut new_bin_cost = 30.0 - 10.0 * progress;
        // If many bins are open, prefer consolidating into them
        new_bin_cost += (open_bins_count as f64) * 1.5;
        // If the mean residual is large, existing bins have room: penalize new bin more
        new_bin_cost += mean_residual * 0.2;
        // Large items pack cleanly into fresh bins; discount the cost
        new_bin_cost -= fill_fraction * 40.0;
        // If no open bin fits well (this call is the new-bin candidate and other
        // fitting bins exist), the comparison is done via score; add lookahead:
        if next_item_size > 0 && (bin_capacity - item_size) < next_item_size {
            new_bin_cost += 5.0; // fresh bin won't help the next item either
        }
        score += new_bin_cost;
    } else {
        // Placing into an existing bin: slight reward scaled by how full the bin
        // becomes (prefer filling nearly-full bins first, classic best-fit flavor)
        let used_after = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= used_after * 8.0;
        // Bins far below mean residual are underfilled; gently prefer them to
        // balance load and keep big residuals available
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        }
    }

    // Late in the stream, consolidation matters more: reward using open bins
    score -= (1.0 - progress) * 0.0 + progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: prefer filling bins well (reward small post_residual strongly).
    // Late in the stream: dead space matters less; smooth decay of the reward.
    let fill_reward = (pr / cap).powi(3) * (1.0 - progress).powf(1.5);
    score -= 60.0 * fill_reward;

    // Penalize leaving a residual that cannot fit the lookahead item, weighted by progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 2.0 * progress);
        } else {
            // Reward leaving room exactly for the next item (perfect chaining).
            let chain = 1.0 - ((pr - nxt) / cap).powi(2);
            score -= 10.0 * chain.max(0.0) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - (pr / cap).powi(2));
    }

    // Prefer bins with residual below the mean (tighter bins get filled first),
    // with a smooth quadratic interaction with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // Mild penalty for spreading across many bins early on.
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize opening a bin unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress) - 15.0 * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10
    // Small dead space classes (mod 10 in {1..9} but < 10) are nearly unusable.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 40.0; // tiny dead space, unusable for items >= 10
    } else if pr == 0 {
        score -= 25.0; // perfect closure
    } else {
        // class-based desirability of leftover: multiples of 10 are ideal
        let cls = pr % 10;
        let class_penalty = match cls {
            0 => -12.0,
            5 => 3.0,
            _ => (cls as f64) * 0.8,
        };
        score += class_penalty;
    }

    // Integer-division thresholds: can next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward, scaled by how tight the fit is
            let tight = (pr - next_item_size) as f64;
            score -= 8.0 + 10.0 * (1.0 - tight / cap);
        } else {
            // lookahead cannot use this leftover: penalize proportionally
            score += 6.0 + 0.05 * (next_item_size as f64);
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless residuals are poor
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let mean_frac = mean_residual / cap;
        // open new bin when existing residuals are fragmented and many bins open
        score += 15.0 - 25.0 * mean_frac - 2.0 * open_f.min(10.0) as f64;
        // but if this is the last chance scenario it's fine to open
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Progress: slightly prefer compacting early, exploiting slack late
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: post_residual that is too small to be usable
    // (smaller than the minimum plausible item) is wasted space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        // Unusable gap for the known next item -> penalize heavily,
        // scaled by how small the gap is relative to capacity.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 150.0 * (1.0 - gap_frac);
    }

    // Gap that cannot fit the next item but is large enough for future
    // unknown items is only mildly wasteful; small reward for keeping gaps
    // that still fit the lookahead item (chained placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    }

    // Last-chance bin pressure: if this is the only bin that fits,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it attractive only when the
    // item is large relative to residuals elsewhere, otherwise penalize
    // opening new bins slightly so existing bins get filled first.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * mean_residual;
        // Large items are safer in a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Mild alignment with mean residual: bins below mean residual are
    // already tight; favor them to consolidate space.
    score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving residual that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if the next item fits snugly into the post residual.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally.
            score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins with residual below the mean (tight packing), penalize outlier-large residuals.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 15.0;
    }

    // Slight preference for filling bins tighter as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Reward near-perfect fits (small post residual).
    if post_residual < 5 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is barely above item size.
    let fit_tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_tightness).max(0.0) * (1.0 - fit_tightness).max(0.0);

    // Penalize dead space: post_residual too small for any plausible future item (min 1).
    if post_residual < 1 {
        score += 50.0;
    } else {
        let usable = post_residual as f64 / bin_capacity as f64;
        if usable < 0.10 {
            score += 40.0 * (1.0 - usable / 0.10);
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when current open bins are crowded.
    if bin_residual == bin_capacity {
        let avg_load = bin_capacity as f64 - mean_residual;
        let crowded = mean_residual / bin_capacity as f64;
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Open a new bin only if open bins are mostly full and many items remain.
        score = 20.0 + 100.0 * (1.0 - crowded) + 50.0 * (1.0 - horizon) - 10.0 / pressure;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // pairing potential in a fresh bin
        }
    }

    // Slight preference for using bins with larger residual when many are open.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early stream: be more tolerant of loose fits (future items may fill gaps).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let fit = item_size as f64 / bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with polynomial coupling to progress
    let mut score = r.powf(1.0 + 2.0 * progress) * (1.0 + progress * fit);

    // Reward near-perfect fills
    score -= (1.0 - r).powf(3.0) * 4.0;

    // Penalize dead space relative to mean residual across open bins
    score += ((r * bin_capacity as f64) - mean_residual).abs() * 0.02 * (1.0 + progress);

    // Last-chance bonus: only bin that fits -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= (1.0 - (post_residual as f64 - nx) / bin_capacity as f64) * 1.5;
        } else {
            score += 0.5 * progress;
        }
    }

    // Mild penalty for opening new bins when many bins are open early
    if bin_residual == bin_capacity {
        score += 0.8 + 1.5 * (1.0 - progress) * (1.0 - fit);
    }

    // Slight preference for bins with larger residuals when item is big
    score -= (bin_residual as f64 / bin_capacity as f64) * fit * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bins whose leftover falls into
    // "small sliver" classes (0..=10, exactly 50, etc.) are strongly rewarded,
    // since they are either perfectly closed or still pairable with mid items.
    let pr = post_residual;
    let pr_class = pr % 10; // decimal harmonic digit
    let pr_quot = pr / 10;  // integer-division threshold tier 0..10

    // Perfect closure: huge reward.
    if pr == 0 {
        score -= 1000.0;
    }
    // Tiny unusable sliver (1..=10): mild penalty — dead space.
    else if pr <= 10 {
        score += 8.0 * (11 - pr) as f64;
    }
    // Slivers that still admit the smallest item class (11..=20): reward.
    else if pr <= 20 {
        score -= 6.0;
    }

    // Tier-based shaping: prefer leaving residuals in mid tiers that future
    // items (10..80) can fill; penalize extremes via quadratic coupling.
    let tier = pr_quot as f64;
    score += 0.7 * (tier - 5.0) * (tier - 5.0);

    // Modulo-10 digit harmony: residuals congruent to 0 mod 10 are "clean"
    // against an item grid that includes multiples of 10.
    if pr_class == 0 && pr > 0 {
        score -= 3.0;
    }

    // --- Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin chains perfectly; reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // Fraction of next item absorbed: harmonic fraction coupling.
            let frac = next_item_size as f64 / pr as f64;
            score -= 40.0 * frac;
            // Penalize leaving residuals that only tiny items can use.
            if pr - next_item_size <= 5 && pr - next_item_size > 0 {
                score += 5.0;
            }
        } else {
            // Next item cannot use this residual: dead-space risk.
            score += 4.0;
        }
    }

    // --- Last-chance logic: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate handling: an empty bin has raw residual = capacity,
    // which already scores high (100). Add pressure so new bins are only chosen
    // when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        // Scale reluctance with stream position and existing bin count.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * progress + 1.5 * open_bins_count as f64;
        // But if existing fits are terrible (huge post sliver), allow opening.
        // (Achieved implicitly: bad open bins carry penalties above.)
    }

    // --- Mean residual context: prefer bins whose residual deviates from the
    // mean toward smaller values (consolidate space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev;

    // --- Item-size harmonic class: large items (integer division > 50) should
    // go into the emptiest-feeling bins; small items tolerate tight bins.
    if item_size > 50 {
        score += 0.3 * (bin_residual as f64 - cap * 0.5);
    } else {
        score -= 0.2 * (bin_residual as f64 - cap * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // since they can only fit tiny items (sizes 1..10).
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Medium gaps (11..=25) are mildly risky: only small items can use them.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward gaps that can still fit the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Gap cannot host the next item: penalize proportionally to wasted potential.
        score += 5.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new empty bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are very fragmented
        // (high mean residual spread) or none fit well.
        score += 30.0 + open_bins_count as f64 * 5.0;
        if mean_residual > 40.0 {
            score -= 10.0; // plenty of slack spread around, still avoid new bin
        }
    } else {
        // Slight preference for tighter bins (lower residual) among open bins.
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Early in the stream, allow slightly more freedom to open bins (future flexibility);
    // late in the stream, squeeze everything into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack proportional to how well the next item fits too.
            let next_leftover = post_residual - next_item_size;
            score -= 20.0 - (next_leftover as f64) * 0.25;
        } else {
            // Placing here strands the next item's fit; penalize wasted potential.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: bins with residual near the item size are good.
    let res_diff = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += res_diff * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when reasonable open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin is acceptable only for large items or when nothing fits well.
        let best_alt = if fitting_bins_count > 0 { post_residual as f64 } else { 1000.0 };
        if item_size >= 50 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 25.0 + 30.0 * (1.0 - progress);
        }
        let _ = best_alt;
        // Penalize new bins more when many bins are already open with slack.
        score += (open_bins_count as f64).sqrt() * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Prefer bins whose residual is close to item size (best-fit sharpening).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 8.0 * (-fit_gap * 6.0).exp();

    // Lookahead coupling: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else if next_item_size >= post_residual && next_item_size <= post_residual + item_size {
            // Next item would have fit had we not consumed space; mild penalty.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to spread usage toward fullest bins.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global pressure: when mean residual is low, conserve tight bins.
    if mean_residual < item_size as f64 {
        score += 2.0 * (item_size as f64 - mean_residual) / bin_capacity as f64;
    }

    // Open-bin count pressure: discourage opening new bins when few exist relative to stream length.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = -20.0 * (1.0 - progress) - 4.0 / (open_bins_count as f64 + 1.0);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: baseline slightly above well-fitting open bins,
        // but attractive when post_residual would be very usable.
        score = 18.0 + post_residual as f64 * 0.9 + new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        score += new_bin_bonus * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Tight-fit reward: strongly favor small post_residual, amplified by progress
    let tight = (1.0 - pr / cap).powi(3);
    score -= 30.0 * tight * (0.5 + progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (progress * progress + 0.3 * progress + 0.1);
    score += 40.0 * poly;

    // Lookahead: reward bins whose residual matches the next item
    if nx > 0.0 && nx <= pr {
        let match_q = (pr - nx) / cap;
        score -= 12.0 * (1.0 - match_q).powi(2);
    } else if nx > 0.0 {
        // penalize residual that cannot host the next item
        score += 6.0 * (nx - pr) / cap;
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 {
        score -= 5.0;
        if prn > 0.5 {
            score += 10.0 * prn;
        }
    }

    // Discourage proliferation of open bins with large residuals
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).powi(2);

    // Slight preference for fuller bins overall
    score -= (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 4 quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 (4 => empty)

    // Reward near-exact fills heavily (class 0 = dead space < 25).
    score -= match class {
        0 => 18.0 + (quarter - post_residual) as f64 * 0.5,
        1 => 6.0,
        2 => 0.0,
        3 => 2.0,
        _ => 0.0,
    };

    // Harmonic compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: residual is reusable by the lookahead item.
            score -= 10.0;
            // Extra reward if next item fits almost exactly (harmonic pair).
            let pair_gap = post_residual - next_item_size;
            if pair_gap <= quarter {
                score -= 8.0 - pair_gap as f64 * 0.2;
            }
        } else {
            // Next item cannot use this residual: penalize proportional waste.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer any bin, tightest fit wins naturally.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 20.0;
        // If the item is small relative to capacity, opening a bin wastes
        // potential; but if no open bin fits well, allow it.
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a bin anyway
        }
        // Late in the stream, prefer reusing open bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins with slack: reuse them instead.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Mild preference for bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Modulo-8 harmonic nudge: residuals that are multiples of 8 tend to
    // pair with common item sizes; reward them slightly.
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny slivers: heavy penalty (dead space).
            score += 30.0 + (10.0 - pr) * 4.0;
        } else if post_residual < 20 {
            // Moderate dead space: moderate penalty.
            score += 12.0 + (20.0 - pr) * 0.8;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Gap that exactly fits the lookahead item: big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + item_size as f64 * 0.1;
    }

    // Open-bin pressure: many open bins -> discourage spreading,
    // favor compacting into existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: it always has post_residual = C - item_size,
    // naturally large; add mild bias so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
    }

    // Late in the stream, tightening reduces leftover fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item's size (creates a perfect fill on the next step).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < 1.0 {
            score -= 60.0; // perfect pairing: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item still fits here: bonus proportional to tightness
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space, more if gap is large
            score += 0.35 * gap;
        }
        // If the NEXT item is huge and this bin is its only hope, protect residual space
        if next_item_size >= bin_capacity / 2 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // last item: strongly prefer the fullest possible placement
        score += 40.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative residual pressure: bins already tighter than average are good targets
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: opening a new bin is wasteful early on; allow it only when
    // open bins would leave very large dead space (post_residual close to capacity use).
    if bin_residual == bin_capacity {
        let waste_threshold = 0.5 * bin_capacity as f64;
        if next_item_size > 0 && post_residual as f64 <= waste_threshold {
            score -= 15.0; // acceptable to open fresh bin when leftover stays usable
        } else {
            score += 25.0 + 30.0 * (1.0 - progress); // discourage new bins early
        }
    }

    // Mild preference for consolidating into fewer bins
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual {
            0.0
        } else {
            (post_residual as f64).sqrt() * 2.0
        };
        score += dead;
    }

    // Lookahead bonus: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins that are much emptier than average (avoid fragmenting many half-empty bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Time horizon: late in the stream, prefer packing into existing bins (avoid opening bins near the end).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 30.0 * progress;
        // Opening a new bin is more acceptable when no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // If item is large, a fresh bin leaves a large usable residual anyway.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Mild preference to fill fuller bins first when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling: post_residual interacts with stream progress
    let coupling = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 30.0 * coupling;

    // Penalize tight fits more as stream progresses (dead space risk grows)
    score -= 20.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: prefer it when open bins have poor fit potential
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 10.0 * progress + 2.0 * openness / (openness + 5.0);
        if post > next_item_size as f64 {
            score -= 8.0; // new bin can host the lookahead item
        }
    } else {
        // Reward bins whose residual aligns with the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / cap);
        }
        // Penalize deviation from mean residual (keeps bin pool homogeneous)
        score += 0.15 * (post - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it falls into.
    let quarter = bin_capacity / 4;      // 25
    let tenth = bin_capacity / 10;       // 10
    let post = post_residual;

    // Dead-space penalty: residuals too small to hold the smallest item (1..tenth)
    // are nearly worthless; penalize superlinearly.
    if post < tenth {
        score += (tenth - post) as f64 * 2.5;
    }

    // Reward landing exactly on harmonic multiples of capacity (perfect packing classes).
    for k in 1..4u32 {
        let mark = k * quarter;
        if post == mark {
            score -= 12.0;
        }
    }

    // Modulo-class coupling: post_residual that is a multiple of the item size
    // suggests future copies of the same item will tile perfectly.
    if post > 0 && item_size > 0 && post % item_size == 0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        if gap < tenth {
            score -= 10.0;
        }
        if gap == 0 {
            score -= 20.0;
        }
    } else if next_item_size > post {
        // Next item won't fit here regardless; mild penalty for stranding space.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral baseline, but discourage opening new bins
    // when the global mean residual is still generous.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
    }

    // Tight-fit bonus: filling most of the residual is excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Progress scaling: later in the stream, waste matters more (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Coupling with next item lookahead: reward residuals that fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item is likely dead space.
        score += 8.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when it beats tight fits.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.15;
    }

    // Slight phase dependence: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small waste.
    else if next_item_size > 0 && post_residual > next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 40.0 - waste.min(40.0);
    }
    // Next item cannot use the leftover: penalize proportionally.
    else if next_item_size > 0 {
        score += 15.0;
    }

    // Favor bins whose residual is close to the mean (avoid stranding outliers),
    // but strongly prefer tight fits relative to mean residual.
    let tightness = (post_residual as f64 - mean_residual).abs();
    score += tightness * 0.15;

    // Last-chance bin: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual != next_item_size { 1.0 } else { 0.0 };
        score = 95.0 + poor_fit * 20.0 + (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that end up with small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating small unusable gaps (dead space) that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Scarcity coupling: if this is the only bin that fits, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count >= 2 {
        // Compete harder among fitting bins: reward tighter fits more.
        score -= 8.0 * tight * (fitting_bins_count.min(6) as f64);
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: residual remains useful for the known next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 10.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: if mean residual is high, prefer consuming the largest residuals first.
    let res_gap = bin_residual as f64 - mean_residual;
    score -= 0.10 * res_gap;

    // Time horizon: early in stream, be conservative (slight penalty for tight fits that
    // strand bins); late in stream, maximize packing density aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * tight * progress;
    score += 10.0 * tight * (1.0 - progress);

    // Open-bin pressure: with many open bins, consolidate (favor filling existing bins);
    // with few open bins, opening a new one is cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * open_pressure * (1.0 - tight);

    // New-bin candidate handling: empty bin is a fallback; make it attractive only when
    // the item is large relative to typical residuals or no good fits exist.
    if bin_residual == bin_capacity {
        score += 18.0; // default penalty: prefer existing bins
        if item_size as f64 > mean_residual + 20.0 {
            score -= 30.0; // item too big for typical leftovers -> open fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // keep room for a bigger follow-up
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with a non-linear (quadratic + quartic) growth
    // so small leftovers are cheap but large dead space is heavily punished.
    let mut score = x + 2.5 * x * x + 4.0 * x * x * x * x;

    // Smooth stream-progress coupling: later in the stream, be stricter about
    // wasted space (bins must close out efficiently).
    let progress_pressure = 1.0 + 3.0 * t * t;
    score *= progress_pressure;

    // Tight-fit reward: subtract proportional to fill ratio, amplified
    // non-linearly by how close the fit is.
    let fill = item_size as f64 / cap;
    score -= 3.0 * fill * fill * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mild preference toward better fits via residual.
        score += 0.5 * (fitting_bins_count as f64).ln() * x;
    }

    // Lookahead coupling: reward leaving a residual that can host the next item
    // exactly; penalize post_residual that is too small to be useful.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usefulness = 1.0 - ((x - nx) / cap.max(1.0)).abs() * 4.0;
        score -= 2.0 * usefulness * (1.0 - x);
        // If post_residual cannot fit the next item, add smooth penalty.
        let can_fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score += (1.0 - can_fit_next) * 1.5 * x * (1.0 + t);
    }

    // New-bin candidate: brand-new empty bin (residual == capacity).
    // It has no waste yet, but opening it costs a bin; make it attractive only
    // when the item is large (poor fits elsewhere would waste more) or when
    // many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        let openness = (open_bins_count as f64).ln_1p();
        score = 4.0 + 6.0 * (1.0 - fill) * (1.0 + t)
              - 3.0 * fill * fill
              - 1.5 * fragmentation * openness * t;
    }

    // Mean residual alignment: prefer bins whose residual is near the item size
    // (smooth kernel), i.e., bins that this item "completes".
    let align = ((mean_residual - item_size as f64) / cap).abs();
    score += 1.2 * align * align;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals in [0,10) are "dead" space,
    // [10,25) poor, [25,50) fair, >=50 excellent.
    let dead = (post_residual < 10) as i32 as f64;
    let poor = ((post_residual >= 10) && (post_residual < 25)) as i32 as f64;
    let fair = ((post_residual >= 25) && (post_residual < 50)) as i32 as f64;
    let good = (post_residual >= 50) as i32 as f64;
    score += dead * 40.0 + poor * 18.0 + fair * 4.0 - good * 6.0;

    // Integer-division harmonic: residual that is an exact divisor-like fit
    // (100 % post_residual small) means future standard items pack cleanly.
    let harmonic = if post_residual > 0 { 100 % post_residual } else { 100 };
    score += harmonic as f64 * 0.35;

    // Modulo-10 classes: residuals that are multiples of 10 are "harmonic bins".
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Last-chance bin: strong reward to use it, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
        // Harmonic pairing: post_residual + next_item near a multiple of 50
        let pair = post_residual + next_item_size;
        if pair % 50 == 0 || pair % 100 == 0 {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when current fit is terrible or
    // no good harmonic class exists.
    if bin_residual == bin_capacity {
        let desperation = dead * 20.0 + poor * 10.0;
        score = 60.0 - desperation - (post_residual as f64 * 0.1);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Progress-aware tightening: late in the stream, prefer tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual >= 10 {
        // Usable residual: mild quadratic penalty to prefer tighter fits.
        score += (post_residual as f64).powi(2) * 0.02;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (item barely fits or leaves big dead space) or too many bins are open.
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = fitting_bins_count > 0
            && (bin_residual.saturating_sub(item_size) > 0
                && bin_residual.saturating_sub(item_size) < 10);
        let pressure = open_bins_count as f64 * 0.5;
        if tight_fit_elsewhere || open_bins_count == 0 {
            score -= 60.0;
        } else {
            score += 80.0 + pressure;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when next item exactly fills the leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize by leftover wasted after both placements.
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 1.5;
        } else {
            // next item cannot use the leftover: dead space penalty.
            score += 40.0 + 0.5 * (post_residual as f64);
        }
    }

    // Prefer bins tighter than average residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: neutral-to-high score so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 250.0 + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time progression factor (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving small unusable residuals (< 10 is dead space for future items)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // Penalize placements that leave a residual just below the next item size
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins (tight packing): relative fill ratio
    let fill_ratio = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Prefer bins below mean residual (i.e. fuller than average)
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only open a new bin when fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        let mut new_bin_score = 30.0;
        // If no open bin fits well (item large relative to residuals), encourage opening
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        // Late in stream, consolidate instead of opening bins
        new_bin_score += 20.0 * t;
        // Many open bins -> discourage opening more
        new_bin_score += 2.0 * open_bins_count as f64;
        // Large items benefit from fresh bins early
        if item_size > 60 && t < 0.5 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score + 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: minimize leftover space, with non-linear (quadratic) waste pressure.
    let mut score = post + 0.004 * post * post;

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, dead space is punished more aggressively.
    let prog_coupling = 1.0 + 2.5 * progress * progress + 1.5 * progress * (1.0 - progress);
    score *= prog_coupling;

    // Reward tight fits: interaction between fill ratio and progress.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (nxt / cap) * (1.0 - progress * 0.5);
        } else {
            // post-residual too small for next item: penalize proportionally to waste.
            score += 3.0 * ((nxt - post) / cap) * post / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: mild pressure to consolidate into existing bins.
    score -= 0.8 * (open_bins_count as f64).ln().max(0.0) * fill;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - post) / cap;

    // New-bin candidate: penalize opening a new bin unless current options are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64);
        // But allow new bin if item is large relative to mean residual spread.
        score -= 10.0 * (item / cap) * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Harmonic class of the post-residual: classify leftover into capacity eighths.
    let eighth = cap / 8.0;
    let class = (post / eighth).floor(); // 0..8
    // Dead-space penalty grows superlinearly for large leftover classes.
    score += match class as u32 {
        0 => -30.0,                    // perfect fit, strongly reward
        1 => -12.0,
        2 => -4.0,
        3 => 0.0,
        4 => 6.0,
        5 => 14.0,
        6 => 26.0,
        7 => 42.0,
        _ => 60.0,                     // bin was nearly empty anyway
    };

    // If the leftover class can host the next item, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack_after_next = post - next_item_size as f64;
        // reward proportional to how snugly the next item fits too
        score -= 10.0 * (1.0 - slack_after_next / cap).max(0.0);
    } else if next_item_size > 0 {
        // leftover too small for next item: penalize proportionally to wasted class
        score += 8.0 + 0.5 * post;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else (large item, few alternatives).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_fraction = item / cap;
        // Base cost of a fresh bin, discounted when the item is huge
        // or this bin would be the only fitting option anyway.
        let mut new_bin_cost = 20.0;
        new_bin_cost -= 30.0 * fit_fraction;                       // big items justify new bins
        new_bin_cost -= 15.0 * (1.0 - progress);                   // early stream: bins cheaper
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;                                   // no alternative
        }
        // penalize hoarding bins when many are open with large mean residual
        new_bin_cost += 0.15 * open_bins_count as f64 + 0.1 * mean_residual;
        score = new_bin_cost + post; // post == cap here; offset by cost
    }

    // Mild tie-breaker: prefer bins whose residual is closest to the item
    // (best-fit flavor) via integer-division threshold on residual.
    let div = bin_residual / 10; // decade class
    score += 0.3 * (div as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // tiny unusable gap -> heavy penalty (added to score)
        score += 40.0 + (10 - pr) as f64 * 6.0;
    } else if pr == 0 {
        // perfect fit -> strong reward
        score -= 60.0;
    } else if pr >= 10 && pr <= 20 {
        // gap still usable by typical small items -> mild penalty
        score += 5.0;
    } else if pr > 60 {
        // large residual: flexible, mild reward
        score -= 6.0;
    }

    // Reward exact fill relative to capacity
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no decent fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // pressure: fewer open bins -> new bins cheaper; many open bins -> expensive
        score += open_bins_count as f64 * 1.5;
        // if this bin is the only fitting option, opening new bin is acceptable
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // lookahead: if next item fits in the residual left here, soften cost
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 8.0;
        }
    } else {
        // existing bin: reward keeping mean residual low (consolidation)
        score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
        // lookahead bonus: placing here leaves room for next item?
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        } else if next_item_size > 0 {
            score += 3.0;
        }
    }

    // slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit with the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward when the next item can also fit in this bin after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Dead space relative to what the next item needs.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize post_residual far below mean residual (creating unusable sliver).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.6 * (mean_residual - pr);
    } else {
        score -= 0.15 * (pr - mean_residual);
    }

    // Small residuals are hard to fill: penalize non-zero tiny slivers.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0;
    }
    if pr == 0.0 {
        score -= 20.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: baseline cost of opening a bin; make it attractive
    // only when no open bin offers a good (small) post_residual.
    if bin_residual == bin_capacity {
        let open_penalty = 35.0 + 0.5 * open_bins_count as f64;
        score += open_penalty;
        // If the next item fits perfectly in a fresh bin, ease the penalty.
        if next_item_size > 0 && (bin_capacity - next_item_size) == item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * pr / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large leftover dead space nonlinearly (hard-to-fill slivers).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 0.35 * (pr / 10.0).powi(2);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual == next_item_size) as f64;
        score -= 8.0 * exact + 3.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual {
        // Next item can't use leftover here: penalize leaving medium leftovers.
        score += 2.0 * (post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when item is large or many bins already open.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 20.0;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 6.0 - 4.0 * big_item - pressure.min(3.0);
        // Late in stream, prefer packing into existing bins harder.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 4.0 * t;
    }

    // Global residual state: if mean residual is low, cherish bins that stay usable.
    if mean_residual < 25.0 && post_residual > 0 {
        score += (25.0 - mean_residual) * 0.1;
    }

    // Mild preference to balance load across many open bins.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let pr = post_residual as f64;
    let mut score = pr / cap;
    score += 0.35 * (pr / cap) * (pr / cap);

    // Stream-progress coupling: as stream advances, dead space becomes costlier.
    score += progress * 0.6 * (pr / cap) * (1.0 - pr / cap);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 0.5 * (1.0 - fit_quality) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        // Penalize blocking the next item when slack is scarce.
        score += 0.25 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative
    // to mean residual of open bins (smooth coupling, no piecewise constants).
    if bin_residual == bin_capacity {
        let mean_ratio = mean_residual / cap;
        let size_ratio = item_size as f64 / cap;
        score += 0.8 + 0.5 * mean_ratio - 0.6 * size_ratio * (1.0 + progress);
        score += 0.1 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty when this bin's residual deviates far from mean residual
    // (keeps bin population homogeneous, smooth quadratic term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction it lands in.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer division thresholds: post_residual buckets via capacity/4.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let bucket = post_residual / quarter; // 0..=4 harmonic class

    // Reward near-perfect fills (small post_residual) with a strong subtraction.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= quarter / 2 {
        score -= 120.0;
    } else if bucket == 1 {
        score -= 40.0;
    } else if bucket == 2 {
        score -= 10.0;
    } else {
        // Large dead space (bucket 3-4): penalize beyond the raw residual.
        score += 30.0 * (frac - 0.5);
    }

    // Modulo arithmetic: residual divisible by small integers tends to be reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the post-residual exactly fit or nearly fit the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 150.0; // perfect two-item chain
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 60.0; // tight future fit
        } else if pr >= nxt {
            score -= 15.0; // next item fits loosely
        } else {
            // next item won't fit: residual becomes dead space
            score += 0.3 * (nxt - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when no open bin
    // offers a good fit, or when the stream is young and future items are large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Fresh bin baseline: raw residual is full capacity, so add a penalty that
        // decays as existing bins become crowded (mean residual shrinks).
        score += 0.5 * mean_residual + 20.0 * (1.0 - progress);
        // If many bins are open with slack, discourage yet another bin.
        score += 5.0 * openness.max(0.0).ln().max(0.0);
        // But if the current item is large and next is large too, a fresh bin is fine.
        if item_size >= 50 && next_item_size >= 50 {
            score -= 90.0;
        }
        // Never open a new bin when a tight fit exists elsewhere: fresh bin is costly.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }

    // Mild preference for filling bins with below-average residual (balance avoidance).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Harmonic threshold: residuals in the (half, 3/4) class are the most awkward.
    if post_residual > half && post_residual < 3 * quarter {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
