pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // two-item perfect chain
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a follow-up residual; penalize
            // proportionally to how much slack remains after that.
            let second_left = post_residual - next_item_size;
            score -= 50.0 - (second_left as f64).min(50.0);
        } else {
            // Next item won't fit here: residual is dead for lookahead,
            // penalize small unusable leftovers more.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 30.0 - 3.0 * dead; // tiny slivers are worst
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious.
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness.max(0.0) - 0.1 * (-tightness).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize opening a new bin unless it's
    // genuinely needed (no good fit exists elsewhere).
    if bin_residual == bin_capacity {
        let base_penalty = 350.0;
        // Late in the stream, prefer consolidating into open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base_penalty + 150.0 * progress;
        // Exception: if only one bin fits and it's roomy but the item is huge,
        // a fresh bin may be cleaner — soften penalty slightly.
        if fitting_bins_count == 1 && item_size >= 70 {
            score -= 100.0;
        }
    }

    // Mild preference to fill fuller bins first (best-fit flavor).
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize unusable dead space: residuals too small for typical items.
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score -= 20.0;
        }
        // Dead space penalty grows if residual can't hold the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Lookahead synergy: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial synergy proportional to how well next item fits.
        let synergy = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * synergy;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins fit the item, prefer the tightest one more aggressively.
    if fitting_bins_count > 2 {
        score -= 2.0 * tightness;
    }

    // Global state: if mean residual is high, prefer reusing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize opening new bins unless current item is large
        // and mean residual is too small to be useful.
        let useless_mean = mean_residual < item_size as f64 * 0.5;
        if useless_mean {
            score -= 8.0;
        } else {
            score += 6.0 + 4.0 * (1.0 - progress);
        }
    }

    // Early stream: slightly discourage proliferating bins.
    if open_bins_count > 5 && bin_residual == bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover space, with smooth non-linear emphasis.
    let mut score = pr as f64;

    // Non-linear polynomial coupling: tight fits matter more as stream progresses.
    let tightness = 1.0 - norm_pr; // 1.0 = perfect fit
    let coupling = tightness * tightness * (0.5 + 2.0 * progress);
    score -= 30.0 * coupling;

    // Penalize small-but-nonzero residuals (dead space) with a smooth bump:
    // residual in (0, ~15) is nearly useless; model as quadratic in normalized space.
    let dead = (1.0 - norm_pr / 0.15).max(0.0);
    if norm_pr < 0.15 {
        score += 12.0 * dead * dead;
    }

    // Lookahead: reward if next item fits into post_residual (smooth, not binary).
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        let slack = (pr - next_item_size as f64).abs();
        let fit_term = if fits { -1.0 } else { 1.0 };
        score += fit_term * (8.0 + 10.0 * (1.0 - slack / cap).max(0.0)) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly when decent fits exist, more so early on.
    if bin_residual == bin_capacity {
        let decent = (fitting_bins_count > 0) as f64;
        score += (18.0 - 10.0 * progress) + 20.0 * decent * (1.0 - progress);
        // Prefer new bin if mean residual across open bins is very low (all bins nearly full).
        let mean_tight = (1.0 - mean_residual / cap).max(0.0);
        score -= 15.0 * mean_tight * mean_tight;
    }

    // Mild diversity bonus: spreading load across bins when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by magnitude
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted
    let class: f64 = if post_residual == 0 {
        0.0
    } else if post_residual <= 10 {
        1.0 // tiny dead space, nearly unusable
    } else if post_residual <= 25 {
        2.0 // small but sometimes usable
    } else if post_residual <= 50 {
        3.0 // medium
    } else {
        4.0 // large residual, bin still flexible
    };
    score += class * 12.0;

    // Modulo-arithmetic harmonic thresholds on post_residual:
    // residuals that are multiples of common item sizes are more reusable
    if post_residual > 0 {
        let mut reusable = false;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80].iter() {
            if post_residual % m == 0 && post_residual >= *m {
                reusable = true;
                break;
            }
        }
        if reusable { score -= 25.0; }
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // extra reward if next item nearly fills the residual
        if post_residual - next_item_size <= 5 {
            score -= 30.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize leaving a residual that traps it
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening new bin is OK early, costly late (many half-empty bins)
        score = cap * (0.6 + 0.4 * progress);
        if open_bins_count == 0 {
            score -= 500.0;
        }
        // avoid opening new bin if a good fit exists elsewhere
        if post_residual == 0 && item_size == bin_capacity {
            score -= 1000.0;
        }
    }

    // Prefer bins with below-mean residual (tighter packing)
    score -= (mean_residual - pr).max(-50.0).min(50.0) * 0.3;

    // Slight preference for fuller bins overall
    score -= (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range gaps that few typical items can fill are also dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it less attractive unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item can fit into the post residual,
    // reward this placement (keeps the chain going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: bins far below the mean residual are already
    // fragmented; placing here is fine, bins above mean should absorb items.
    if bin_residual as f64 > mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can hold the next item at all -> moderate reward
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Post residual cannot hold next item: penalize if it wastes a large gap
    else if next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward tight fits: small post_residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize placements into bins with residual far below mean (wasting large bins)
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.2;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Slight preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New-bin candidate: only attractive if no open bin gives a good fit
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual == next_item_size;
        if good_fit_exists {
            score += 0.0; // neutral, open bins handled above
        }
        score += 60.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            score -= 150.0; // opening new bin is fine if existing fit is last-chance anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty grows for large waste.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if next item
    // would be wasted in the leftover, penalize leaving awkward gaps.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        if next_fits {
            let gap_after_next = post_residual - next_item_size;
            score -= (gap_after_next as f64) * 0.3;
        } else {
            // Leftover dead space relative to next item
            score += (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)) * 0.15;
            // If post_residual is smaller than the smallest plausible item, it's dead space
            if post_residual < 5 {
                score -= 8.0;
            }
        }
    }

    // New-bin candidate logic: opening a bin is penalized when good fitting bins exist,
    // but attractive when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin, discounted late in the stream (sunk bins anyway).
        let mut nb = 60.0 * (1.0 - 0.4 * progress);
        // If many fitting bins exist, discourage opening a new one.
        if fitting_bins_count > 0 {
            nb += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If this bin (best existing) leaves lots of waste, opening fresh is relatively fine.
        nb -= 0.0;
        score += nb;
    } else {
        // Slight preference for fuller bins when several fit (best-fit reinforcement).
        score += (bin_residual as f64) * 0.05;
        // Crowding control: with many open bins, prefer consolidating into emptier ones less.
        if open_bins_count > 8 {
            score -= (open_bins_count as f64).log2() * 2.0;
        }
    }

    // Global residual state: if mean residual is high, we have slack; be pickier (raise scores
    // of loose fits). If mean residual is low, accept decent fits.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: waste after placement, mildly discounted as stream progresses
    let mut score = pr * (1.0 - 0.3 * progress);

    // Smooth non-linear penalty for residual that is neither small nor full-bin-sized:
    // dead zones around mid residuals get quadratic/cubic shaping.
    let mid = (norm_pr - 0.5).powi(2);
    score += 40.0 * mid * (1.0 - progress) * (1.0 - fit);

    // Cubic coupling: residuals that leave awkward gaps (< next item) are penalized smoothly.
    let nx = next_item_size as f64 / cap;
    let gap = if next_item_size > 0 { nx - norm_pr } else { 0.0 };
    if gap > 0.0 {
        score += 60.0 * gap * gap * (0.5 + progress);
    } else if next_item_size > 0 {
        // Reward bins that can also host the next item, scaled by snugness of current fit.
        score -= 25.0 * (-gap) * (1.0 - (fit - norm_pr).abs());
    }

    // Last-chance bonus: unique fitting bin gets strong smooth reward.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Diversification: when many bins share residual mass, prefer tighter bins.
    score += 0.5 * (mean_residual - pr).abs() * (open_bins_count as f64).sqrt().min(5.0);

    // Slight preference for keeping many open bins consolidated early.
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate shaping: empty bin scored mildly against tight fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 10.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small dead space are golden
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, close the bin
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 8.0;
    }

    // Modulo classes: residual divisible by common item sizes is reusable
    if pr > 0 {
        let mut reusable = false;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 10.0;
        } else {
            score += 4.0; // awkward leftover
        }
    }

    // Coupling with next item: post_residual that can host the lookahead is valuable
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // exact match to lookahead is best
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: any bin works, prefer tightest
        score -= 20.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Penalize opening new bins when good alternatives exist; encourage when crowded
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - step_index as f64 / total_items.max(1) as f64).max(0.2);
        if fitting_bins_count > 0 && post_residual >= bin_capacity - 20 {
            score += 20.0; // don't open a bin when a near-full bin exists
        }
    }

    // Prefer filling bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64).abs() * 0.15;
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 6.0; // tiny leftovers are wasted space
    } else if dead >= 10.0 && dead < 20.0 {
        score += (20.0 - dead) * 2.0; // moderately awkward gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }
    // Penalize if next item would be blocked by a small residual.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0 + 15.0;
        // Early in stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Slight preference to fill bins with low residual (tighter bins first).
        score += (bin_residual as f64) * 0.05;
    }

    // Coupling with mean residual: placing into a bin below average residual
    // (i.e., tighter than average) is preferred to consolidate fullness.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item size well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // Perfect chain: next item exactly fills the bin afterwards.
            if gap == 0.0 {
                score -= 500.0;
            } else if gap <= 10.0 {
                score -= 150.0;
            } else {
                // Gradual penalty as the leftover after the pair grows.
                score -= 100.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's residual at all: penalize
            // proportionally to how much dead space remains.
            score += 0.5 * (next - pr).min(60.0);
        }

        // Pair-fit quality relative to capacity: prefer placements where
        // item + next item nearly fill the bin.
        let pair = item_size as f64 + next;
        if pair <= bin_capacity as f64 {
            let pair_fill = (bin_capacity as f64 - pair) / bin_capacity as f64;
            score -= 60.0 * (1.0 - pair_fill);
        }
    }

    // Last chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin for a large item.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Progression: early in the stream, be slightly more willing to open
    // bins (spread items); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: only attractive when nothing fits well
    // (post_residual of an empty bin is large, so it scores high by
    // default; add a small extra penalty so open bins with decent fits
    // win, unless they are terrible).
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the item is huge relative to capacity and mean residual
        // is small, opening fresh is reasonable: soften the penalty.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize opening a new bin when existing bins can fit, unless the fit is poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let poor_fit = post_residual as f64 > mean_residual;
            if poor_fit {
                score -= 5.0; // allow opening when all fits are bad anyway
            } else {
                score += 25.0; // discourage opening when a decent fit exists
            }
        } else {
            score -= 50.0; // no alternative: new bin is best
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 20.0;
    }

    // Lookahead: if the next item could fill this bin's post-residual exactly, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 40.0;
        } else {
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving a medium dead zone.
        if post_residual > 0 && post_residual < 20 {
            score += 10.0;
        }
    }

    // Global state coupling: prefer filling bins when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in the stream, be more willing to open bins (flexibility);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mean residual anchor: bins far below mean residual are worth filling.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // early on, moderate residuals are tolerable; late, we punish them quadratically.
    let coupling = norm_pr * norm_pr * (0.5 + 2.5 * progress * progress) * cap;
    score += coupling;

    // Smooth cubic penalty for very large residuals, damped early in the stream
    score += norm_pr * norm_pr * norm_pr * cap * progress;

    // Reward tight fits: smooth bell around zero post-residual
    let tightness = (-norm_pr * 8.0).exp();
    score -= 12.0 * tightness * (0.6 + 0.4 * progress);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (-slack / 30.0).exp();
    } else if next_item_size > 0 {
        // penalize if next item cannot use this residual, scaled by closeness
        let gap = (next_item_size - post_residual) as f64;
        score += 3.0 * (-gap / 20.0).exp();
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Slight preference to spread across bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: make empty bin mildly attractive only when
    // nothing fits well (post_residual of empty bin = capacity)
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "clean" slots.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure — ideal
    } else {
        // Residual mod 10 class: multiples of 10 are reusable by typical item sizes.
        let class = pr % 10;
        score += (class as f64) * 1.5; // ragged residuals penalized
        // Very small dead space (< 10) is nearly worthless.
        if pr < 10 {
            score += 25.0;
        } else if pr <= 20 {
            score += 8.0;
        }
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 20.0;
            // Harmonic bonus: next item exactly divides the residual class
            if pr % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
            // next item leaves a clean multiple-of-10 residual too
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // residual too small for lookahead item: dead-end penalty
            score += 12.0 + (pr as f64) * 0.3;
        }
    }

    // Exact fit of current item into residual.
    if item_size == bin_residual {
        score -= 45.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Best-fit flavor: tighter residual preferred among many candidates.
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // New-bin candidate handling: only attractive early or when open bins are crowded with big residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        score = 40.0 + crowding * 30.0 - progress * 25.0;
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 20.0; // pairing large items in a fresh bin is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the minimum item (size 1) usefully,
    // i.e., gaps below a small threshold are penalized quadratically.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // penalize gaps that are small relative to capacity
        let small_gap_threshold = 15.0;
        if gap < small_gap_threshold {
            score += (small_gap_threshold - gap).powi(2) * 1.5;
        }
        // large leftover space is mildly penalized (wasteful placement)
        score += gap * 0.1;
    }

    // Reward using a bin whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open bins pressure: discourage spreading across many bins unless fit is good
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.05 + 0.1 * (1.0 - progress));

    // Mean residual coupling: prefer bins whose residual is below mean (more filled bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would NOT fit in post residual but fits in current residual,
    // penalize consuming space needed by the next item
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 5.0;
    }

    // New-bin candidate baseline: empty bin gets a neutral-ish but slightly
    // penalized score so it's chosen only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in stream or many open bins: opening new bins is cheaper
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Perfect 2-step match: post_residual exactly fits the next item
    if next > 0.0 && post == next {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    if next > 0.0 && next <= post {
        score -= 30.0 * (1.0 - (post - next) / cap);
    }
    // Next item does NOT fit this residual: penalize proportionally to wasted potential
    if next > 0.0 && next > post {
        score += 10.0 * ((next - post) / cap);
    }

    // Favor bins whose residual is already below average (tight packing)
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= 8.0 * (mean_residual - bin_res) / cap;
    } else {
        score += 8.0 * (bin_res - mean_residual) / cap;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving large dead space relative to capacity
    score += 20.0 * (post / cap) * (post / cap);

    // Late in the stream, prefer closing out bins (use existing space aggressively)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / cap);

    // New empty bin candidate: penalize mildly unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if next > 0.0 && item_size as f64 + next <= cap {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fills are perfect, small post-residuals are good.
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    score -= tight_bonus;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead: reward bins whose leftover can host the next item,
            // scaled by how snugly the next item would fit.
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 18.0 * snug;
        } else if next_item_size > 0 {
            // Leftover too small for the next item: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing space.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln();
        if bin_residual >= item_size {
            score -= 4.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be conservative (favor good fits);
    // late in the stream, accept looser fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: if open bins are generally full,
    // opening a new bin (large residual) should look less attractive.
    let new_bin = (bin_residual == bin_capacity) as f64;
    if new_bin > 0.0 {
        let avg_waste = mean_residual.max(0.0);
        // If mean residual is large, existing bins have room; penalize a new bin.
        score += 8.0 * (avg_waste / bin_capacity as f64).min(1.0);
        // But if this is a tight item and mean residual is tiny, new bin is fine.
        score -= 8.0 * (1.0 - (avg_waste / bin_capacity as f64).min(1.0)) * (item_size as f64 / bin_capacity as f64);
    } else {
        // Prefer bins with residual close to the item (best-fit flavor).
        score += 0.05 * (bin_residual as f64 - item_size as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // 0..1 normalized post residual

    // Base: prefer tight fits (small post_residual), slightly sub-linear.
    let mut score = 100.0 * norm_pr.powf(1.5);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate residual slack; late, penalize it strongly.
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress + 3.0 * progress.powf(3.0));
    score += 40.0 * coupling;

    // Reward filling bins well: item_size relative to capacity, weighted by progress.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * (1.0 + progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap < cap * 0.2 {
            score -= 15.0 * (1.0 - gap / (cap * 0.2));
        }
        // Penalize post_residual that is too small for the next item (dead space).
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless post_residual is truly tiny... actually reward using it to prevent bin proliferation.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty proportional to number of open bins (encourage consolidation),
    // modulated smoothly by progress.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (balanced packing), with smooth quadratic term.
    score += 0.05 * (pr - mean_residual).powi(2) / cap;

    // New-bin candidate: empty bin gets a moderate score; only chosen when
    // open bins are bad fits (their scores will be low via tight fits).
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Exact fit: perfect closure, reward heavily. ---
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // --- Harmonic classes on post_residual: small dead space is good, but
        // "perfectly reusable" residuals (multiples of common item sizes) are better. ---
        let pr = post_residual;
        // Class A: residual exactly matches a plausible next-item size (1..=80 window).
        if next_item_size > 0 && pr >= next_item_size {
            // Residual can host the lookahead item: strong reward, scaled by how snug.
            let snug = (pr - next_item_size) as f64;
            score -= 60.0 - 0.4 * snug;
        } else if next_item_size > 0 && pr < next_item_size {
            // Residual cannot host lookahead: penalize proportionally to the gap.
            score += 0.5 * (next_item_size - pr) as f64;
        }

        // Integer-division thresholds: classify residual into harmonic buckets.
        let bucket = pr / 10; // decile of capacity
        match bucket {
            0 => score -= 40.0,           // 1..=9 : nearly closed, great
            1 => score -= 20.0,           // 10..=19: still very reusable
            2 | 3 => score -= 5.0,        // 20..=39: moderately useful
            4 | 5 => score += 3.0,        // 40..=59: mediocre
            6 | 7 => score += 8.0,        // 60..=79: wasteful for small items
            _ => score += 15.0,           // 80..=99: nearly empty bin left open
        }

        // Modulo-arithmetic coupling: residuals divisible by 5 or 10 tile better
        // against typical integer item sizes.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Odd awkward residuals (prime gaps like 7, 13, 17...) get a small penalty.
        if pr % 2 == 1 && pr % 5 != 0 {
            score += 2.0;
        }
    }

    // --- Last-chance bin: strongly favor using the only bin that fits. ---
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins fit: prefer best-fit competition to dominate.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // --- New-bin candidate handling. ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive early (waste accumulates over long streams),
        // cheaper late when few placements remain.
        let open_cost = 120.0 * (1.0 - progress);
        // If the item is huge relative to capacity, a fresh bin is fine (clean fit).
        let size_relief = (item_size as f64 / bin_capacity as f64) * 40.0;
        score += open_cost - size_relief;
        // If no open bin could fit, the new bin is the only option: cancel the cost.
        if fitting_bins_count == 0 {
            score -= open_cost + 200.0;
        }
        // Never open a new bin for tiny items when any bin fits.
        if item_size <= 20 && fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // --- Mean-residual coupling: avoid deepening an already-fragmented fleet. ---
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // --- Late-stream consolidation: near the end, close bins aggressively. ---
    if progress > 0.8 {
        score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Tight fit reward: residual just below next typical item size.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening a new bin when
    // the item fits an existing bin reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // penalize new bin, scaled by how many alternatives exist
            score += 40.0 + 10.0 * fitting_bins_count as f64;
        } else {
            // forced new bin: neutral-to-good
            score -= 30.0;
        }
    } else {
        // Open-bin pressure: prefer filling bins when many are open.
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits, slight penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Late-stream urgency: close out bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next_item_size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect match: strong reward.
        score -= 12.0 * (-diff / 6.0_f64.max(nxt * 0.3)).exp();
        // Penalize leaving a gap that neither fits the next item nor is tiny.
        if post < nxt {
            score += 0.4 * (nxt - post);
        }
        // Reward creating exactly-next-item space strongly when diff is zero.
        if diff == 0.0 {
            score -= 8.0;
        }
    }

    // Penalize dead space: small unusable residuals that no small item could use.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = pr < 10.0 || (next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() > 15);
        if !bad_fit && fitting_bins_count > 0 {
            score += 6.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Leftover is dead space w.r.t. the next item.
            score += 4.0 + 0.10 * (next_item_size as f64 - post_residual as f64);
        }
        // Chain fit: residual fits both remaining after next item? (rare, reward)
        if post_residual >= 2 * next_item_size {
            score -= 3.0;
        }
    } else {
        // Last item: pure best fit.
        score -= 6.0 * tightness;
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize new-bin candidate unless existing residuals are unusable.
    if bin_residual == bin_capacity {
        let avg_usability = mean_residual / (bin_capacity as f64);
        // Open new bin when open bins are fragmented (mean residual small) or late in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_penalty = 14.0 + 10.0 * (1.0 - avg_usability) + 6.0 * progress;
        score += open_penalty;
        // If many bins could fit elsewhere, strongly discourage new bin.
        if fitting_bins_count > 0 {
            score += 5.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mild pressure to fill crowded bins when many bins are open.
    if open_bins_count > 3 {
        score -= 0.15 * (open_bins_count as f64).min(20.0) * tightness;
    }

    // Slight preference for bins below mean residual (consolidate emptier space).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover waste with a super-linear term (dead space grows costly).
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Reward tight fits: the closer post_residual is to 0, the bigger the discount.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 45.0 * tightness;

    // Smooth stream-progress coupling: as the stream advances, waste tolerance shrinks.
    // Early on, spreading items across bins is fine; late, pack tightly.
    let pressure = 0.5 + 1.5 * progress;
    score *= pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Many open bins -> prefer consolidating into existing bins.
    let open_f = open_bins_count as f64;
    score += 2.0 * (open_f / (open_f + 5.0)) * pr;

    // Lookahead: if the next item can exactly use this bin's post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if pr >= nx {
            score -= 25.0 * (1.0 - gap / cap).powi(2);
        } else {
            // Post-residual too small for next item: mild penalty unless it's near zero.
            score += 8.0 * (nx / cap) * (1.0 - (1.0 - norm_pr).powi(2));
        }
    }

    // New-bin candidate: empty bin leaves a large residual; penalize so it's only
    // chosen when no decent existing fit exists (its raw residual is already high).
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    // Mean residual context: when open bins are generally roomy, prefer filling them.
    let mr = mean_residual / cap;
    score -= 10.0 * mr * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by
    // integer division thresholds and capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // fraction of capacity left after placement

    // Modulo arithmetic classes on post_residual (harmonic buckets of 25)
    let class = post_residual / 25; // 0: <=24, 1: 25..49, 2: 50..74, 3: 75..99, 4: full bin
    match class {
        0 => { score -= 30.0 * (1.0 - post_frac); } // near-full: excellent fit, reward strongly
        1 => { score += 8.0; }                      // small awkward gap: mild penalty
        2 => { score -= 5.0; }                      // half-class: decent
        _ => { score += 12.0 * post_frac; }         // mostly-empty bin used: penalize waste
    }

    // Exact-fit resonance via modulo 10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0; // residual divisible by 10 likely reusable by future items
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / cap;
            // harmonic alignment: next item's class matches residual class
            if (next_item_size / 25) == class {
                score -= 10.0;
            }
            // penalize leaving a gap next item cannot use well
            let leftover = post_residual - next_item_size;
            if leftover > 0 && leftover < 10 {
                score += 15.0; // creates tiny dead sliver
            }
            score += 4.0 * (1.0 - nfrac);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: keep neutral baseline so it wins only
    // when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; small so good fits beat it
        score = post_residual as f64 + 20.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // large next item: fresh bin attractive
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.8 {
            score += 5.0; // late in stream, prefer closing existing bins
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual,
    // it is "dirtier" than average; prefer placing here to consolidate.
    let diff = mean_residual - post;
    if diff > 0.0 {
        score -= (diff * 0.15).min(10.0);
    }

    // Mild pressure to reduce number of open bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_frac < 0.25) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * mean_residual * (1.0 - progress);

    // 2-step lookahead: reward when the NEXT item exactly fills the leftover space.
    if next_item_size > 0 {
        if post_residual == 0 {
            // Perfect fill now: excellent, strongly reward.
            score -= 60.0;
        } else if next_item_size == post_residual {
            // Next item perfectly fills this bin's remainder: huge reward.
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Next item still fits here: mild reward proportional to how well
            // the pair packs the bin (combined waste).
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.6 * pair_waste;
        } else {
            // Next item cannot use the remainder: penalize dead space creation,
            // worse if the leftover is small and unusable.
            let leftover = post_residual as f64;
            let unusable = (leftover / bin_capacity as f64).min(0.5);
            score += 25.0 * unusable + 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins => discourage opening a new one).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 35.0 + 8.0 * fitting_bins_count as f64;
        }
    }

    // Prefer bins with residual already below mean (consolidating waste),
    // mild coupling with open bin count.
    let res = bin_residual as f64;
    score += 0.15 * (res - mean_residual).abs() * (open_bins_count as f64).ln().max(1.0);

    // Slight preference for bins whose residual is a multiple of common sizes
    // (10, 20, 40) which are likely future item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), but scale relative to capacity.
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= (bin_capacity as f64 - pair_waste as f64) * 0.35;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't reuse leftover: penalize large dead space.
        score += (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0) * 0.2;
    }

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance: only one bin can fit this item; strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize bins whose residual is far below the mean (they are poor donors),
    // reward bins with residual above the mean (keeps big slots available).
    let diff = bin_residual as f64 - mean_residual;
    score -= diff * 0.15;

    // Early in the stream, prefer spreading into new bins less aggressively;
    // late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (open_bins_count as f64) * 0.3;
    score -= progress * 5.0;

    // New-bin candidate: opening a new bin costs an effective penalty that shrinks
    // as the stream progresses or when many bins are open and residuals are small.
    if bin_residual == bin_capacity {
        let new_bin_cost = 45.0
            - progress * 15.0
            - (mean_residual / bin_capacity as f64) * 10.0;
        score += new_bin_cost.max(5.0);
    }

    // Mild penalty for leaving residual that matches no plausible item band.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress * (1.0 - x));

    // Penalize wasted space quadratically, softened early in the stream
    score += 0.5 * x * x * (0.4 + 1.2 * progress);

    // Reward tight fits: subtract when post residual is small
    score -= 0.6 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0 * (1.0 + progress);
    }

    // Scarcity pressure: when few fitting bins, prefer using existing bins
    if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0).ln_1p();
    }

    // Lookahead: bonus if next item fits the post residual (chaining)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 0.4 * (1.0 - n / cap) * (1.0 + progress);
        } else {
            score += 0.2 * (n - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual
    score += 0.1 * (mean_residual / cap) * (open_bins_count as f64).ln_1p() * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it enables good packing
    if bin_residual == bin_capacity {
        score += 1.5 + 0.5 * progress - 0.3 * (fitting_bins_count == 1) as i32 as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that pair well with
    // common small items (mod 10 classes) are penalized less.
    let r = post_residual % 10;
    let residue_bonus: f64 = match r {
        0 => -6.0,               // perfectly reusable slot
        5 => -4.0,               // half-slot friendly
        1 | 9 => -2.0,
        2 | 8 => -1.0,
        4 | 6 => 1.0,
        3 | 7 => 2.0,
        _ => 0.0,
    };
    score += residue_bonus;

    // Integer-division thresholds on post_residual: large leftovers are
    // valuable, tiny leftovers are dead space.
    let q = post_residual / 25;
    score -= match q {
        0 => 0.0,                 // post_residual < 25: nearly dead
        1 => 4.0,
        2 => 8.0,
        _ => 12.0,                // roomy bin stays attractive
    };

    // Coupling: does the next item fit exactly / harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual == next_item_size {
            score -= 15.0;        // perfect lookahead closure
        } else if post_residual % next_item_size == 0 {
            score -= 7.0;         // exact harmonic subdivision
        } else if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;         // leaves a clean residue class
        } else {
            score -= 2.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover: mild penalty scaled by waste.
        let waste_frac = (post_residual as f64) / (bin_capacity as f64);
        score += 6.0 * waste_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the tightest (smallest post residual dominates already).
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a bin is only preferred when the
    // current stream is early or all open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual - post_residual as f64).abs() / mean_residual.max(1.0)
        } else {
            0.0
        };
        // Base cost of a fresh bin, discounted early in the stream or when
        // existing bins are very fragmented.
        let base = 30.0 - 20.0 * (1.0 - progress);
        score = base + fragmentation * 10.0 + post_residual as f64 * 0.1;
    }

    // Slight global pressure to close bins as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Moderate dead space (10..=20) is mildly penalized too.
    if post_residual >= 10 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small but usable residual).
    if post_residual == 0 {
        score -= 60.0; // perfect fit bonus
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item can use the leftover space, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0; // chains into another near-perfect fit
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // leftover likely wasted
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 6.0;
        // But a new bin is acceptable if the item is large and fits nowhere well.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight late-stream conservatism: keep bins open as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize small leftover dead space
            score += 0.5 * post_residual as f64;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 200.0;
    }

    // Prefer bins below mean residual (tighter bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New empty bin candidate: penalize unless no good fit exists
    if bin_residual == bin_capacity {
        score += 250.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Early stream: be more conservative about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (low post-residual), non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap; // dead space quadratic penalty

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            score -= 18.0 * (1.0 - slack_after_next / cap);
            if slack_after_next == 0.0 {
                score -= 25.0; // perfect two-item chain
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 0.08 * (nxt - pr);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when open bins with small residuals exist.
    if bin_residual == bin_capacity {
        // New bin: baseline cost of consuming fresh capacity.
        score += 55.0;
        // More attractive early in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score -= 2.5 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual of open bins is large, opening new bin is wasteful.
        score += 0.25 * mean_residual;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Placing into an existing bin: reward consolidation of fragmented bins.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 12.0 * fill * fill; // prefer filling fuller bins (best-fit-like)
        // Slight bonus when bin residual is far below mean residual (bad bin to keep).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Time-horizon modulation: late in the stream, avoid leaving tiny unusable slivers.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if pr > 0 && pr < 10 {
        score += 15.0 * (0.5 + progress); // slivers are dead weight, worse late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Non-linear polynomial coupling: waste matters more later in the stream
    let waste_weight = 1.0 + 1.5 * p2 + 2.0 * p3;
    score *= waste_weight;

    // Normalize waste relative to capacity (smooth quadratic saturation)
    let cap = bin_capacity as f64;
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small relative to item
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64 + 1.0);
    score -= 12.0 * tightness * tightness;

    // Lookahead: bonus if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let fit_quality = 1.0 - slack / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit: penalize bins leaving large unusable gaps
            score += 3.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New empty bin candidate: penalize unless existing bins fit poorly
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 10.0 * (1.0 - progress);
        // If many bins fit, discourage opening a new one
        let scarcity = if fitting_bins_count > 0 {
            1.0 / (fitting_bins_count as f64)
        } else {
            1.0
        };
        score += base_penalty * (1.0 - scarcity * 0.8);
        // Late in the stream, opening bins is cheaper than wasting space
        score -= 5.0 * p2 * (post_residual as f64 / cap);
    }

    // Mild preference for bins with residuals close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes / halves) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual exactly divisible by 10 or 25 -> reusable slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Class 2: post_residual can host next_item_size (lookahead chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fills this bin exactly afterwards.
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                let chain_left = post_residual - next_item_size;
                score -= 8.0;
                // Penalize awkward chain leftovers via modulo class of chain remainder.
                if chain_left % 10 != 0 && chain_left < 10 {
                    score += 3.0;
                }
            }
        } else {
            // Dead-end: leftover too small for the known next item.
            score += 5.0;
        }
    }

    // Class 3: integer-division thresholds on post_residual relative to capacity.
    let frac = pr / cap;
    if frac < 0.1 {
        // Nearly-full bin: excellent, pack here to close it.
        score -= 10.0;
    } else if frac < 0.3 {
        score -= 3.0;
    } else if frac > 0.7 {
        // Wasting a large residual on a big item is poor.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        // Opening fresh is penalized mildly; becomes attractive if mean residual
        // is fragmented (many unusable small leftovers).
        score += 2.0;
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 3.0; // big upcoming item benefits from a fresh bin
        }
    }

    // Slight preference for tighter fits overall.
    score -= (item_size as f64) / cap;

    // Stream-progression tie-break: later in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (pr / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item are pure waste; penalize them heavily.
    let dead_threshold = 9.0; // smallest plausible item is 1, but typical sizes 10..80
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize "awkward" residuals: too small for the lookahead item even
    // though the current item fits — this bin likely becomes dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward bins that can also host the lookahead item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Perfect-fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction
    // of the residual (best-fit style, non-linear).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; penalize mildly per bin.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make an empty bin attractive only when the item
    // is large relative to capacity or the mean residual is very small.
    if bin_residual == bin_capacity {
        score += 18.0;
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * size_frac * size_frac;
        if mean_residual < 5.0 {
            score -= 10.0;
        }
    }

    // Slight late-stream conservatism: keep residual flexibility early,
    // accept tighter fits as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect two-item packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual >= next_item_size {
            // Bin can also host the next item: reward closeness to exact match.
            score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize proportionally to wasted lookahead.
            score += 0.5 * (next - post_residual as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 20.0;
    }

    // Prefer bins tighter than the mean residual (waste-minimization).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 5.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 3.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless current bins
    // would leave very fragmented space (high mean residual relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if next_item_size > 0 && fragmentation > 0.5 && post_residual < next_item_size {
            score -= 10.0; // open new bin when open bins are too fragmented
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight late-stream tightening: consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // marginal dead space
    }

    // Lookahead: reward bins whose post residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by gap.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.02 * pressure;

    // Prefer bins whose residual is close to mean residual (balanced packing).
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: late in the stream, be conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is huge and no good fit exists.
        score += 10.0 - 6.0 * (item_size as f64 / 100.0);
        if progress > 0.8 {
            score += 5.0 * progress;
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // forced new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr as f64;
    score += 40.0 * (1.0 - x) * (1.0 - x) * x; // penalize mid-range wasted space
    score -= 25.0 * x * x * x;                 // reward near-perfect fills

    // Stream-progress coupling: later in stream, value tight fits more
    let p = progress;
    score *= 0.7 + 0.6 * p * p;                 // scale base score with progress
    score -= 10.0 * p * (1.0 - x) * (1.0 - x);  // late-stream: favor tight fits

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (pr - n) / cap) * (1.0 - p);
        } else {
            score += 6.0 * p * (1.0 - n / cap);
        }
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 8.0 * p;
    }

    // Mean residual coupling: penalize bins far from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * dev / cap;

    // New-bin candidate: make it moderately attractive only when open bins are poor fits
    if bin_residual == bin_capacity {
        score = 30.0 + 0.3 * mean_residual - 15.0 * p * (1.0 - item_size as f64 / cap);
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small denominators) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Class bonus: leftover exactly divisible by common item sizes (5,10,20,25)
    // is reusable; odd leftovers are dead space.
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect fit is ideal
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward leftover
    };
    score += class_penalty;

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the resulting double-leftover
            let inner = if slack % 10 == 0 { -6.0 } else if slack % 5 == 0 { -3.0 } else { 2.0 };
            score -= 8.0 + inner;
        } else {
            // next item cannot use this residual: penalize proportionally to wasted fraction
            score += 6.0 + 10.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    // heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no
    // open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score = cap * 0.85;
        // if the item fills a large share of a fresh bin, opening is reasonable
        score -= (item_size as f64 / cap) * 25.0;
        // if many bins already fit the item, discourage opening another
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).min(6.0);
        }
        // early in the stream, prefer consolidating into fewer bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 8.0;
    }

    // Prefer tighter bins overall: small residual relative to mean is good.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild preference for filling bins that are already mostly full.
    score += (bin_residual as f64 / cap) * 2.0;

    // Small penalty per open bin to encourage closing bins out.
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold coupling on item size: large items want tight fits.
    if item_size >= 50 && post_residual <= 10 {
        score -= 5.0;
    }
    if item_size < 20 && post_residual >= 60 {
        score += 4.0; // small item into a big hole wastes a large bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the smallest plausible item is waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0; // overflow guard (should not happen)
    }
    let dead_zone = 12.0; // gaps below this are hard to fill generically
    if (post_residual as f64) < dead_zone {
        // quadratic ramp-up inside the dead zone
        score += (dead_zone - post_residual as f64).powi(2) * 0.8;
    }

    // Reward near-perfect fits strongly (post_residual close to zero).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly -> reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit in post residual and post residual is small,
    // the leftover is likely dead -> extra penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < dead_zone {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize new-bin opening and favor tighter fills.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= open_pressure * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // New bin is attractive only when this item would leave a bad gap elsewhere
        // or when few bins fit the item.
        let gap_penalty = if (post_residual as f64) < dead_zone { 0.0 } else { post_residual as f64 };
        score = (item_size as f64) * 0.5 + gap_penalty * 0.3 + open_pressure * 2.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative -> new bin is fine
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual >= item_size {
            score -= 8.0; // roomy bin for chaining
        }
    }

    // Mild stream progression: later in the stream, be more conservative about gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    // Mean residual coupling: if mean residual is high, prefer bins that reduce spread
    // (fill below-average-residual bins harder).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or snugly
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 500.0; // chain of perfect fits
            } else if slack < 10 {
                score -= 120.0;
            } else {
                score -= 20.0;
            }
        } else if next_item_size > bin_residual {
            // next item can never fit this bin anyway; residual is dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great chain
    if bin_residual == bin_capacity {
        let mut base = 40.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            base -= 30.0;
        }
        if fitting_bins_count == 1 {
            // an open bin is a last chance; don't open new bin
            base += 200.0;
        }
        score += base;
    }

    // Late in stream: consolidate into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: as the stream advances, become more conservative with open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (waste minimization): squared residual penalty shaping.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0; // extra penalty for large leftover space

    // Lookahead: if the next item fits into the post-residual, this bin stays useful -> reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Perfect chain: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Dead space for the lookahead: penalize proportionally, more so late in stream.
            let gap = (post_residual as f64) - (next_item_size as f64);
            score += gap.abs() * (0.3 + 0.5 * progress);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // rather than opening a new bin (avoids fragmenting the residual elsewhere).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // If many bins fit the item, prefer the one with least waste; add mild competition pressure.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Coupling with global mean residual: placing into a bin below the mean residual
    // (i.e., a fuller bin) is good; placing into a roomy bin wastes global slack.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Early in the stream
    // (or when many bins are already open with slack), prefer new bins for large items;
    // otherwise make the new bin moderately attractive so only poor fits trigger it.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin decreases with stream progress (amortization).
        let open_cost = 30.0 * (1.0 - 0.4 * progress);
        // If existing bins have little usable room (mean residual small relative to item), new bin is good.
        let slack_pressure = (mean_residual - item_size as f64).max(0.0);
        score = open_cost + post_residual as f64 - slack_pressure * 0.5;
        // Late in stream, opening bins is cheap since their residual may still be used.
        if progress > 0.8 {
            score -= 8.0;
        }
        // If only one bin fits and it isn't this one, new bin should rarely win.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Small bonus for perfectly filling a bin.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild waste penalty; late stream: aggressive waste penalty.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_coupling;

    // Quartic dead-space penalty: strongly punish residuals too small for
    // any plausible future item (min item size 1, but small slivers are waste).
    score += 8.0 * x * x * x * x * cap;

    // Reward tight fits: subtract a smooth function of fill ratio.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = if next_item_size <= post_residual { 1.0 } else { 0.0 };
        let gap = (next_item_size as f64 - pr).abs();
        let smooth_fit = (-gap / 40.0).exp();
        score -= 20.0 * smooth_fit * fits_next.max(0.0);
        // Penalize leaving a residual that just barely fails to fit the next item.
        if fits_next == 0.0 && pr > 0.0 {
            score += 10.0 * (-gap / 25.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early on and when
    // existing open bins have ample room.
    if bin_residual == bin_capacity {
        let mean_room = mean_residual / cap;
        score += 40.0 + 60.0 * (1.0 - progress) + 30.0 * mean_room;
        // Allow new bins late in the stream when existing residuals are tiny.
        score -= 50.0 * progress * (1.0 - mean_room).max(0.0);
    }

    // Mild preference for bins with below-average residual (keep big gaps free).
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * diff;

    // Smooth open-bin pressure: discourage spreading across many bins early.
    score += 1.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible into large chunks are valuable; prime-like / odd
    // residuals create dead space.
    let pr = post_residual;
    if pr > 0 {
        // Modulo classes on capacity fractions
        let class = pr % 25; // quarters of capacity
        let class_penalty = match class {
            0 => -30.0,                 // exact quarter multiple: very reusable
            5 => -20.0,                 // 5-friendly
            10 => -15.0,
            15 => -10.0,
            20 => -8.0,
            _ => 0.0,
        };
        score += class_penalty;

        // Integer division thresholds: large residuals are inherently good
        let big = pr / 40; // 0, 1, 2
        score -= big as f64 * 12.0;

        // Small odd residuals are dead space
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 50.0;
        } else if diff <= 5 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > pr {
        // Next item won't fit here; penalize slightly, worse if residual small
        score += (next_item_size - pr).min(30) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Early stream: be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost, discounted when few bins or late stream
        score += 25.0 - progress * 10.0 - (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean residual coupling: if open bins are generally full, prefer packing tight
    if mean_residual < 20.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item (1..~15) are pure waste.
    if post_residual > 0 {
        if post_residual < 15 {
            // Unusable sliver: heavy penalty.
            score += 60.0 + 4.0 * (15.0 - post_residual as f64);
        } else if post_residual < 30 {
            // Marginal gap: moderate penalty scaled by gap smallness.
            score += 15.0 * (1.0 - post_residual as f64 / 30.0);
        } else {
            // Large residual is still potentially useful: mild reward.
            score -= 5.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize increasingly with open bin count.
        score += 25.0 + 6.0 * open_bins_count as f64;
        // But if no open bin fits well (last chance handled below), ease up.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strong reward to avoid opening a bin.
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        if next_fit < 15.0 {
            score -= 35.0; // leaves near-perfect room for lookahead item
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway: slight penalty for wasting space.
        score += 5.0;
    }

    // Progress coupling: late in the stream, tighten bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    // Mean residual context: prefer bins below mean residual (denser bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins with zero or tiny post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else {
        // Penalize unusable dead space relative to smallest possible item (1).
        // Dead space that can't fit a small item is worse.
        let dead = post_residual as f64;
        score += dead * dead * 0.02;
    }

    // 2-step lookahead: reward when the NEXT item fits into this bin's post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here too: excellent chaining.
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 + slack_after_next as f64 * 0.5;
            // Extra reward for a tight 2-item packing.
            if slack_after_next < 10 {
                score -= 100.0;
            }
        } else {
            // Next item won't fit here: mild penalty, but small overflow is okay
            // since other bins or a new bin can take it.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a good fit. Penalize the fresh bin so it's used sparingly,
    // but less when many bins are open (consolidation pressure) or early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        score += 120.0 + 80.0 * pressure - 40.0 * progress;
        // If the item is large and would leave a big hole in any open bin anyway,
        // a fresh bin is less bad.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Relative waste vs mean residual: bins with residual far below mean are
    // tighter; placing there consumes scarce space, so penalize slightly.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res) * 0.15;
    }

    // Prefer fuller bins overall (best-fit flavor).
    score += (bin_capacity as f64 - res) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small unusable leftovers (1..=9) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: bonus if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chaining
        } else if next_item_size < post_residual {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain;
        } else {
            // Next item won't fit here; leftover becomes dead unless large enough to matter.
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // If item is large, a fresh bin gives flexibility for future items.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If mean residual across open bins is high, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
    } else {
        // Slight preference for using bins with more remaining space relative to mean.
        score -= 10.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Time-horizon modulation: early in the stream, be conservative about wasting space;
    // late in the stream, just pack anything that fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits more aggressively as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize large unusable residuals: dead space grows super-linearly when residual
    // is small relative to typical item sizes (item_size, next_item_size).
    let next = if next_item_size == 0 { item_size as f64 } else { next_item_size as f64 };
    let unusable = (next - pr).max(0.0) / cap;
    score += 18.0 * unusable * unusable;

    // Interaction: post_residual vs mean_residual — prefer bins whose residual deviates
    // favorably (smaller) from the mean, with smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Lookahead coupling: smooth polynomial rewarding residual that leaves room for next item.
    let gap = (pr - next).max(0.0);
    score -= 8.0 * (gap / cap) * (gap / cap) * (1.0 - progress);

    // Last-chance bin bonus: smooth sigmoid-like emphasis on scarcity of fitting bins.
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 10.0 * scarcity * (0.5 + progress);
    }

    // Mild pressure against hoarding many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets via integer division
    // Small post_residuals are "good closures" -> reward heavily.
    let pr = post_residual;
    let class = pr / 10; // 0..=10
    let class_reward: f64 = match class {
        0 => 30.0,           // near-perfect fit (residual < 10)
        1 => 18.0,           // 10..19: still fits smallest items
        2 => 10.0,           // 20..29
        3 => 5.0,            // 30..39
        4 => 1.0,            // 40..49
        5 => -2.0,           // 50..59: half-empty bin, wasteful
        _ => -6.0,           // > 60 left: very wasteful
    };
    score -= class_reward;

    // Dead-space penalty: post_residual that no future item (min size 1..10)
    // can pair with well. Penalize residuals in "awkward" classes.
    if pr > 0 && pr < 10 {
        score -= 8.0; // tiny slivers are excellent (near-exact fit)
    } else if pr >= 60 && pr < 90 {
        score += 4.0; // awkward mid-large residual zone
    }

    // Next-item coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic decay of pairing quality
            score -= 12.0 / (1.0 + slack / 10.0);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let over = (next_item_size - pr) / 10;
            score += over as f64 * 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (item_size as f64 / cap) * 8.0;
    }

    // New-bin candidate handling: empty bin gets baseline pulled toward neutral,
    // but should lose to decent fits and win against terrible ones.
    if bin_residual == bin_capacity {
        // neutralize large post_residual penalty for fresh bin (post_residual == cap)
        score += 60.0;
        // early in stream, prefer consolidating into open bins less aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // if many bins already open, new bin is cheaper
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // (fill the outlier bins first to close them).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // Modulo-25 harmonic tiebreak on residual: residues near 0 mod 25 pair well
    // with common item sizes (25/50/75/100).
    let m = pr % 25;
    if m == 0 {
        score -= 6.0;
    } else if m <= 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host even the
    // smallest plausible future item are nearly worthless -> heavy penalty.
    let dead_zone_max = 10.0f64;
    if (post_residual as f64) < dead_zone_max && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / dead_zone_max);
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (tight coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual - next_item_size < 10 {
                score -= 10.0; // lookahead fits almost perfectly too
            }
        } else if post_residual > 0 {
            score += 5.0; // lookahead cannot use this gap
        }
    }

    // Waste ratio shaping: penalize proportionally wasted space.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; with few bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early / few bins, penalized later.
        score += 12.0 * pressure;
        score -= 6.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        }
    } else {
        // Existing bin: reward being one of few fitting options (last chance).
        if fitting_bins_count == 1 {
            score -= 25.0;
        } else if fitting_bins_count == 2 {
            score -= 10.0;
        }
        // Prefer bins tighter than average residual (good fits).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late-stream urgency: squeeze existing bins harder near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: many open bins with large mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let surplus = mean_residual - (bin_residual as f64);
    score += 0.05 * surplus;
    score -= 0.03 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early on, be more willing to open new bins (less penalty on new-bin candidate);
    // late in stream, strongly prefer consolidating into open bins.
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets base cost that shrinks with progress.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to item size (perfect-ish fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - progress) * (1.0 - norm_pr);
    score += 8.0 * poly * (1.0 - progress);

    // Penalize large residuals late in the stream (wasted space compounds)
    score += 12.0 * norm_pr * norm_pr * progress;

    // Reward tight fits, especially when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - ((pr - nx) / cap).abs() * 2.0).max(0.0);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty when many bins are open and residual deviates from mean
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are more reusable.
    let class_bonus: f64 = if post_residual == 0 {
        -60.0 // perfect fit
    } else if post_residual % 50 == 0 {
        -25.0
    } else if post_residual % 25 == 0 {
        -15.0
    } else if post_residual % 20 == 0 {
        -12.0
    } else if post_residual % 10 == 0 {
        -8.0
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: reward if next item fits exactly into the post residual,
    // penalize if next item cannot fit at all (dead space for the next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are
    // too fragmented (small mean residual relative to item size).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual / (bin_capacity as f64);
        if fragmentation < 0.35 && post_residual >= 50 {
            score -= 20.0; // open fresh bin when open bins are nearly full
        } else {
            score += 15.0 + fragmentation * 20.0; // prefer reusing open bins
        }
    }

    // Penalize very small unusable dead space (harmonic bottom class).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild stream-progression pressure to consolidate late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps below the minimum item size are unusable.
    let min_item = 1u32;
    let usable_threshold: u32 = 10; // smallest plausible item size
    if post_residual < usable_threshold {
        // Dead space penalty: scaled by how close post_residual is to 0
        let dead = (usable_threshold - post_residual) as f64;
        score += 25.0 * dead;
    }

    // Penalty for very tight fits that leave near-zero residual (waste of a big chunk)
    if post_residual == 0 {
        score -= 8.0; // perfect fit reward
    }

    // Open bins pressure: penalize opening new bins when many are already open
    if bin_residual == bin_capacity {
        // New-bin candidate
        let pressure = open_bins_count as f64;
        score += 15.0 + pressure * 2.5;
        // If few fitting bins exist, opening a new bin is less bad
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // If next item is large, opening a fresh bin may be good
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Reward using existing bins, especially when they are the last chance
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Slight reward for keeping mean residual balanced (avoid fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // Lookahead: if next item fits into post_residual, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Penalize leaving a residual just below the next item size (blocking)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack left over.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tight fits for the next item; penalize leaving large unusable gaps.
        score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        // Dead space: gap too small for typical minimum item (assume >= 1, but
        // penalize gaps below 10 heavily since stream items were often >= 10).
        if post_residual < next_item_size {
            score += 15.0;
        }
        if slack > 0.0 && slack < 10.0 {
            score += 12.0;
        }
    }
    // Next item does NOT fit here: this bin becomes dead after this placement.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 25.0;
    }

    // Tighten overall: prefer small post_residual relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    // Slight penalty for opening a brand-new bin when open bins exist and fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
        // But allow new bin if current bin would leave a very awkward residual.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize wasted space after placement.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * chain_fill;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let dead = post_residual as f64;
            score += 0.35 * dead;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        if post_residual <= 10 {
            score += 12.0; // tiny unusable sliver in the only fitting bin
        }
    }

    // Reward using bins that are already relatively empty when many bins are open
    // (consolidation pressure), but only mildly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if open_bins_count > 2 {
        let rel = bin_residual as f64 / mean_residual.max(1.0);
        if rel > 1.2 {
            score -= 6.0 * (rel - 1.2).min(2.0) * (0.5 + 0.5 * progress);
        }
    }

    // Late in the stream, be more aggressive about filling existing bins tightly.
    score -= 10.0 * progress * fit_ratio;

    // Penalize leaving large awkward gaps (residuals that few item sizes can use).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // near-dead sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // gap usable by typical small items
    }

    // New-bin candidate: neutral-to-slightly-high baseline; open a new bin only
    // when no open bin offers a good fit. Scale with stream progress: early on,
    // opening bins is cheaper; late, prefer squeezing into existing bins.
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Progress coupling: tighten packing more aggressively as stream advances
    let progress_coupling = (progress * progress) * (pr - mean_residual);
    score += 0.35 * progress_coupling;

    // Dead-space penalty for very small residuals (smooth quadratic)
    if pr > 0.0 {
        let dead = (1.0 - norm_pr) * (1.0 - norm_pr);
        score += 8.0 * dead * norm_pr;
    }

    // Reward using a bin that only this item fits (last chance)
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).abs();
        score -= 5.0 * (1.0 - fit_gap / cap).max(0.0);
    } else {
        // last item: strongly prefer minimal waste
        score += 0.0;
        score -= 2.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score = pr - 3.0 + 10.0 * (1.0 - (pr / cap).min(1.0));
        if fitting_bins_count <= 1 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse bins of dead space
    // class 0: 0 (perfect), 1: 1..=5, 2: 6..=15, 3: 16..=30, 4: >30
    let class = match post_residual {
        0 => 0u32,
        1..=5 => 1,
        6..=15 => 2,
        16..=30 => 3,
        _ => 4,
    };
    score += match class {
        0 => -30.0,
        1 => -10.0,
        2 => 5.0,
        3 => 12.0,
        _ => 18.0,
    };

    // Fractional fill ratio of the bin after placement
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: does the residual still host the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // residual remains usable -> reward, scaled by how snugly next fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 6.0 + 4.0 * snug;
        } else {
            // residual too small for next item -> penalize dead space
            score += 7.0;
        }
    } else {
        // last item: prefer tightest packing, ignore future value
        score -= 4.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            1.0
        };
        // open new bin only when mean residual is small (bins nearly full)
        score += 25.0 * crowd - 12.0;
        // avoid opening bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing ones
    score += 0.15 * open_bins_count as f64;

    // Slight preference for bins whose residual is a "harmonic" multiple class
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0; // residual aligns with typical item granularity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable gap
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else {
        // Usable gap: scale penalty by how tight the fit is
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness * tightness;
    }

    // Penalize gaps that can't fit the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: encourage filling existing bins rather than spawning more
    if bin_residual < bin_capacity {
        score -= 0.8 * open_bins_count as f64;
    } else {
        // New-bin candidate: make it unattractive unless existing fits are terrible
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item needs
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Early stream: slightly favor tight packing to build good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
