pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the fit: reward near-perfect fills strongly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;           // bigger items are more valuable to place
    score += 25.0 * waste_ratio * waste_ratio;         // penalize unusable dead space quadratically

    // Lookahead: if the next item fits into the post-residual, reward this bin
    // (it may absorb both items), otherwise penalize leaving a gap sized
    // awkwardly relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 15.0 * (nxt / bin_capacity as f64);
        } else {
            // gap mismatch: penalize proportionally to how close the gap is
            // to the next item (a "teasing" gap is worst).
            let gap_diff = (post_residual as f64 - nxt).abs() / bin_capacity as f64;
            score += 12.0 * (1.0 - gap_diff.min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer reusing existing ones (consolidation);
    // with few open bins, allow spreading.
    let crowding = (open_bins_count as f64).ln1p();
    score += 4.0 * crowding * waste_ratio;

    // Global residual pressure: if mean residual is small, bins are mostly full,
    // so any fit here is precious.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 10.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very tight fits that strand space); late in the stream, pack aggressively.
    score += 10.0 * (1.0 - progress) * waste_ratio;
    score -= 10.0 * progress * fill_ratio;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is huge relative to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        let big_item_bonus = 20.0 * fill_ratio * fill_ratio;
        let scarcity = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        // Baseline penalty so a fresh bin loses to decent fits, but wins when
        // existing bins would waste a lot.
        score += 35.0 - big_item_bonus - scarcity + 20.0 * waste_ratio.max(0.0) * 0.0;
        // Compare against expected waste in existing bins via mean_residual:
        if mean_residual > (item_size as f64) + 10.0 {
            score += 8.0; // existing bins have room; discourage new bin
        } else {
            score -= 6.0; // existing bins are tight; new bin reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post-residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: squared normalized post-residual weighted by progress
    score += 15.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 20.0 * (1.0 - pr_norm).powi(3) * (0.3 + 0.7 * progress);

    // Penalize bins far from mean residual (fragmentation avoidance), smooth cubic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.abs().sqrt();

    // Last-chance bonus: smooth reward when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits into post-residual (smooth interaction)
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap * gap);
        score += 5.0 * (1.0 - fits_next) * pr_norm;
    }

    // Mild penalty for spreading across many open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common GCDs are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Reward residuals that are "harmonic" (divisible by small moduli => likely reusable).
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 3.0; }
        score -= harmony;

        // Penalize dead space: small odd residuals are hard to fill.
        if pr < 10 {
            score += 40.0 - 4.0 * pr as f64;
        } else if pr > 80 {
            score -= 5.0; // large leftover still flexible
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0;
            } else if next_item_size < pr {
                let slack = pr - next_item_size;
                if slack < 10 { score += 8.0; } else { score -= 3.0; }
            } else {
                score += 6.0; // next item won't fit here anyway
            }
        }

        // Last-chance bin: strongly prefer using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Prefer tighter bins relative to mean residual.
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;

        // Mild pressure to keep open bin count low late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.1 * open_bins_count as f64 * (1.0 - progress);

        // Integer-division threshold: bins whose residual class matches item's complement class.
        if (bin_residual / 10) % 2 == (item_size / 10) % 2 {
            score -= 2.0;
        }
    }

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
            if next_item_size > 0 && next_item_size >= 50 {
                score -= 20.0; // big item coming: fresh bin useful
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more than large residuals (dead space avoidance).
    if post_residual > 0 {
        let small_gap = post_residual < 10;
        let medium_gap = post_residual >= 10 && post_residual < 20;
        if small_gap {
            score += 25.0;
        } else if medium_gap {
            score += 8.0;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 40.0;
        }
        // Residual that exactly matches typical item range is valuable
        if post_residual >= 20 && post_residual <= 80 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // If the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by post-residual but bin_residual could hold it, penalize.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && next_item_size <= bin_residual {
        score += 6.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are scarce
    // or mean residual is very low (nothing useful left).
    if bin_residual == bin_capacity {
        let scarcity = if open_bins_count == 0 { 1.0 } else { 0.0 };
        let low_mean = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (scarcity + low_mean) - 5.0 * progress;
        // Default: opening a new bin is slightly worse than a decent fit
        score += 20.0;
    }

    // Slight preference for tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item fits perfectly into post_residual (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Partial reward: next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
    }
    // Penalize leaving a residual slightly above next_item_size (wasted sliver).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score += 12.0;
    }
    // Penalize post_residual too small to be useful for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Best-fit bias: tighter fit relative to mean residual is preferred.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Discourage opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        score += 50.0 + pressure * 0.2 + open_bins_count as f64 * 0.5;
        // Late in stream, opening new bins is more acceptable (fewer future conflicts).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
        // If nothing else fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization is non-linear).
    let tightness = item_size as f64 / bin_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize leaving dead space that cannot fit typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress); // small slivers worse early
    }

    // Lookahead coupling: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize proportional dead space
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bin where fit is tightest relative to others
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 0 {
        let consolidation = mean_residual / bin_capacity as f64;
        score += 20.0 * consolidation * (open_bins_count as f64).ln().max(1.0);
    }

    // Slight preference for filling fuller bins (lower residual) over emptier ones.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: make it costly unless current fits are all poor.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let poor_fit = tightness < 0.5 && post_residual > 0;
        if poor_fit {
            score -= 15.0 * (1.0 - tightness);
        } else {
            score += 80.0;
        }
    }

    // Time horizon: late in stream, prioritize closing bins tightly.
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: quadratic in normalized post_residual, modulated by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress) * cap;

    // Cubic interaction between fill fraction and progress
    let fill = 1.0 - norm_pr;
    score -= 30.0 * fill * fill * fill * (1.0 - progress) * cap * 0.1;

    // Penalize post_residual that is too small to matter (dead space), smoothly
    score += 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.05;

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        let k = (gap / cap * 4.0).exp() * (-1.0);
        score += 10.0 * k;
    }

    // Last-chance bin bonus (smoothly weighted by scarcity)
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mean residual deviation coupling
    score += 0.3 * (pr as f64 - mean_residual).abs() * (0.5 + progress);

    // Encourage consolidation late in stream
    score -= 5.0 * progress * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual bucketed by capacity/4 quarters
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward tight fits: post_residual in the "dead zone" below smallest plausible item
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual <= quarter / 2 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: residues that pair well with common item sizes
    let r = post_residual % 10;
    if r == 0 {
        score -= 10.0;
    } else if r >= 8 {
        score += 8.0;
    }

    // Harmonic class of next_item_size: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after the pair
            let post2 = post_residual - next_item_size;
            score += post2 as f64 * 0.5;
            if post2 == 0 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here: slight reward for keeping large residual bins
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a mostly-full bin on a small item when many bins fit
    if fitting_bins_count > 3 && item_size < quarter {
        score += 10.0;
    }

    // New-bin candidate: only attractive when current residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual % 25.0) / 25.0;
        score = 100.0 - 40.0 * fragmentation - 20.0 * progress
            + if fitting_bins_count <= 1 { -30.0 } else { 0.0 };
    }

    // Slight preference for bins below mean residual (consolidate emptier space)
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Integer-division threshold: bins whose residual is in [half, half+quarter) get a nudge
    if bin_residual >= half && bin_residual < half + quarter {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize post-residuals that cannot fit typical items (below min item size 1..100 unknown,
    // so use a soft dead-zone curve around small residuals).
    let pr = post_residual as f64;
    score += 0.5 * (1.0 - (pr / 10.0).min(1.0)) * pr;

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward placements leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near/below mean (tighter packing).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Mild progression term to stabilize late-stream behavior.
    score += 0.01 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills post residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }

    // Next item fits with small leftover: good chain
    if next_item_size > 0 && next_item_size < post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= (30.0 * (1.0 - chain_waste / bin_capacity as f64)).max(0.0);
        // penalize large unusable leftovers after chain
        score += chain_waste * 0.3;
    }

    // Next item doesn't fit: post residual becomes dead space; penalize small dead space
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
        if post_residual < 10 {
            score += 20.0; // tiny dead space is worst
        }
    }

    // Last-chance bin: strong bonus to use it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: only attractive when current item barely fits nothing well
    if bin_residual == bin_capacity {
        let tight_fit = open_bins_count > 0
            && post_residual < 15
            && (next_item_size == 0 || next_item_size > post_residual);
        if tight_fit {
            score -= 5.0;
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Late in stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize wasted space, with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward;
    // if post-residual is dead space (too small for next item but nonzero), penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still use the leftover: mild reward proportional to fit quality.
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_fit / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead space: unusable for the next item.
            let dead = post_residual as f64;
            let dead_frac = dead / bin_capacity as f64;
            score += 18.0 * dead_frac * dead_frac * 100.0 / (dead + 5.0);
        }
    }

    // Penalize bins that deviate far from the mean residual: keep residual
    // distribution balanced so future items have compatible targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream: encourage opening/using fresh bins to build a diverse
    // residual portfolio; late in the stream: squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: default penalty so it is only chosen when open bins
        // are poor fits; relax penalty late in the stream or when many bins open.
        let mut new_bin_penalty = 60.0;
        new_bin_penalty -= 25.0 * progress;
        new_bin_penalty -= (open_bins_count as f64).min(20.0);
        // If next item is large, a fresh bin is more attractive.
        new_bin_penalty -= 0.2 * next_item_size as f64;
        score += new_bin_penalty.max(5.0);
    } else {
        // Existing bin: late-stream urgency bonus to fill open bins.
        score -= 20.0 * progress;
    }

    // Slight preference for bins with smaller residuals among equals (fill fuller bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth polynomial coupling of residual waste with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier)
    let coupling = (1.0 + progress) * (post * post) / (cap * cap);
    score += 30.0 * coupling;

    // Cubic interaction: strongly reward near-zero post-residual as stream advances
    score -= 50.0 * (1.0 - norm_post).powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (post - ns).abs();
        if post >= ns {
            score -= 15.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            score += 10.0 * gap / cap;
        }
    }

    // Mild penalty for proliferating bins
    score += 0.3 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: dead space is worse when it
    // falls into a "useless" class relative to typical item sizes.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: residual exactly zero -> perfect packing, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class B: residual too small for the smallest plausible item (1..100
        // range, but small items are common): penalize dead space quadratically.
        let min_useful = 1u32;
        if post_residual < min_useful {
            score += 500.0;
        }
        // Dead-space penalty grows superlinearly for tiny residuals.
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0;
        }
    }

    // Harmonic class via integer division thresholds on post_residual:
    // classify residual into octaves of capacity (12,5% steps).
    let class = post_residual / 13; // 0..7 classes
    let class_penalty = match class {
        0 => 40.0,           // 0-12: nearly dead space
        1 => 22.0,           // 13-25
        2 => 12.0,           // 26-38
        3 => 6.0,            // 39-51
        4 => 2.0,            // 52-64
        5 => 0.0,            // 65-77
        6 => -4.0,           // 78-90: roomy, flexible
        _ => -10.0,          // 91-100: nearly full bin reuse
    };
    score += class_penalty;

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain fit: excellent
        } else if next_item_size < post_residual {
            // reward proportionally, but discount tiny leftovers
            let frac = next_item_size as f64 / pr.max(1.0);
            if frac > 0.7 {
                score -= 60.0 * frac;
            } else if frac < 0.2 {
                score += 15.0; // leaves awkward sliver again
            }
        } else {
            // next item cannot fit here: slight penalty for inflexibility
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin, more so when
    // existing bins fit well (post_residual here == capacity - item_size is
    // maximal, so compare against mean residual).
    if bin_residual == bin_capacity {
        let waste_vs_mean = (pr - mean_residual).max(0.0);
        score += 120.0 + 0.5 * waste_vs_mean;
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 * progress;
        // If many bins are open already, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins tighter than the average (best-fit flavor).
    if bin_residual != bin_capacity {
        let tightness = (mean_residual - bin_residual as f64).max(0.0);
        score -= 0.3 * tightness;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 8.0;
    } else if post_residual > 0 && post_residual % 10 != 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit the minimum
    // item size are wasted space -> heavily penalize.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Lookahead: if the next item can fit into the post-residual, this is a
    // valuable chain placement -> reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item nearly fills the remaining gap.
        if post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }
    // Penalize if next item won't fit here AND we leave a dead gap.
    if next_item_size > post_residual && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (raise score of the empty new-bin candidate implicitly by lowering
    // scores of usable existing bins when open_bins_count is high).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 1.5 * (0.5 + progress);
    } else {
        // New-bin candidate: penalize more when many bins are already open
        // or mean residual is large enough to absorb the item.
        score += open_bins_count as f64 * 2.0;
        if item_size as f64 <= mean_residual {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: exact 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 40.0 - 8.0 * diff as f64;
        } else {
            // penalize residuals that can't host the next item
            if (post_residual as u32) < next_item_size {
                score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
            }
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Penalize large dead space relative to mean residual
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are truly bad fits
    if bin_residual == bin_capacity {
        let waste = if fitting_bins_count > 0 {
            let best_possible = bin_residual - item_size; // residual in some open bin
            (best_possible as f64) - (post_residual as f64)
        } else {
            0.0
        };
        // opening new bin costs ~ a bin's worth of potential; only attractive if
        // all existing fits leave big dead space or no bin fits
        score += if fitting_bins_count == 0 { -1000.0 } else { 45.0 + waste.min(100.0) };
    }

    // Slight preference for fuller bins as stream progresses
    score -= 0.05 * (1.0 - post_residual as f64 / bin_capacity as f64) * (step_index as f64 / total_items.max(1) as f64 + 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind, especially if it's too small for
    // typical future items (dead space below the smallest useful chunk).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain_fit;
    }
    // If next item can't use the post residual at all, mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the
    // current item fits poorly everywhere else. Penalize the empty bin
    // proportionally to how many bins already fit the item.
    if bin_residual == bin_capacity {
        let base_penalty = 8.0 + 6.0 * fitting_bins_count as f64;
        score += base_penalty;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer bins whose residual is close to the mean residual (keeps the
    // pool of usable bins balanced), avoiding fragmentation outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins among equals (lower residual first).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    // Mild load balancing: many open bins -> discourage spreading too thin.
    if open_bins_count > 8 {
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Core: quadratic + cubic penalty on leftover space (dead space is bad).
    let mut score = norm_pr * norm_pr * (1.0 + progress) + 0.35 * norm_pr * norm_pr * norm_pr;

    // Mild linear term so tighter fits always preferred at equal nonlinearity.
    score += 0.15 * norm_pr;

    // Lookahead coupling: reward residual that still fits the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 0.5 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 0.3 * (ni - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when many bins are open, unless the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 0.8 + 0.6 * progress + 0.02 * open_bins_count as f64 - 0.5 * size_frac;
    } else {
        // Reward bins that are tighter than average (consolidating residual mass).
        let dev = (mean_residual - pr) / cap;
        score -= 0.25 * dev.tanh();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals divisible by 10
    // are "usable slots" for typical item sizes; odd/prime-ish residuals
    // tend to become dead space.
    let residual_class = post_residual % 10;
    let class_penalty = match residual_class {
        0 => -14.0,
        5 => -4.0,
        2 | 8 => 3.0,
        1 | 3 | 7 | 9 => 6.0,
        _ => 4.0,
    };
    score += class_penalty;

    // Exact fill is always perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fits (small post_residual) are good, but not if they strand
    // a residual too small for any plausible item (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post residual, strongly reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits: reward proportionally to how well it fills.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fill;
    } else if next_item_size > 0 {
        // Next item would NOT fit here: penalize by how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.15 * miss.min(30.0);
    }

    // Integer-division thresholds on post_residual: bins left with
    // residual in [25, 50) are still valuable half-bins; [10, 25) is
    // marginal; keep a mild gradient.
    let half = post_residual / 25;
    score -= 2.5 * half as f64;

    // Last-chance bin: if this is the only bin that fits, opening a new
    // bin wastes capacity; strongly prefer using it unless the fit is
    // terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer the bin that would be left emptier overall.
        score += 0.02 * (fitting_bins_count as f64 - 1.0) * (post_residual as f64);
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity and open bins are mostly full. Penalize opening a new
    // bin early in the stream or when open bins have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let slack = mean_residual / bin_capacity as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * big_item - 20.0 * (1.0 - slack) - 10.0 * progress;
        // A fresh bin is good if it will be left with a harmonic residual.
        let fresh_post = bin_capacity - item_size;
        if fresh_post % 10 == 0 {
            score -= 6.0;
        }
    }

    // Prefer bins below the mean residual slightly (keeps residual
    // distribution tight, reducing fragmentation spread).
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible future item
    // (sizes >= 1, but practically >= 10 in classic streams) can use are pure waste.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && (post_residual as f64) < dead_threshold as f64 {
        score += 40.0 + 0.5 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap for min-size items
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open bins,
    // allow moderate spreading but keep new-bin cost visible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.15 * bin_pressure * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): only attractive when the item is large relative
    // to capacity and open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 45.0;                       // base cost of opening a new bin
        score -= 55.0 * large_item;          // big items justify fresh bins
        score -= 30.0 * fragmentation;       // fragmented open bins justify fresh bins
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;                   // pairing potential with next item
        }
    }

    // Lookahead coupling: if the next item would exactly fill this bin's post-residual,
    // keep this bin for the pair — penalize consuming it now.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual exactly matches next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post residual can still fit next item: mild bonus proportional to slack
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if post_residual leaves room for another typical item
        let half = next_item_size.min(bin_capacity / 2) as f64;
        if (post_residual as f64) >= half {
            score -= 4.0;
        }
    }

    // Penalize dead space: post_residual smaller than the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Penalize wasting space if next item can't fit here
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or current bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if poor_fit {
            score -= 10.0; // opening fresh bin may be better than fragmenting
        } else {
            score += 20.0 + 30.0 * progress;
        }
        // If only one bin open, prefer using it rather than spreading
        if open_bins_count <= 1 {
            score += 15.0;
        }
    }

    // Slight late-stream tightening: favor filling bins fully as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space non-linearly; small residuals are cheap, large ones costly.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 1.5);
    }

    // Perfect fill check: if next item exactly matches post_residual, huge reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits in post_residual, mild reward for chaining.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit post_residual but is small, residual waste matters more.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        // If next item would fit some other bin anyway, penalize leaving awkward gap.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // here is terrible. New bin has post_residual == capacity - item_size, which
    // is large, so base score already penalizes it; add extra penalty scaled by
    // how many bins already exist (prefer reusing bins as stream matures).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
        // But if no open bin fits well (best post_residual large), new bin is fine:
        // approximate via mean_residual — if mean residual is small, open bins are full.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 35.0;
        }
    }

    // Prefer bins with below-average residual (they're "fuller"), keeping
    // large-residual bins free for future large items.
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.3;

    // Early in stream, be slightly conservative: keep big residual bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += diff * 0.2;
    }

    // Many open bins: encourage consolidation into tighter bins.
    if open_bins_count > 5 {
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with non-linear coupling to stream progress
    let mut score = pr
        + 20.0 * (x * x) * (1.0 + progress)
        - 15.0 * x * (1.0 - progress);

    // Reward tight fits more strongly later in the stream
    score -= 10.0 * (1.0 - x).powi(3) * (0.5 + progress);

    // Penalize creating dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let gap = x - nx;
        if gap > 0.0 {
            score += 25.0 * gap * gap * (0.5 + progress);
        } else {
            score -= 8.0 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (1.0 - progress);
    }

    // Mild penalty for proliferating bins early; encourage consolidation
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 3.0;

    // Prefer bins below mean residual (larger holes) when progress is high
    score += 0.15 * (mean_residual - pr) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions. Leftovers in the lowest quarter are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows superlinearly once post_residual < C/4.
    if pr < cap * 0.25 {
        score += (cap * 0.25 - pr) * 2.5;
    }

    // Harmonic bonus: post_residual divisible by common item-size classes
    // (multiples of 5 and 10) is more reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
        // Small odd leftovers are hard to fill later.
        if post_residual % 2 == 1 && post_residual < 20 {
            score += 4.0;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0; // leftover fillable by smallest items
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; slightly penalize tight fits that
            // strand the lookahead item.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless the
    // current bin fit would be terrible (large dead space or no fit class).
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large relative to capacity and mean residuals
        // are small, opening fresh may be wise.
        if (item_size as f64) > cap * 0.6 && mean_residual < (item_size as f64) {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate: favor existing bins more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 3.0;
    }

    // Prefer bins tighter than the mean residual (better packed bins first).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is more attractive when the next item is large
        // and would leave dead space in any existing bin.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item exactly fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot use the gap: dead space is locked in.
        score += post_residual as f64 * 0.8;
    }

    // Prefer bins tighter than average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward bins whose post-residual can host the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain: post_residual exactly matches next item -> strong reward.
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0) * 0.4;
    } else if next_item_size > 0 {
        // Penalize creating residuals that the next item cannot use (dead space).
        let dead = (next_item_size - post_residual) as f64;
        score += dead.min(40.0) * 0.9;
    }

    // --- Relative fit quality vs mean residual of open bins ---
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;                    // prefer bins tighter than average
    score -= tightness * 25.0;              // prefer tight fills generally

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Many options: mildly penalize to encourage exploring alternatives.
        score += fitting_bins_count as f64 * 2.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well
        // (item barely fits anywhere) or stream is early with many items to come.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if next_item_size > 0 { (item_size + next_item_size) > bin_capacity } else { false };
        let bias = 55.0 + (fitting_bins_count.max(1) as f64) * 8.0 + progress * 20.0;
        if poor_fit || fitting_bins_count == 0 {
            score -= 30.0; // open fresh bin for oversized pair
        } else {
            score += bias; // discourage opening new bins when fits exist
        }
    }

    // --- Small smoothness term: prefer filling larger residuals first ---
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let shape = 1.0 - 0.8 * t + 0.3 * t * t;
    score += 20.0 * (fit_frac * fit_frac) * shape;

    // Penalize wasted residual more as stream progresses
    score += 10.0 * fit_frac * (1.0 - t) * (1.0 - t);

    // Last-chance bin bonus (only bin that fits): reward using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here anyway: mild penalty for leaving awkward gap
        score += 5.0 * fit_frac;
    }

    // Compare against mean residual: penalize bins far above mean waste
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: neutral-ish baseline, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = cap - 30.0 * (1.0 - t) + 40.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space below 10 is nearly unusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += 25.0; // dead space, unusable for any item
    } else if pr < 20 {
        score += 8.0;
    } else if pr < 35 {
        score -= 4.0;
    } else {
        score -= 10.0; // large residual stays useful
    }

    // Modulo-10 harmonic class: residual in the same class as common item sizes
    // (multiples of 10) is more likely reusable.
    let class = pr % 10;
    if class == 0 {
        score -= 6.0;
    } else if class <= 3 {
        score += 3.0;
    }

    // Lookahead: does next_item_size fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic class match: next item lands exactly or nearly
            if pr % 10 == 0 && next_item_size % 10 == 0 && pr == next_item_size {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin; penalize proportional to overshoot class
            let over = (next_item_size - pr) % 20;
            score += 5.0 + over as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tighter bins: deviation from mean residual.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.3;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when this bin would leave bad dead space
    // and many bins are already open.
    if bin_residual == bin_capacity {
        let penalty = 15.0 + 0.15 * open_bins_count as f64;
        if pr < 10 && pr > 0 {
            score -= penalty - 20.0; // allow new bin when fit would be terrible
        } else {
            score += penalty;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize opening a brand-new bin when fitting alternatives exist
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If this bin is the last chance, opening new bin is less bad
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Last-chance bin bonus: avoid wasting this bin's potential
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: mild penalty scaled by count
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residuals below mean (consolidate emptier space elsewhere)
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    } else {
        // Last item: prefer filling existing bins as much as possible.
        score -= 5.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Cost of opening a bin grows with stream progress and open bins.
        let open_cost = 25.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
        // But if the current bin would leave bad dead space, opening is fine.
        let waste_if_here = (bin_residual - item_size) as f64;
        let waste_penalty = if waste_if_here > 0.0 && waste_if_here < 20.0 { waste_if_here * 2.0 } else { 0.0 };
        score = open_cost - waste_penalty;
        // If next item could use the fresh bin's space too, slightly cheaper.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    if mean_residual > 60.0 && post_residual > 30 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling: penalize medium dead space, reward tight fits,
    // modulated by stream progress.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like shape in [0,1]
    score += 8.0 * poly * (0.5 + 0.5 * progress);

    // Reward near-exact fits strongly (smooth exponential-like via polynomial of (1-x))
    let tight = (1.0 - x) * (1.0 - x) * (1.0 - x);
    score -= 14.0 * tight;

    // Interaction with mean residual: prefer bins whose residual differs from mean
    // (filling laggard bins), scaled smoothly by progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.3 + 0.7 * progress);
    score -= 3.0 * dev * (0.5 + 0.5 * progress);

    // Lookahead: bonus if post residual can hold next item (smooth via ratio).
    if next_item_size > 0 {
        let ratio = next_item_size as f64 / cap;
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let margin = ((pr - next_item_size as f64) / cap).max(0.0);
        score -= 6.0 * fits_next * (1.0 - margin) * (1.0 - ratio);
        // Penalize leaving a residual that no typical item would fit (smooth dead-zone)
        score += 4.0 * (x - (x.min(0.1))) / 0.1 * 0.0; // no-op guard, keeps structure
        let unusable = (0.1 - x).max(0.0) / 0.1;
        score -= 7.0 * unusable * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * x);
    }

    // Mild penalty for spreading across many bins early (encourage consolidation later)
    let ob = open_bins_count as f64;
    score += 0.4 * ob * progress * (1.0 - poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the fill ratio: how "complete" the bin becomes.
    // Classes based on integer division of post_residual into capacity octaves.
    let class = (post_residual * 8) / bin_capacity; // 0..7 harmonic class
    let class_bonus: f64 = match class {
        0 => -60.0, // bin nearly full -> excellent
        1 => -35.0,
        2 => -18.0,
        3 => -8.0,
        4 => 0.0,
        5 => 6.0,
        6 => 12.0,
        _ => 20.0, // mostly empty bin used poorly
    };
    score += class_bonus;

    // Reward perfect / near-perfect fits (residual exactly 0 or tiny).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic complement: does next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            // modulo structure of residual vs next item
            let m = post_residual % next_item_size;
            if m <= 2 {
                score -= 20.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.3;
            }
        } else {
            // next item won't fit here; penalize leaving awkward residue
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.5 * (bin_residual.saturating_sub(item_size)) as f64;
    }

    // New-bin candidate handling: empty bin should only win when no good
    // placement exists among open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, a fresh bin is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If many open bins already exist, discourage proliferation.
        score += open_bins_count as f64 * 2.0;
        // If item is large relative to capacity, new bin is fine.
        score -= item_size as f64 * 0.15;
    }

    // Coupling with mean residual: placing into a bin far below mean residual
    // (i.e., consuming a large residual) balances the pool.
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Small tie-breaker noise via deterministic step-based micro-shift.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for the minimum item size (1..100 stream, but
    // practically small slivers) are "dead": penalize them hard, superlinearly.
    let dead_threshold = 9u32; // gaps <= 9 are almost never fillable
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 60.0 * (dead_threshold as f64 - post_residual as f64 + 1.0);
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 80.0;
    } else {
        // Usable leftover: mildly reward small-but-usable gaps,
        // penalize large wasted capacity quadratically.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Reward tight fits (item consumes most of the residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // --- Open-bin pressure: discourage spreading across many bins ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Pull toward bins whose residual is near the mean (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward.
            score -= 12.0;
            // Extra reward if next item fills it exactly.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // Leftover too small for the known next item: mild penalty.
            score += 6.0;
        }
    }

    // --- Last-chance bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // If this is the only bin that fits, avoid opening a new bin.
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline cost of opening a bin.
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is attractive only if no open bin fits well,
        // i.e. many fitting bins exist but all would leave dead space.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // If the only fitting open bin would leave an unusable sliver,
            // prefer the fresh bin.
            if post_residual > 0 && post_residual <= dead_threshold {
                score -= 70.0;
            }
        }
        // Late in the stream, opening bins is cheap (no future amortization needed).
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // bin becomes exactly full next step
        } else if post_residual > next_item_size {
            // residual left over after next item; penalize leftover dead space
            let leftover = (post_residual - next_item_size) as f64;
            score -= 10.0;
            score += leftover * 0.6;
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Relative to mean residual: bins with unusually small residual are precious;
    // avoid wasting a tight bin on a loose fit.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.15;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive early in the stream or when this fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 30.0;
        score = 45.0 + progress * 30.0;
        if poor_fit { score += 10.0; }
        if fitting_bins_count == 1 { score += 25.0; } // don't abandon the last fitting bin
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins with small post residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize dead space relative to typical future item sizes (assume ~mean item ~ (1+100)/2).
    let dead_penalty = (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;
    score += dead_penalty;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 12.0;
        } else {
            // next item cannot fit here; mildly penalize leaving space it would waste
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins (reward using open bins);
    // late in stream, prefer tight fits and opening new bins less aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 8.0 * (open_bins_count as f64).ln().max(0.0);

    // Global state coupling: if mean residual is high, prefer bins below mean residual
    // (balance residuals to keep usable mid-size gaps).
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += dev * 6.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is worthwhile only if the item is large or no good fit exists.
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins moderately; relax penalty when item is big or few fitting bins.
        let mut new_bin_cost = 35.0 + (1.0 - large_item) * 20.0;
        if fitting_bins_count <= 1 {
            new_bin_cost -= 45.0; // no real alternative
        }
        if next_item_size > 0 && next_item_size >= post_residual.max(1) && post_residual == bin_capacity - item_size {
            // next item might still fit in fresh bin leftover; soften
            new_bin_cost -= 8.0;
        }
        score += new_bin_cost.max(0.0);
    }

    // Slight preference for bins whose residual stays "usable" (>= small item min size 1..10 range).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0; // tiny useless sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;
    score -= (fill2 * 6.0 + fill3 * 9.0) * (0.5 + t);

    // Penalize post_residual relative to mean residual (avoid dead space vs fleet average)
    score += 0.8 * (pr - mean_residual).tanh();

    // Lookahead: if next item fits exactly into post_residual, strong bonus
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let nxn = nx / cap;
            score -= 4.0 * (1.0 - (pr - nx) / cap) * (1.0 + t);
        } else {
            score += 1.5 * (nx / cap) * (1.0 - t);
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * t;
    }

    // Mild pressure against accumulating too many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - fill2);

    // New-bin candidate: penalize mildly so real bins preferred unless all fits are poor
    if bin_residual == bin_capacity {
        score += 2.5 + 3.0 * t - 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual in 1..=10 (tiny dead space) -> reward.
    // Class 2: post_residual in 11..=30 -> moderate penalty zone.
    // Class 3: post_residual > 30 -> leftover likely reusable, mild penalty.
    let class = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 30 {
        2
    } else {
        3
    };

    match class {
        0 => { score -= 40.0; }
        1 => { score -= 15.0; }
        2 => { score += 8.0; }
        _ => { score += 2.0; }
    }

    // Modulo-harmonic bonus: post_residual divisible into nice chunks of 10
    // (aligns with capacity fractions) is more reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0;
    }
    // Half-capacity alignment: residual near capacity/2 or capacity/4 is valuable.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == half || post_residual == quarter {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Make it unattractive unless every open bin would leave large dead space.
    if bin_residual == bin_capacity {
        // Base penalty for wasting a fresh bin.
        score += 25.0;
        // But if many bins are open with poor mean residual and this is early
        // in the stream, opening a fresh bin can still be reasonable.
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Progress coupling: late in the stream, prefer closing bins tightly
    // (avoid leaving many nearly-empty bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual > 0 && post_residual <= 20 {
        score -= 6.0;
    }

    // Mild tie-break: prefer bins with residuals close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100, but practically < 10 are nearly
    // unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Residuals that cannot fit the lookahead item are mildly penalized.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect lookahead fit: strongly reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins, especially when few fitting alternatives exist.
    score += 2.0 * open_bins_count as f64;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the last chance bin: strongly prefer using it.
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild bonus for being one of several options (competition resolved
        // by tightness terms).
        score -= 3.0;
    }

    // New-bin candidate: only attractive if it would beat a very poor fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If the new bin can host both this item and the next one exactly,
        // allow it more readily.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (i.e., fuller bins) to consolidate space.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 400.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits here: mild reward proportional to closeness
            score -= (40.0 - diff.min(40) as f64);
        } else {
            // next item won't fit: penalize leaving a gap that traps the lookahead
            score += diff as f64 * 0.5;
        }
    }

    // Compare post_residual relative to mean residual: prefer bins that tighten
    // the residual distribution (avoid many medium gaps).
    let post = post_residual as f64;
    if post > mean_residual {
        score += (post - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer filling bins with low residual relative to capacity (tight packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight penalty for proliferating bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Early in stream: be more willing to open bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large or fits are poor.
        let large_item_bonus = if item_size > bin_capacity / 2 { 30.0 } else { 0.0 };
        score += 120.0 - large_item_bonus - progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly usable space for the lookahead item.
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64)).abs();
        }
    } else {
        // Last item: prefer the fullest possible packing.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when reasonable alternatives exist,
    // but allow it when open bins are crowded (mean residual small).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 20.0 * crowding.max(0.0) + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count <= 1 {
            score -= 35.0; // no good alternative -> open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // fresh bin can host the next large item
        }
    } else {
        // Prefer bins with residual close to item (harmonic fit) over very large ones.
        let slack = (bin_residual - item_size) as f64;
        score += 0.05 * slack;
    }

    // Time-horizon modulation: early in the stream, be conservative with new bins;
    // later, tolerate more slack since future composition is unknown anyway.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let g = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += 6.0 * prn * prn * (1.0 + g) - 3.0 * prn * g;

    // Reward tight fits (small post residual) more strongly as stream advances.
    let tight = 1.0 - prn;
    score -= 8.0 * tight * tight * (0.5 + progress);

    // Penalize leaving dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 5.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 2.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild penalty when bin residual deviates far from mean residual (balance pressure).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate handling: penalize opening a new bin unless post residual is large.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by capacity fraction classes
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = pr / c; // fraction of capacity left

    // Penalize residuals in "dead zone" classes: (0,10] and (50,60] are hard to fill
    let class = post_residual % 25;
    if post_residual > 0 && class <= 10 {
        score += 30.0; // small slivers are dead space
    }
    if post_residual > 50 && post_residual <= 60 {
        score += 15.0; // awkward mid-class residual
    }

    // Reward residuals that are harmonic multiples of common item classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or closely, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 500.0;
        } else if slack <= 10 {
            score -= 100.0;
        } else {
            score -= 40.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving large unusable residual
        score += pr * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer tighter bins when many bins are open (consolidation pressure)
    score -= (c - bin_residual as f64) * 0.2;

    // New-bin candidate: make it attractive only when existing residuals are poor
    if bin_residual == bin_capacity {
        let urgency = (fitting_bins_count == 0) as i32;
        let mean_pen = mean_residual / c;
        score = 40.0 + mean_pen * 50.0 - (urgency as f64) * 200.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 30.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: later in stream, be slightly more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..10)
    // can use are pure waste. Penalize tiny unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize moderate gaps that are below the typical minimum item size band,
    // scaled by how "wasted" they are relative to capacity.
    if post_residual > 0 && post_residual <= 20 {
        score += 0.5 * (post_residual as f64).powf(0.8);
    }

    // Last chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading out.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += open_pressure * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (creates a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item cannot fit in post residual, mildly penalize unless gap is large.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: empty bins should only win when all open
    // bins would leave terrible dead space. Add a moderate baseline penalty
    // so open bins with decent fits win instead.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
    } else {
        // Prefer bins tighter than average residual.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    }
    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward tight fills relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Discourage opening new bins when decent fits exist, especially early/mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0;
    }

    // Mild penalty for very low post-residual unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of the bin filled by this item
    let tightness = item_size as f64 / bin_capacity as f64;

    // Reward tight fits (subtract proportional to how much of the bin the item consumes)
    score -= 30.0 * tightness;

    // Penalize dead space that is too small to be useful later.
    // Items are >= 1, but small post-residuals (< typical item) are likely wasted.
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Non-linear dead-space penalty: peaks for unusable slivers
        let sliver = if dead < 15.0 { (15.0 - dead) / 15.0 } else { 0.0 };
        score += 12.0 * sliver;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item would fit into the post-residual,
    // reward leaving exactly that much room (chained placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize residual that blocks the known next item
        score += 6.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on we avoid bin sprawl; late we accept it more readily).
        let mut new_bin_cost = 20.0 * (1.0 - 0.5 * progress);
        // If many bins fit the item, opening a new bin is less attractive.
        if fitting_bins_count > 1 {
            new_bin_cost += 15.0;
        }
        // If only this new bin "fits", the bonus above already steers here;
        // soften the cost so we don't fail to place the item.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 30.0;
        }
        // If mean residual across open bins is large, prefer packing existing bins.
        new_bin_cost += 0.05 * mean_residual;
        score += new_bin_cost;
    } else {
        // Mild reward for keeping bin count low by using existing bins
        score -= 3.0;
        // Prefer bins whose residual deviates from the mean in a "fillable" way:
        // bins with below-average residual are closer to being closed out.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.03 * dev;
    }

    // Global pressure: when many bins are open, encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: normalized residual raised to a progress-dependent power
    // penalizes large leftover space early (keep bins flexible), tolerates it late (consolidate).
    let norm_res = post_residual as f64 / cap;
    let exponent = 1.0 + 2.0 * (1.0 - progress); // 3.0 early -> 1.0 late
    score += 40.0 * norm_res.powf(exponent) * (0.5 + progress);

    // Perfect / near-perfect fit reward (smooth, not piecewise)
    let fit_quality = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Dead-space penalty: residuals too small for the smallest plausible future item
    let dead = if post_residual > 0 { (1.0 - post_residual as f64 / cap).max(0.0) } else { 0.0 };
    score += 15.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into the post residual (smooth coupling)
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64 - post_residual as f64) / cap;
        if next_fits <= 0.0 {
            score -= 12.0 * (1.0 + next_fits) * (0.5 + progress);
        } else {
            score += 8.0 * next_fits * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (post_residual as f64 - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless existing bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse granularity classes (capacity / 8).
    let class_width = cap / 8.0;
    let post_class = (post_residual as f64 / class_width).floor() as f64;
    let item_class = (item_size as f64 / class_width).floor() as f64;
    let next_class = (next_item_size as f64 / class_width).floor() as f64;

    // Reward placing items into bins whose post residual belongs to a "useful" class.
    // Small post residuals are dead space unless a known next item fits exactly.
    score -= (7.0 - post_class) * 2.0;

    // Harmonic match: does the next item land into the same or compatible class of space?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect modulo-style fit: post_residual % next_item_size small => chainable bin.
        let m = post_residual % next_item_size.max(1);
        let harmony = if m == 0 { 6.0 } else if m <= 5 { 3.0 } else { 1.0 };
        score -= harmony;
        // Extra reward when the next item consumes a large fraction of the remaining space.
        let frac = next_item_size as f64 / post_residual as f64;
        score -= frac * 4.0;
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize leaving large dead space.
        score += post_class * 1.5;
    }

    // Integer-division threshold on item size: big items (>= half capacity) prefer
    // bins with tight fit; small items are flexible.
    if item_size * 2 >= bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= tightness * 5.0;
    } else {
        // Small items: prefer bins with mid-range residuals (avoid wasting large gaps).
        let mid_penalty = ((post_residual as f64 - cap * 0.4) / cap).abs() * 4.0;
        score += mid_penalty;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are
    // crowded (mean residual low) and the item is large.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if crowded {
            score -= 8.0 + progress * 4.0;
        } else {
            score += 15.0;
        }
    }

    // Mild penalty for proliferating open bins when residuals are already large.
    if open_bins_count > 4 && mean_residual > cap * 0.5 && bin_residual < bin_capacity {
        score += 2.0;
    }

    // Tie-break noise-free deterministic micro-adjustment by harmonic class parity.
    if (post_class as i64) % 2 == 0 {
        score -= 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalty grows as post_residual shrinks relative to item_size (tight fits rewarded).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space: post_residual that no future item (min size 1) could use is worst;
    // gap smaller than next item is less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward gaps that can still hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mild pull toward mean residual to keep bins balanced.
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain into the next placement).
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain match: strongly subtract.
        if match_gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize proportional to mismatch, but only if next item could chain.
            score += match_gap * 0.35;
            // If next item cannot fit in post_residual at all, penalize dead space.
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size - post_residual) as f64 * 0.6;
            }
        }
    } else {
        // Last item: prefer minimal final residual.
        score += post_residual as f64 * 0.5;
    }

    // Reward tight fits: small post_residual relative to capacity is good
    // unless it chains with next item (handled above).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 25.0;

    // Last-chance bonus: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all poor (high mean residual means open bins are fragmented anyway).
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if mean residual across open bins is small (bins are tight),
        // opening fresh space is reasonable: reduce the penalty.
        score -= mean_residual * 0.5;
        // Late in the stream, avoid leaving many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Compare against mean residual: bins with residual below mean are more
    // "used up"; prefer filling those to consolidate.
    score += (mean_residual - bin_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that end with small residual (tight fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // how much of the bin's space is consumed

    // Reward tight fits nonlinearly (small post_residual gets super-linear bonus).
    score -= (cap - post) / cap * 30.0 * (0.5 + fit_ratio);

    // Penalize dead space that is too small to be useful later (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // worst kind of leftover
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward leftover zone
    }

    // Lookahead: if the next item can still fit in the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 15.0 * (1.0 - nxt / cap);
        } else {
            score += 8.0 + 10.0 * (nxt / cap);
        }
        // Bonus if post residual exactly leaves a perfect slot for next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to encourage diversity / keep big bins free.
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: prefer filling bins when mean residual is high (fragmentation risk).
    score -= (mean_residual / cap).min(1.0) * 6.0;

    // Time horizon: early in stream, be conservative (favor tight fits less aggressively,
    // keep bins flexible); late in stream, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    // Prefer bins that are already partially filled over nearly-empty ones (reduce bin count).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= fill * 10.0;

    // New-bin candidate: make it unattractive unless the item fits very poorly everywhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if item is huge relative to capacity and would leave tiny residual anyway,
        // slightly soften so a new bin can win when open bins are all bad.
        if item_size as f64 > 0.7 * cap {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let npr = pr / cap;

    // non-linear polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.6 * t - 0.8 * t * t + 0.4 * t * t * t;
    score *= poly;

    // penalize large dead space non-linearly
    score += 4.0 * npr * npr * (1.0 + t);

    // reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - npr) * (1.0 - npr) * (2.0 + 3.0 * t);

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // lookahead: prefer leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 1.5 * (1.0 - ni / cap);
        } else {
            score += 0.5 * (ni - pr) / cap;
        }
    }

    // mild penalty when many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual / cap - npr).abs();

    // new-bin candidate: discourage unless nothing fits well
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are valuable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual, especially when it lands on "usable" harmonic classes
    // (residuals divisible into nice fractions of capacity: 0, 10, 20, 25, 50)
    let harmonic_bonus = if post_residual == 0 {
        60.0
    } else if post_residual % 10 == 0 || post_residual % 25 == 0 {
        18.0
    } else if post_residual % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space that no future item (1..100) can plausibly use:
    // if post_residual is very small but nonzero, it's nearly dead
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic class of the resulting slack
            if slack as u32 % 10 == 0 || slack as u32 % 25 == 0 {
                score -= 12.0;
            } else if slack < 10.0 {
                score += 10.0;
            }
        } else {
            // next item won't fit here; penalize slightly if we'd block it
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        // open new bin when mean residual across open bins is small (bins nearly full)
        score = 40.0 + 60.0 * pressure - if next_item_size > 0 && next_item_size >= bin_capacity { 20.0 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // slight penalty for very full open bins relative to mean (prefer balanced fills)
        if (bin_residual as f64) < mean_residual - 15.0 {
            score += 5.0;
        }
    }

    // Progress-based mild tightening: later in stream, prefer tighter packs
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * harmonic_bonus / 60.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Reward tight fits (small waste relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: discourage scattering when many bins are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits the resulting residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use leftover; penalize proportionally.
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when current fit is poor or item huge.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 10;
        if poor_fit || item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        } else {
            score += 35.0; // keep filling existing bins otherwise
        }
    }

    // Mild stream-progression pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * waste_ratio;

    // Prefer bins below mean residual (keeps a spread of gap sizes).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: reward closeness of the match.
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + gap);
        } else {
            // Next item would NOT fit: penalize proportionally to how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }

        // Chain bonus: residual after hypothetically placing the next item too.
        if post_residual >= next_item_size {
            let after_two = post_residual - next_item_size;
            if after_two == 0 {
                score -= 25.0; // bin perfectly closed over two steps
            } else {
                score -= 10.0 / (1.0 + after_two as f64);
            }
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // --- Relative-to-mean residual shaping ---
    // Prefer bins whose post_residual sits below the mean residual (compact bins),
    // penalize bins that would be left far above the mean (isolated dead space).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.25 * (mean_residual - pr).min(30.0);
    } else {
        score += 0.15 * (pr - mean_residual).min(40.0);
    }

    // --- Last-chance bin protection ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that can fit the item: reward using it
        // to avoid opening a new bin, scaled by how much space is consumed.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: neutral baseline plus a mild reluctance so we
        // only open a new bin when no existing bin gives a decent fit.
        score += 8.0;
        // Open a new bin eagerly if the item is large and fits poorly anywhere,
        // or if there are no other fitting bins.
        if item_size >= 60 || fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Slightly less eager to open bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    } else {
        // Existing bin: reward fuller bins (waste-reduction pressure).
        let used_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * used_ratio;
    }

    // --- Tie-break: prefer closing bins to reduce open-bin clutter ---
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * tightness;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: small post-residual thresholds relative to future items.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or nearly, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (next_item_size as f64) / (post_residual as f64);
        score -= 22.0 * chain_fit;
        if next_item_size == post_residual {
            score -= 35.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Post-residual too small for the next item: mild penalty unless tight fit now.
        score += 6.0 * (1.0 - tightness);
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Prefer a new bin when existing residuals are large and item is big,
        // or when this is a big item late in the stream.
        let progress = step_index as f64 / total_items as f64;
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if mean_residual < item_size as f64 * 1.05 {
            score -= 20.0;
        }
        score -= 10.0 * big_item * progress;
        // Penalize opening new bins early with small items.
        if item_size < 40 && progress < 0.3 {
            score += 15.0;
        }
        // Penalize new bins when many open bins exist (fragmentation risk).
        score += (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Global state: penalize bins whose residual deviates far from the mean (balance pressure).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream consolidation: favor filling existing bins more aggressively near the end.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 12.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth coupling of residual with stream progress: early stream tolerates
    // leftover space less (keep bins tight), late stream rewards tight fits more.
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peak mid-stream
    score *= progress_coupling;

    // Reward near-perfect fits via smooth bell-shaped term around small residuals
    let tight_bonus = (-norm_pr * norm_pr * 12.0).exp() * (1.0 + 3.0 * progress);
    score -= 12.0 * tight_bonus;

    // Penalize residuals that cannot fit the lookahead item (smooth polynomial)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let unusable = if pr < next_item_size as f64 {
            (next_item_size as f64 - pr) / cap
        } else { 0.0 };
        score += 15.0 * unusable * (1.0 - progress);
        // Reward exact chain: residual exactly fits next item
        let chain = (-((pr - next_item_size as f64) / cap).powi(2) * 20.0).exp();
        score -= 8.0 * chain;
        let _ = gap;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_item * 0.5);
    }

    // Slight penalty proportional to number of open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Mean-residual alignment: prefer bins whose residual is below the mean
    // (tighter bins first), smooth quadratic coupling
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division into bands.
    let class = post_residual / 10; // 0..10 harmonic band
    // Penalize odd/dead bands non-linearly
    score += (class as f64) * (class as f64) * 0.35;

    // Reward near-perfect fills strongly
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Modulo coupling: residuals that are multiples of common item sizes are reusable
    let reusable = (post_residual % 10 == 0) as f64 * 12.0
        + (post_residual % 20 == 0) as f64 * 8.0
        + (post_residual % 25 == 0) as f64 * 6.0;
    score -= reusable;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
            // harmonic match: next item shares class with post residual
            if (next_item_size / 10) == class && post_residual >= next_item_size {
                score -= 10.0;
            }
        } else {
            // next item won't fit: penalize slightly based on overshoot band
            let over = (next_item_size - post_residual) / 10;
            score += over as f64 * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: prefer new bin only when existing bins fit badly
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 20.0 * progress;
        // if item is large relative to capacity, new bin is natural
        if item_size >= 50 {
            score -= 15.0;
        }
        if fitting_bins_count > 0 {
            // some bin fits: new bin must beat it, so add pressure
            score += 10.0 + mean_residual * 0.05;
        }
    }

    // Tightness term: prefer bins where item fills a large fraction of residual
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 20.0;

    // Mean residual coupling: when open bins are loose, discourage wasting space
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Mild penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the minimum item (1) are pure waste,
    // but gaps below the typical item floor (~10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty: tiny unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill reward
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize large leftover gaps relative to capacity (wasted space).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins / favor consolidation.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize more as open_bins_count grows
        score += 10.0 + 4.0 * open_bins_count as f64;
        // but early in the stream, opening a bin is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    } else {
        score += 2.0 * open_bins_count as f64 * 0.1; // mild consolidation pressure
    }

    // Lookahead: if next item fits into this bin's post_residual, reward placement here.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // leftover can't host next item: mild penalty scaled by gap size
        score += 5.0 * (post_residual as f64 / 100.0);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    // (placing into below-average-residual bins keeps large gaps available).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 100.0; // perfect chain: bin closed after next item
        } else if (next_item_size as u32) <= post_residual {
            score -= 40.0 / (1.0 + diff);
        } else {
            // next item cannot fit here; mild penalty for leaving awkward gap
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: baseline cost of consuming fresh capacity
        score += 15.0;
        if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
            score -= 20.0; // fresh bin allows perfect chain
        }
        if item_size >= 50 {
            score -= 10.0; // large items are fine in fresh bins
        }
    }

    // Dead-space penalty: tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in stream: prefer closing bins tightly (fewer total bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize residual that is too small to be useful later (dead space).
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 7.0;
    } else if post_residual < 30 {
        score += 2.5;
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 9.0 * fit_ratio;

    // Lookahead: if next item fits in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
            // Extra reward if next item exactly complements post residual.
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 4.0; // near-miss: wasteful pairing
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 8.0);
    score += 1.2 * bin_pressure;

    // Prefer bins whose residual is close to the mean (balance residuals)
    // unless the mean is large (then prefer filling emptier bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early on, be picky about waste; late, accept anything.
    let waste_tolerance = 1.0 + 2.5 * progress;
    score -= waste_tolerance * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or the current bin leaves bad residue.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * big_item;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 6.0; // next item won't pair well with fresh bin either
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= 30.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize large dead space more as stream progresses
    score += 8.0 * (pr / cap).powf(3.0) * (1.0 + progress);

    // Lookahead: reward bins whose post_residual fits next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins unless residual is unusable
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress) - 5.0 * (pr / cap);
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln() * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class penalty: residual that cannot plausibly host future items
        // (item sizes 1..100). Penalize residual classes by divisibility structure.
        let r = post_residual;
        // Class A: r divisible by 10 -> "clean" residual, mildly favorable.
        if r % 10 == 0 {
            score -= 5.0;
        }
        // Class B: small unusable slivers (r < 10) are dead space -> strong penalty.
        if r < 10 {
            score += 60.0;
        }
        // Class C: integer-division thresholds on usable mid-range residuals.
        let q = r / 10; // decade class of residual
        score -= (q as f64) * 2.0; // larger usable residual preferred, graded

        // Fractional-band coupling: reward residuals near harmonic fractions of capacity
        // (1/2, 1/4, 3/4) which pair well with typical item magnitudes.
        let bands = [0.25f64, 0.5, 0.75];
        for b in bands.iter() {
            let d = (frac - b).abs();
            if d < 0.05 {
                score -= 20.0 * (1.0 - d / 0.05);
            }
        }

        // Lookahead harmonic class: does next_item_size divide/match post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item fits exactly or nearly: reward strongly.
                if next_item_size == post_residual {
                    score -= 400.0;
                } else {
                    let nr = post_residual - next_item_size;
                    score -= 50.0;
                    // penalize if next placement creates a tiny sliver
                    if nr < 10 && nr > 0 {
                        score += 25.0;
                    }
                    if nr == 0 {
                        score -= 200.0;
                    }
                }
            } else {
                // Next item cannot use this residual: penalize proportionally.
                score += 15.0;
            }
            // Modulo harmony: next_item_size and residual sharing decade class
            if (next_item_size % 10) == (r % 10) && next_item_size <= r {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 80.0;
        if post_residual < 10 {
            score += 40.0; // still bad to burn a bin for a sliver
        }
    }

    // New-bin candidate handling: empty bin should lose unless open bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty so full bins win; relieved by stream position and crowding.
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            score -= progress * 10.0 + mean_residual * 0.05;
            if crowd > 3.0 {
                score -= 20.0; // many bins, spread load
            }
        }
    }

    // Mild preference for bins below mean residual (tighter packing pressure).
    score += ((post - mean_residual) * 0.1).clamp(-10.0, 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual that is too small to hold even the smallest plausible item (1..10)
    // is pure waste; the smaller it is, the worse.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // dead space penalty up to ~54
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill: strongly reward exact closure
    }

    // Reward tight fits: relative waste ratio
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += (bin_residual as f64 - post_residual as f64).min(1.0) * 0.0; // no-op guard
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // unless current bins would leave big dead space.
        score += 18.0 + 2.5 * pressure;
    } else {
        score -= 4.0; // mild bonus for reusing an open bin
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (avoid opening a new bin for an item that fits nowhere else).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward proportional to leftover after next
        let after_next = post_residual - next_item_size;
        if after_next < 10 && after_next > 0 {
            score += 4.0; // would create dead space next step: slight penalty
        } else {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: if this bin's post-residual deviates far below
    // the mean, it's becoming an outlier of waste; penalize.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins and more aggressive about filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            // Perfect 2-step chain fill: huge reward.
            score -= 40.0;
        } else {
            // Partial chain fill: reward proportional to how much of post residual is consumed.
            let fill = 1.0 - (leftover as f64) / (post_residual as f64);
            score -= 20.0 * fill;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the post residual: penalize dead space relative to next item.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Compare post residual against mean residual: leaving more than average free
    // space is a sign of a wasteful placement.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless nothing fits well
    // (post residual would be tiny) or it is the only option.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.4 * waste;
        // If item nearly fills a fresh bin, opening a new bin is fine.
        if item_size >= 90 {
            score -= 40.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use leftover space: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be picky (penalize loose fits);
    // late in stream, accept decent fits to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.5;

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if open_bins_count > 4 {
        score -= 0.1 * mean_residual;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // More attractive when few bins can fit the item.
        score -= 15.0 * (fitting_bins_count as f64).min(3.0);
        // Early stream: new bins are cheaper investments.
        score -= 30.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr
        - 22.0 * x * (1.0 - x) * 4.0          // reward mid-range residuals (usable space)
        - 14.0 * x * x * (1.0 - progress);     // early stream: reward tight fits more
    score += 30.0 * x * x * x * progress;      // late stream: penalize large leftover dead space

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 18.0 * dev - 10.0 * dev * dev;

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_after = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs() / cap;
        score -= 25.0 * fit_after * (1.0 - gap * gap);
        score += 12.0 * (1.0 - fit_after) * (nx / cap);
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when open bins exist.
    if bin_residual == bin_capacity {
        score += 45.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if item is huge, opening a fresh bin is attractive.
        score -= 35.0 * (item_size as f64 / cap).powi(2);
    }

    // Small penalty on many open bins to encourage consolidation.
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize post_residual more aggressively when small
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 20.0;
    }

    // Harmonic classes: classify post_residual into residue classes modulo common item sizes
    let classes: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut harmonic_bonus = 0.0;
    for &c in &classes {
        let r = post_residual % c;
        if r == 0 && post_residual > 0 {
            harmonic_bonus += 12.0; // exact multiple: dead space aligns with class
        } else if r < 5 {
            harmonic_bonus += 6.0; // near-multiple: likely fillable
        }
    }
    score -= harmonic_bonus;

    // Reward when next item fits into post_residual (chained placement)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // extra reward if next item almost exactly fills residual
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual {
        // penalize leaving dead space that next item cannot use
        score += (post_residual as f64) * 0.5;
    }

    // Last fitting bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current bins are congested
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = (bin_capacity as f64) * 0.9 + congestion * 5.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big next item: fresh bin is valuable
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Slight preference for bins below mean residual (balance load)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps too small for the smallest possible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < next_item_size as f64 && post_residual > 0 {
        // Gap can't fit the lookahead item -> likely dead space.
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize using existing bins when many are open,
    // pushing toward consolidation; but a new empty bin gets a mild bonus
    // so it can win when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 0.15 * open_bins_count as f64;
    }

    // Prefer bins with residual close to the item (good local fit).
    score += 0.3 * ((bin_residual as f64 - item_size as f64).abs());

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match between post_residual and next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step chain: bin becomes perfectly full next step
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // reward closeness of post_residual to next item size (soft match)
            score -= 25.0 * (-diff / 20.0).exp();

            // penalize if next item cannot fit into post_residual (dead-end risk)
            if post_residual < next_item_size {
                score += 0.35 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Relative to mean residual: prefer bins whose post_residual sits below the mean
    // (tighter packing), but avoid creating tiny unusable slivers.
    score += 0.20 * (post_residual as f64 - mean_residual);

    // Penalize unusable dead space: residuals below the minimum item size are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (post_residual close to next item) or when
    // the stream is early and future flexibility is valuable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let flexibility_bonus = 12.0 * (1.0 - progress);
        score = bin_capacity as f64 - flexibility_bonus;
        // discourage opening new bins when a good 2-step match exists elsewhere
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0; // (unreachable for empty bin, kept for symmetry)
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets extra preference.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot plausibly hold future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 40 {
        // usable small space is mildly good
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 14.0 * (next_item_size as f64 / 100.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // mild bonus per competing bin to spread load
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global residual pressure: when mean residual is high, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.08 * (mean_residual - post_residual as f64) * (0.5 + progress);

    // New-bin candidate handling: empty bin is a fallback; make it attractive only
    // when this item is large or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let base = 30.0;
        // Early stream: opening bins is cheap; late stream: avoid proliferation.
        let time_penalty = 35.0 * progress;
        let size_pull = 0.35 * item_size as f64;
        score = base + time_penalty - size_pull;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0; // large next item benefits from a fresh bin
        }
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score -= 12.0; // no real alternative anyway
        }
    }

    // Mild penalty for too many open bins relative to progress.
    score += 0.6 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress * progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 + 2.0 * p);
    score -= 8.0 * norm_pr * (1.0 - p) * (1.0 - p);

    // Reward tight fits with smooth saturation
    let fit = 1.0 - norm_pr;
    score -= 10.0 * fit * fit * fit;

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 6.0 * (pr - ni) / cap;
        } else {
            score += 4.0 * (ni - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += (open_bins_count as f64).ln() * 0.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: how well post_residual divides into capacity fractions.
    // post_residual that is a divisor-friendly residue (small modulo classes) is
    // more likely reusable by future items -> reward (subtract).
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_bonus = match class {
        0 => 8.0,
        5 => 6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: post_residual that can hold a "typical" chunk
    // (capacity / 4 = 25) is valuable dead-space-wise.
    if pr >= bin_capacity / 4 {
        score -= 4.0;
    } else if pr > 0 {
        // Tiny unusable sliver: penalize strongly.
        score += (bin_capacity / 20 - pr.min(bin_capacity / 20)) as f64 * 0.5;
    }

    // Perfect fit: zero waste is ideal.
    if pr == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this bin chains perfectly -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        } else {
            // Next item won't fit: the leftover becomes dead space unless
            // it is large enough for future items; penalize moderate leftovers.
            if pr < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and mean residual across open bins is small (nothing useful left).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64 / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score += 15.0 - 12.0 * pressure.clamp(-1.0, 1.0) - 5.0 * progress;
    } else {
        // Mild preference for tighter bins (lower residual) beyond raw post_residual.
        score += (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    // Late-stream consolidation: as the stream ends, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    let gap = post_residual as f64;
    if post_residual > 0 {
        // Penalize gaps that are too small for the smallest plausible item (1..100).
        // A gap of 1..=10 is dead space unless the next item fits it.
        if post_residual < 10 {
            score += 60.0 * (1.0 - gap / 10.0) + 15.0;
        } else if post_residual < 25 {
            score += 25.0 * (1.0 - (gap - 10.0) / 15.0);
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Reward bins whose gap can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: it's likely dead space.
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few bins needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing),
    // but reward using bins with larger residuals when mean residual is high.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 40.0 + 1.5 * open_bins_count as f64 * progress;
        score = base + item_size as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is mandatory anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 50.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // next item fits: reward closeness of post_residual to next size
            score -= 20.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving dead space relative to next size
            score += 5.0 + (next - post_residual as f64) * 0.3;
        }
    }

    // Penalize very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only late in the stream or when many bins already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 20.0 * progress - (open_bins_count as f64).min(10.0);
    }

    // Mild bias toward fuller bins
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let tight_fit = (post_residual as f64) / (item_size as f64).max(1.0);

    // Reward tight fits, more strongly later in the stream.
    score -= 12.0 * fill_ratio * (0.5 + progress);

    // Penalize large dead space, especially if it can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover can still serve the next item.
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 8.0 * fill_ratio;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize using a bin when many bins fit (prefer best-fit among them via post_residual already).
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: attractive early when few bins exist, or when mean residual is low.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        let state_pull = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 6.0 * early + 10.0 * (1.0 - state_pull);
        // Late in stream, opening bins is costly unless nothing fits well.
        if progress > 0.7 && fitting_bins_count > 0 {
            score += 10.0 * progress;
        }
    } else {
        // Mild bonus for consolidating when many bins are open.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Nonlinear coupling: exact fills are golden.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 6.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Tight-fit ratio term: prefer leftover smaller than the item itself.
    score += 3.0 * tight_fit.min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) growth
    let mut score = pr + 6.0 * norm_pr * norm_pr * cap + 4.0 * norm_pr * norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: waste is more tolerable early, costly late
    score *= 0.6 + 0.8 * progress * progress;

    // Interaction: post_residual vs mean residual — avoid bins far from the fleet norm
    let dev = pr - mean_residual;
    score += 0.35 * dev * dev / cap;

    // Lookahead coupling: reward leaving space the next item can use (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 3.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Mild pressure against proliferation of open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: make empty bins attractive only when the fit is poor
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity fractions.
    // Small post_residual in a "good class" (near multiples of common item sizes)
    // is fine; large awkward residuals are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward (post_residual near zero)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Harmonic classes: how well post_residual aligns with capacity fractions
    // (1/2, 1/3, 1/4 of capacity) — residuals near these values are reusable
    // by typical mid-size items.
    for k in 1..4u32 {
        let frac = cap / (k as f64 + 1.0);
        let d = (pr - frac).abs();
        score += d * (0.15 / k as f64);
    }

    // Integer-division threshold: post_residual bucketed by /10 class.
    let bucket = post_residual / 10;
    // Buckets 0..3 (0-39) are highly reusable; larger buckets penalized superlinearly.
    if bucket <= 3 {
        score -= 6.0 * (3 - bucket) as f64;
    } else {
        score += 0.5 * (bucket - 3) as f64 * (bucket - 3) as f64;
    }

    // Reward if next item exactly fits the post residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 20.0 - 0.5 * leftover as f64;
        } else {
            // next item cannot use this residual; penalize proportionally
            let gap = next_item_size - post_residual;
            score += 0.3 * gap as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless current residuals
    // are all large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = avg / cap; // high pressure = open bins are full
        score += 45.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild penalty for item much smaller than residual (wasteful placement)
    let waste = (bin_residual - item_size) as f64;
    score += 0.1 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps (< 10, or below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.25 * (post_residual as f64);
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor bins whose residual is close to the mean (balanced packing).
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the gap: penalize proportionally to wasted space
            score += 0.1 * (post_residual as f64);
        }
    }

    // Slight preference for tighter bins (small residual before placement) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins far below mean residual (already loose bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when current bin fit would be very poor.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can accommodate the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit_gap = post_residual - next_item_size;
            // Reward proportional to how snugly the next item fits afterwards
            score -= (bin_capacity as f64) * 0.9
                * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
            // Extra bonus for a perfect 2-step chain (post_residual == next_item_size)
            if next_fit_gap == 0 {
                score -= 40.0;
            } else if next_fit_gap <= 10 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space,
            // scaled by how much of the residual is wasted.
            let dead = post_residual as f64;
            score += dead * 0.5;
            // If next item is large and this bin strands it, add extra penalty
            if next_item_size > post_residual {
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
        }
    } else {
        // Last item: just minimize final waste
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual above the mean are more
    // valuable to preserve for future items; penalize using them loosely.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - res) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is
    // huge relative to capacity and no good chaining exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish default; adjust based on item size fraction.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            // Large item: fresh bin is fine, slight reward so it beats bad fits
            score -= 10.0;
        } else {
            // Small/medium item: discourage wasting a fresh bin unless lookahead says otherwise
            score += 25.0;
        }
        // If lookahead shows the next item also fits a fresh bin after this one,
        // make the new bin attractive for building a clean chain.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Mild stream-progression term: late in the stream, be more conservative
    // about opening bins (favor filling existing ones).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if is_new_bin {
            score += progress * 20.0;
        }
    }

    // Slight preference to keep the number of open bins from exploding
    score += (open_bins_count as f64) * 0.05 * if is_new_bin { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits nonlinearly.
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill: residual zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: reward leaving exactly room for the next item,
    // penalize leaving a residual that is unusable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 30.0;
        } else if post >= nxt && post - nxt < 10.0 {
            score -= 10.0;
        } else if post < nxt && post > 0.0 {
            // dead space relative to lookahead: penalize small stragglers
            score += 8.0 * (1.0 - post / nxt);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is huge
    // relative to capacity or open bins are nearly all unusable.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / cap;
        // default: discourage opening a new bin
        score += 30.0;
        // but if item is very large, a fresh bin gives perfect packing room
        score -= 40.0 * pressure * pressure;
        // if many bins already open and mean residual is high, opening is fine
        if mean_residual > 0.35 * cap && open_bins_count > 2 {
            score -= 10.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (bin_residual as f64 - item_size as f64) / cap;

    // Slight penalty for bins far below mean residual (fragmentation avoidance).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score += 0.02 * dev; // reward above-average fullness slightly
    }

    // Mild open-bins count pressure: discourage spreading across many bins early.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth polynomial coupling of residual penalty with stream progress:
    // early on, prefer tight packing (amplify residual penalty); later, relax.
    let coupling = 1.0 + 1.5 * progress - 2.0 * progress * progress + 1.5 * progress * progress * progress;
    score *= coupling;

    // Reward near-perfect fills (small post_residual) with a smooth bump
    let fill = 1.0 - norm_pr;
    score -= 25.0 * fill * fill * fill * fill;

    // Penalize wasted space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Many open bins: discourage fragmenting further; few bins: consolidation ok
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - fill);

    // Lookahead: if next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-diff / 10.0).exp();
        // smooth penalty if next item leaves awkward tiny residual
        let next_norm = (pr - next_item_size as f64) / cap;
        if next_norm > 0.0 {
            score += 10.0 * next_norm * (1.0 - next_norm) * (1.0 - next_norm);
        }
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // --- Harmonic class of post_residual: classify leftover space into deciles ---
    let class = post_residual / 10; // 0..=10
    // Dead-space classes: leftover < 10 can never host any item -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Sweet-spot classes: leftovers that match common item size bands (10,20,40,50)
    // are reusable; reward them mildly.
    let reusable = matches!(class, 1 | 2 | 4 | 5);
    if reusable {
        score -= 6.0;
    }
    // Modulo coupling: leftover that is an exact multiple of 25 pairs well with
    // quarter-capacity item classes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // --- Lookahead (k=2) coupling ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: chain reward, stronger
            // when the chain is tight (little waste after both placements).
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 + (chain_waste.min(50) as f64) * -0.08;
            if chain_waste < 10 {
                score -= 5.0; // near-perfect two-item chain
            }
        } else {
            // Next item won't fit here; penalize by the size of the miss,
            // but only mildly if the miss is huge (bin nearly exhausted anyway).
            let miss = next_item_size - post_residual;
            if miss <= 20 {
                score += (20 - miss) as f64 * 0.4; // near-miss is worst case
            }
        }
    } else {
        // Last item: any residual is pure waste; tightest fit wins outright.
        score *= 1.5;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can host the item: new bin is mandatory.
            score -= 100.0;
        } else {
            // Opening a new bin wastes (capacity - item) of fresh space.
            // Penalize, but relax if existing bins are on average quite full
            // (mean_residual low) or late in the stream.
            score += 12.0 + mean_residual * 0.3 - progress * 5.0;
            // If the item is large, a fresh bin wastes less: soften penalty.
            score -= item_size as f64 * 0.05;
        }
    } else {
        // --- Last-chance bonus: this is the only open bin that fits ---
        if fitting_bins_count == 1 {
            score -= 14.0;
        }
        // Prefer fuller bins when many bins compete: tie-break by fill ratio.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 8.0;
    }

    // Small global pressure toward using fewer bins early on.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A nonzero post_residual below the minimum item size (unusably small gap)
    // is pure waste: penalize it hard so tight-but-leaving-dead-space fits lose
    // against alternatives (including opening a fresh bin).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Perfect fit: the bin is closed exactly, zero waste — reward strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Last-chance pressure ---
    // If this is the only open bin that can fit the item, using it avoids
    // opening a new bin; reward it (but never for the new-bin candidate itself).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    // Opening a bin is expensive: add a fixed cost plus pressure that grows
    // with the number of already-open bins (discourage bin proliferation),
    // unless the current fit would strand a large dead gap (handled above,
    // since the dead-space penalty outweighs this surcharge).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    // --- Lookahead coupling (k=2) ---
    // If the leftover space can still host the next item, this placement keeps
    // the bin useful: reward it. If the leftover is positive but too small for
    // the next item, the gap is likely to become dead weight: mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // --- Open-bins compaction pressure ---
    // When many bins are open, amplify the preference for tight fits so the
    // heuristic consolidates fragments instead of spreading them.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // --- Fragmentation context ---
    // If the average residual across open bins is low (bins nearly full),
    // slightly favor packing into them to close them out.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits snugly here.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 250.0; // perfect chain: item + next fills bin exactly
        } else if gap > 0.0 && gap <= 15.0 {
            score -= 80.0; // next item still fits comfortably
        } else if gap < 0.0 && gap >= -next_item_size as f64 {
            // next item would NOT fit: penalize leaving awkward residual
            score += 30.0;
        }
        // Penalize residuals too small to ever matter (dead space) vs lookahead
        if post_residual < 10 && gap != 0.0 {
            score += 15.0;
        }
    }

    // Prefer bins with residuals above the mean (keep big slots alive),
    // unless this placement is a very tight fit.
    let tight = (post_residual as f64) < 0.25 * (bin_capacity as f64);
    if !tight {
        if (bin_residual as f64) > mean_residual {
            score += 10.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current item is large
    // (large items pair well with fresh capacity) or stream is early.
    if bin_residual == bin_capacity {
        let large_item = item_size > bin_capacity / 2;
        let early = (step_index as f64) < 0.2 * (total_items as f64);
        if large_item || early {
            score -= 40.0;
        } else {
            score += 200.0; // discourage opening new bins mid-stream for small items
        }
        // But if next item is huge, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 50.0;
        }
    }

    // Mild preference to fill already-open bins as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize small dead space that can never host typical items (1..100 unknown),
    // but mildly reward moderate residuals that stay reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 4.0;
        }
    }

    // Time horizon: early in the stream, be more open to new bins (explore);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    // New-bin candidate: penalize opening a bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        let exploration_bonus = 15.0 * (1.0 - progress);
        score += 20.0 - exploration_bonus;
        // If many bins are open, discourage adding more.
        score += 1.5 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins with residual below mean (more compact bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: non-linear polynomial in normalized post residual
    let mut score = 3.0 * x * x - 1.5 * x * x * x;

    // Stream-progress coupling: later in stream, penalize large residuals more (want tight fits)
    let progress_coupling = (0.5 + t) * x * x;
    score += 2.0 * progress_coupling;

    // Reward near-perfect fills (small post residual) with a smooth dip
    score -= 1.2 * (1.0 - x) * (1.0 - x) * x;

    // Dead-space penalty: residual too small for any plausible next item
    let small_gap = (x * 10.0).powi(2) * (1.0 - x);
    score += 0.8 * small_gap;

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 1.5 * fits_next * (1.0 - (pr - next_item_size as f64) / cap).abs() * (1.0 - nx);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5 * (1.0 - t);
    }

    // Many open bins: prefer consolidating into existing bins
    let ob = open_bins_count as f64;
    score += 0.05 * ob * x * x;

    // Mean residual interaction: if this bin is far below mean residual, mildly penalize
    let dev = (pr - mean_residual) / cap;
    score += 0.6 * dev * dev - 0.4 * dev;

    // New-bin candidate calibration: empty bin gets a moderate baseline
    if bin_residual == bin_capacity {
        score += 1.8 - 1.5 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // Dead space classes: residual smaller than the minimum item size is unusable.
    if post_residual < 10 {
        score -= 40.0; // small but totally dead space: acceptable, close the bin
    } else {
        // Harmonic class of post residual: which item sizes could still fit?
        // Usable residual is valuable: reward keeping large usable space.
        let usable = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * usable;

        // Modulo-10 harmonic classes: residuals that are multiples of 10
        // align with common item sizes and remain splittable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Residuals in [10,19] can only host tiny items: mild penalty unless
        // the lookahead item actually fits there.
        if post_residual < 20 {
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 15.0; // lookahead fits exactly in this tight leftover
            } else {
                score += 6.0;
            }
        }
    }

    // Integer-division thresholds on how full the bin becomes.
    let fill_class = (bin_residual * 4) / bin_capacity; // 0..3 quarters used before placement
    match fill_class {
        3 => score -= 25.0, // bin was already >75% full: prefer completing dense bins
        2 => score -= 10.0,
        1 => score += 5.0,
        _ => {}
    }

    // Lookahead coupling: penalize leaving a residual that neither fits the
    // next item nor forms a clean class (wasted intermediate state).
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item cannot use this bin's leftover: leftover must be dead-ish
            if post_residual >= 10 {
                score += 10.0;
            }
        } else {
            // next item fits: reward proportional closeness of the match
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items early or when mean residual is fragmented: open fresh bin.
        if item_frac > 0.6 || (mean_residual < item_size as f64 && open_bins_count > 0) {
            score -= 15.0 + 10.0 * item_frac + 5.0 * (1.0 - progress);
        } else {
            score += 25.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mild preference to spread load when many bins are open and residuals high.
    if open_bins_count > 3 && (post_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to ever be useful (below the minimum plausible item size band).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 50.0 + (10 - post_residual.min(10)) as f64 * 10.0;
    }

    // Strongly reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space zone: residual in [1, 20] is hard to fill later; penalize
    // proportionally, but less if the next item could use it.
    if post_residual >= 1 && post_residual <= 20 {
        let usable_next = next_item_size > 0 && next_item_size <= post_residual;
        if !usable_next {
            score += (20 - post_residual) as f64 * 4.0;
        } else {
            score -= 15.0; // lookahead item plugs the gap exactly
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and
        // when existing bins could still fit the item.
        score += 40.0 + pressure * 3.0;
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 10.0;
        }
    } else {
        // Existing bin: reward being chosen, especially under pressure.
        score -= pressure * 1.5;
        // Last-chance bin: strongly prefer using it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    // but modulate by mean residual across bins.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;
    if (bin_residual as f64) < mean_residual {
        score -= 5.0; // fuller-than-average bin: good, keep draining it
    }

    // Lookahead synergy: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        let left = post_residual - next_item_size;
        if left <= 10 {
            score -= 10.0; // chain fill nearly completes the bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward leaving room for the next item, decaying with slack
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize proportionally to how much is wasted
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Penalize tiny dead space that nothing can use (items >= 1, but small unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when decent fits exist among open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        // a new bin is acceptable if the next item is large and this item is small
        if next_item_size > 0 && next_item_size >= item_size.saturating_mul(2) {
            score -= 25.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins first to consolidate)
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Slight preference for tighter fits overall
    score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 8.0; // small leftovers are fine-ish
        } else {
            // waste that can't hold the next item is worse
            if next_item_size > 0 && dead < next_item_size as f64 {
                score += 6.0 + 0.25 * dead;
            }
        }
    }

    // Lookahead: reward bins whose post-residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            let chain = post_residual as f64 - next_item_size as f64;
            score -= 5.0 * (1.0 - chain / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong bonus so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced when stream is early
        // or when existing residuals are large (poor fits likely).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 20.0 + 25.0 * progress;
        // If mean residual is large, open bins are roomy; opening new is cheaper.
        penalty -= 0.15 * mean_residual;
        // If many bins fit, opening new is wasteful.
        if fitting_bins_count > 0 {
            penalty += 8.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // If the next item is huge and no bin would have room after, opening is ok.
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 > bin_capacity as f64 {
            penalty -= 10.0;
        }
        score = score.max(0.0) + penalty;
    }

    // Slight preference for consolidating into bins with smaller residuals overall.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, dead space is costly.
    let pr_norm = pr / cap;
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm); // 0 = empty, 1 = full
    score -= 30.0 * tightness * (0.4 + 0.6 * progress);

    // Reward filling bins tightly as stream progresses (quadratic in progress).
    score -= 20.0 * tightness * progress * progress;

    // Penalize post_residual that cannot fit the lookahead item (smooth cubic coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * gap;
        // Reward residual that exactly accommodates the next item (smoothly).
        let fit_gap = (pr - nx).abs() / cap;
        score -= 12.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - fit_gap.min(1.0));
    }

    // Last-chance bin bonus: smooth penalty for alternatives when only this bin fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins (smooth in count).
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Pull toward mean residual: prefer bins near average fill (quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=5) are near-perfect fits -> reward strongly.
    let cls = post_residual % 10;
    match cls {
        0 => score -= 40.0,               // exact fill, ideal
        1..=5 => score -= 30.0,           // tiny dead space
        6..=9 => score += 8.0,            // awkward small gap
        _ => {}
    }

    // Integer-division thresholds on post_residual: large usable leftovers
    // (>= 25, i.e. capacity quarter) remain attractive for future items.
    let quarter = bin_capacity / 4;
    if post_residual >= quarter {
        score -= 12.0;
    } else if post_residual >= quarter / 2 {
        score += 5.0; // half-quarter gap: moderately wasteful
    } else {
        score += 15.0; // dead space below 12
    }

    // Coupling: does next item fit into the post residual? Harmonic residue
    // check: if (post_residual - next_item_size) % 10 == 0, chain fits nicely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = post_residual - next_item_size;
            if chain % 10 == 0 {
                score -= 25.0;            // perfect chained fill
            } else {
                score -= chain as f64 / 20.0;
            }
        } else {
            score += 10.0; // next item won't reuse this bin
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize spreading when many bins are open with high mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 1.5 + mean_residual * 0.05 * progress;

    // New-bin candidate: only attractive when item is huge relative to
    // capacity or all open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / bin_capacity as f64) > 0.8;
        if tight {
            score -= 20.0;
        } else {
            score += 30.0 + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are
    // effectively unusable; anything below ~10 is nearly worthless dead space.
    if post_residual < 10 {
        score += 40.0; // tiny sliver -> heavy penalty
    } else if post_residual <= 20 {
        score += 15.0; // awkward small gap
    }

    // Reward very tight fits (post_residual close to 0 relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize leaving a gap that exactly matches next item poorly:
    // if the next item cannot use the leftover, the dead space persists.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            score += 12.0; // leftover unusable by lookahead item
        } else {
            score -= 10.0; // leftover perfectly consumable by next item
        }
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // discourage opening new bins when fleet is already large.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bin less attractive unless it enables a
    // great pairing with the lookahead item (e.g. item + next <= capacity).
    if bin_residual == bin_capacity {
        let pair_ok = next_item_size > 0 && (item_size + next_item_size) <= bin_capacity;
        if pair_ok {
            score -= 8.0; // fresh bin justified by lookahead pairing
        } else {
            score += 30.0; // default: avoid opening new bins
        }
    }

    // Mean residual coupling: if average residual across bins is already low,
    // existing bins are well-filled; prefer them even more.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for filling bins earlier in the stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills this bin's post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap.min(40.0);
        if gap == 0.0 {
            score -= 60.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Prefer tight fits relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin early when an open bin fits reasonably well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // new bin can host a fresh pair
        }
    }

    // Late in the stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: post residual too small to hold typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits into post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item can't follow here; mild penalty if we strand space
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Global state: many open bins with low mean residual -> prefer consolidation.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 3.0 * t;
    }

    // Late in stream: avoid leaving large residuals; early: allow exploration.
    score += t * (post_residual as f64) * 0.3;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Early on, prefer filling bins tightly (low post_residual); later, tolerate
    // residual slightly more to keep bins flexible for future arrivals.
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - norm_pr));

    // Non-linear penalty for small, awkward residual gaps (dead space).
    // Penalize residuals that are too small to be useful but nonzero, using a
    // smooth quadratic bump centered around a low residual fraction.
    let dead_center = 0.15;
    let dead_width = 0.2;
    let dead = ((norm_pr - dead_center) / dead_width).powi(2);
    score += 8.0 * (-dead).exp() * (1.0 - progress);

    // Reward tight fits: smooth coupling between item size and remaining space.
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * norm_item * tightness * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let look = next_item_size as f64 / cap;
        score -= 5.0 * look * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize if next item cannot fit here anyway (residual wasted).
        score += 2.0 * (next_item_size as f64 / cap) * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.5 * (open_bins_count as f64) * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: make empty bins slightly less attractive unless the
    // current bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod-based dead-space taxonomy) ---
    let pr = post_residual;
    // Perfect-fit class: residual exactly divisible into harmonic fractions of capacity
    let cap = bin_capacity as f64;
    let fractions: [u32; 6] = [1, 2, 4, 5, 10, 20];
    let mut harmonic_bonus = 0.0;
    for f in fractions.iter() {
        let denom = bin_capacity / f;
        if denom > 0 && pr % denom == 0 && pr > 0 {
            harmonic_bonus += 8.0 / (*f as f64).sqrt();
        }
    }
    score -= harmonic_bonus;

    // Small dead space is bad: penalize tiny nonzero residuals (unusable slivers)
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Integer-division threshold classes on post_residual
    let pr_class = pr / 10; // 0..10 coarse class
    score += match pr_class {
        0 => 6.0,   // 0-9: near-full, only good if exact
        1 => 2.0,   // 10-19: can host small items
        2 => 0.0,
        3 => -1.5,
        4 => -2.0,  // 40-49 sweet spot
        5 => -1.0,
        _ => 0.5,
    };

    // Lookahead coupling: does post_residual fit next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0; // perfect chain
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 / (1.0 + slack / 10.0);
            // harmonic chain: next item leaves a residual divisible by 10
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 3.0; // next item won't fit here either
        }
    } else {
        // last item: strongly prefer exact fill
        score -= 15.0 / (1.0 + pr as f64);
    }

    // Last-chance bin: heavily favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = 40.0 + mean_residual * 0.3 - openness * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += (bin_capacity - next_item_size) as f64 * 0.1;
        }
        // discourage opening bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for fuller bins when many bins are open
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (open_bins_count as f64).sqrt().min(3.0);

    // Mean-residual coupling: penalize bins far from the mean (keep residuals uniform)
    let dev = post_residual as f64 - mean_residual;
    score += (dev * dev).sqrt().min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1) can use it well.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0; // tiny slivers are pure waste
    }
    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the next item exactly fits the post residual.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating a gap just below the next item size (dead space).
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer tightening existing ones
    // rather than spreading items; with few open bins, opening new bins is cheap.
    let bin_pressure = (open_bins_count as f64).ln().max(0.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 20.0 * bin_pressure + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // But if item is large and no bin has good room, new bin is less bad.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Fitting an existing bin: reward more when bin pressure is high.
        score -= 4.0 * bin_pressure;
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.15;
    }

    // Mild preference for bins with residuals below the mean (tighten loose bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Reward if next item still fits in the bin after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize dead space that neither fits the next item nor is tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
        // Extra penalty for medium dead space (hard to fill later).
        if post_residual > 20 {
            score += 10.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins that become
    // tighter than average (reducing fragmentation spread).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current item is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, but less if item is large.
        score += 30.0 - 0.3 * (item_size as f64);
        // Strong penalty if an open bin could hold both item and next item.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Late in the stream, prefer filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64);

    // Penalize unusable dead space: residuals too small for the smallest items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys a slot usable by the next item
            score += 6.0;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize opening new bins mildly; worse early when many bins open
        score += 40.0 + 5.0 * (open_bins_count as f64).sqrt() - 20.0 * (1.0 - progress);
        // if the fit into an open bin would be very loose, new bin becomes competitive
        if post_residual as f64 > 0.5 * (bin_capacity as f64) {
            score -= 35.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late in the stream, avoid spreading: prefer densest bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (tight fit)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is more tolerable; late, dead space is heavily penalized.
    let pn = post / cap; // normalized post residual in [0,1]
    let poly = pn * pn * (1.0 + 2.0 * progress) + pn.powi(3) * (1.0 + 4.0 * progress * (1.0 - progress) * 4.0);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pn;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bin bonus: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = post - nx;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty proportional to leftover gap
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, or large enough) are rewarded.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        // Perfect fit: strongest reward.
        score -= 60.0;
    } else if class == 0 {
        // Leftover is a multiple of 10: still highly reusable.
        score -= 25.0;
    } else if pr <= 5 {
        // Tiny dead space: nearly perfect.
        score -= 45.0;
    } else if pr <= 15 {
        // Small awkward leftover.
        score += 10.0;
    } else if pr >= 50 {
        // Large leftover keeps future options open.
        score -= 15.0;
    }

    // Integer-division thresholds on post_residual vs next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the lookahead item: chain-fit reward.
            score -= 18.0;
            // Exact chain fit (post_residual == next_item_size) is ideal.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Harmonic pairing: leftover + next item sums to a multiple of capacity/2.
        let half = bin_capacity / 2;
        if (pr + next_item_size) % half == 0 && pr + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive for big items or late stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size >= 60;
        let many_bins = open_bins_count as f64 > 8.0;
        if big_item || many_bins {
            score -= 5.0 + 20.0 * progress;
        } else {
            // Early stream with small items: discourage opening new bins.
            score += 25.0 - 20.0 * progress;
        }
    }

    // Mean-residual coupling: prefer bins whose fill state tracks the average.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Mild preference for tighter bins when many are open.
    score += (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead gap, essentially unusable
        } else if post_residual <= 20 {
            score += 25.0; // narrow gap, only fits smallest items
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit, no dead space at all
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor new bin when fit is bad.
    let ob_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += ob_pressure;

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0; // blocks the next item too
    }

    // New-bin candidate: mildly penalize opening a new bin unless pressure is high or fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * fill_ratio;
        if post_residual < 15 {
            score -= 30.0; // large item in fresh bin leaves useful space, fine
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good compaction target.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Early stream: be slightly greedy toward tight packing; late stream: conserve bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward for tight chain (small slack after hypothetical next item).
        let slack_after_next = post_residual - next_item_size;
        score -= (slack_after_next as f64).min(20.0) * 0.5;
    }

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins that will end up below-average residual
    // (tight packing) when mean residual is large.
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave large unusable
    // residual and next item is big.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate, penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    }

    // Discourage leaving residuals that are too small to ever be useful
    // (below minimum plausible item size of 1 is trivial; use small-threshold logic).
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Waste ratio: dead space relative to capacity
    let waste_ratio = post_residual as f64 / cap;
    score += 30.0 * waste_ratio * waste_ratio;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 25.0;
        } else {
            // penalize leaving residual that next item cannot use if gap is small
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 && gap >= 0.0 {
                score += 5.0;
            }
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize bins whose residual deviates from mean (keep bin diversity balanced)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // New-bin candidate handling: only attractive when the item fits poorly elsewhere
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // opening a new bin is penalized mildly; becomes attractive if item is large
        score = cap - item_size as f64 + 15.0 - 20.0 * tightness;
        // late in the stream, discourage opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if many bins already open, discourage yet another
        score += 2.0 * open_bins_count as f64;
    }

    // Time horizon: as stream progresses, be more conservative (tighter packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically, more strongly early in stream.
    score += 6.0 * norm_pr * norm_pr * (1.5 - progress);

    // Reward tight fits (small post_residual) especially when many bins fit the item.
    if fitting_bins_count > 0 {
        score -= 4.0 / fitting_bins_count as f64 * (1.0 - norm_pr);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 3.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * gap / cap;
        }
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * norm_pr;
    score += 0.3 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: prefer it only when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score = pr + 5.0 - 6.0 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
