    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // next fits: reward proportional to tightness of that future fit
            let fut = post_residual - next_item_size;
            if fut < 10 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item will NOT fit here -> this bin's residual is likely wasted
            score += 10.0;
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; penalize slightly so it only wins
    // when existing bins are truly bad, but relax late in the stream when
    // consolidation matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * progress;
        // if nothing fits anywhere, new bin is obviously fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins below mean residual (balancing toward tight packs).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure to close nearly-full bins early in the stream.
    if post_residual <= 15 {
        score -= 10.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (1..=10) are wasted; treat them as fully lost capacity.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor. Penalize the fresh bin mildly, escalating with
    // how many bins could otherwise fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 + 8.0 * fitting_bins_count as f64 };
        score += pressure + 0.05 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild open-bin pressure: prefer consolidating into fewer bins.
    score += 0.02 * open_bins_count as f64;

    // Slight preference for bins with below-average residual (fill emptier bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward when post_residual exactly chains to next item ----
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect chain: next item exactly fills what remains -> strong reward.
        let chain_gap = (post - nxt).abs();
        if nxt <= post {
            score -= 55.0 * (1.0 - chain_gap / 60.0).max(0.0);
        } else {
            // Next item won't fit in this bin's remainder: penalize proportionally
            // to how much of the next item would be stranded.
            score += 0.25 * (nxt - post).min(50.0);
        }

        // Coupling: if the chain gap is small, discount dead space further.
        if chain_gap < 10.0 {
            score -= 8.0 * (10.0 - chain_gap);
        }
    } else {
        // Last item: simply prefer the tightest fit.
        score += 0.0;
    }

    // ---- Tightness reward: small post_residual relative to capacity ----
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // ---- Mean residual coupling: placing in a bin far below mean residual
    //      balances the pool of open bins; encourage leveling ----
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 20.0 * dev; // bins with more residual than mean get penalized

    // ---- Last-chance bonus: only one bin can fit the item, use it ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // ---- New-bin candidate handling: brand-new empty bin ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current fits are poor or the
        // item is large and would leave awkward remainders elsewhere.
        let poor_fit = if next_item_size > 0 && next_item_size > post_residual.min(bin_residual.saturating_sub(item_size)) { 1.0 } else { 0.0 };
        let large_item = (item_size as f64 / bin_capacity as f64) * 30.0;
        let early_bonus = (1.0 - progress) * 15.0; // open bins early in stream
        score -= 10.0 + poor_fit * 25.0 + large_item + early_bonus;
        // But avoid proliferating bins late in the stream when fits exist.
        score += (open_bins_count as f64) * (2.0 + 6.0 * progress);
    }

    // ---- Mild penalty for very small unusable remainders (dead space) ----
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual decay
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 18.0 * tight * tight;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no future item can use (min item size 1)
    if post_residual >= 1 && post_residual < 5 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack_after / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: dead space penalty
        score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: prefer emptier bins when many bins are open
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += crowding * (post_residual as f64 - mean_residual) * 0.4;

    // Prefer bins below mean residual slightly (conservation of large gaps)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Time horizon: early in stream, be conservative (favor new bins for big gaps);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let conservatism = 1.0 - progress;
    score += conservatism * 6.0 * (post_residual as f64 / (bin_capacity as f64));

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: good if item is large relative to capacity
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = 25.0 - 20.0 * size_frac;
        // Late in stream, avoid opening new bins
        score += progress * 12.0;
        // If a last-chance bin exists, discourage the new bin
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
        // If next item is huge, opening a fresh bin may be wise
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    score += 12.0 * pr_norm * pr_norm * progress;
    score -= 8.0 * pr_norm * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * (0.5 + 0.5 * progress);
        } else {
            score -= 3.0 * (pr - nxt) / cap * (1.0 - progress);
        }
    }

    // Last-chance fitting bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Slight preference to keep bins balanced with mean residual
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Small penalty for proliferating bins as stream progresses
    score += 0.4 * (open_bins_count as f64).ln() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 captures
    // "resonant" dead-space levels. Leftovers that are multiples of 10 are
    // more likely to be exactly filled by later items -> reward them.
    let residue_class = (post_residual % 10) as f64;
    score -= 6.0 * (1.0 - residue_class / 10.0);

    // Integer-division thresholds: large post_residual bands are valuable.
    if post_residual >= 50 {
        score -= 10.0;
    } else if post_residual >= 30 {
        score -= 4.0;
    } else if post_residual < 10 {
        // Tiny dead space: mildly penalize unless bin is nearly perfect.
        score += 5.0;
    }

    // Perfect fit reward (post_residual == 0).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Next-item lookahead: if the next item fits exactly into the post
    // residual, this placement is doubly good (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack_after = post_residual - next_item_size;
            // Reward proportional closeness of the follow-up fit.
            score -= 25.0 * (slack_after as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: slight penalty scaled by overshoot class.
            let over = (next_item_size - post_residual) % 20;
            score += over as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are nearly full (mean residual small) or the item is huge.
    if bin_residual == bin_capacity {
        score += 30.0
            - 0.4 * mean_residual
            + if item_size > 70 { -25.0 } else { 0.0 };
    }

    // Capacity-fraction coupling: reward placements filling a harmonic
    // fraction of the bin (1/2, 1/4, 3/4 boundaries).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let frac = fill * 4.0;
    let harmonic_dist = (frac - frac.round()).abs();
    score -= 8.0 * (1.0 - harmonic_dist);

    // Progression: early in the stream, be more conservative (prefer tight
    // fits to build good bins); late, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, prefer tighter bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post_residual), but with a dead-space twist.
    let pr = post_residual as f64;
    score += pr;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable (min item = 1
    // in this interface, but tiny slivers waste capacity); residuals in a "danger
    // window" that cannot absorb the common small item sizes are heavily penalized.
    if post_residual > 0 {
        // Penalize gaps too small to be useful later.
        if post_residual < 10 {
            score += 60.0 - (post_residual as f64) * 3.0;
        }
        // Penalize gaps that can't fit the lookahead item if the next item is close.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 12.0;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: only attractive when no (or very poor) alternatives.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // Opening a new bin wastes the residual of existing bins: penalize
            // proportionally to how much capacity is stranded in open bins.
            let stranded = open_bins_count as f64 * mean_residual;
            score += 35.0 + stranded * 0.15;
        }
    } else {
        // Reward using an existing bin, especially the last one that fits.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward bins whose residual is far above the mean (they are the natural
        // dumping grounds), keeping low-residual bins for small future items.
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Open-bin pressure: as the number of open bins grows, discourage opening
    // more bins and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.5 * (0.5 + progress);
    }

    // Late-stream tightening: near the end, avoid leaving mid-sized gaps.
    if progress > 0.8 && post_residual > 0 && post_residual < 30 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact or near-exact two-item fill is excellent
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leftover that is too small for typical items (dead space)
            if slack > 0.0 && slack < 10.0 {
                score += 15.0 * (10.0 - slack) / 10.0;
            }
        } else {
            // Next item cannot follow here; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.2 * gap.min(50.0);
        }
    } else {
        // Last item: prefer minimal post_residual strongly
        score += 0.0;
    }

    // Reward bins tighter than the mean (good fillers)
    score -= 0.5 * (mean_residual - post_residual as f64).clamp(-40.0, 40.0);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in stream: be more willing to open new bins (keep flexibility)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late
        score = score * 0.5 + 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Penalize creating tiny unusable residual (< 10, smallest possible item)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
        // Extra reward for a "chained" perfect pair.
        if (post_residual as u32) == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here afterward: mild penalty proportional to gap.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.15 * gap.min(40.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with slack: discourage fragmenting; few open bins: encourage filling.
    let open_f = open_bins_count as f64;
    if open_bins_count > 4 {
        score += 0.05 * open_f * (mean_residual / bin_capacity as f64);
    } else {
        score -= 0.05 * open_f;
    }

    // Time horizon: late in stream, consolidate aggressively; early, allow exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tight;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        score += desperation * (30.0 + 0.3 * open_f);
        // A new bin gives full room for the lookahead item.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, smoothly scaled by progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post-residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr.powi(3) * progress;
    score += 2.5 * coupling;

    // Reward tight fits (small post residual relative to item) more strongly later
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= (1.0 - tightness) * (1.5 + 1.5 * progress);

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - pr) / cap * (1.0 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.4 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: only fitting bin should be favored
    if fitting_bins_count == 1 {
        score -= 1.2 + 1.0 * progress;
    }

    // Mild penalty for bins far below mean residual (fragmentation avoidance)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: neutral baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space buckets by capacity fraction
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Post-residual modulo classes: reward residuals that are "harmonic" with
    // common small item sizes (multiples of 10 / 25 / 50 leave usable space).
    let pr_u = post_residual;
    if pr_u == 0 {
        score -= 25.0; // perfect fit is excellent
    } else {
        let harmonic = if pr_u % 10 == 0 {
            1.0
        } else if pr_u % 25 == 0 || pr_u % 20 == 0 {
            0.6
        } else {
            0.0
        };
        score -= harmonic * 12.0;

        // Penalize tiny unusable slivers (< 10, the minimum item size)
        if pr_u < 10 {
            score += 30.0;
        }
    }

    // Integer-division threshold on post_residual: how many min-size items fit
    let slots = post_residual / 10;
    score -= slots as f64 * 2.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic chaining: post_residual - next still multiple of 10
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when all open
    // bins would waste heavily (post_residual tiny or next item mismatch).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // cheaper to open new bin when open bins are nearly full on average
        score -= (mean_residual / cap).min(1.0) * 10.0;
        // if next item is large and current open bins are tight, new bin good
        if next_item_size > 50 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.3;

    // Slight preference for tighter fills relative to capacity fraction
    score += (1.0 - (bin_residual as f64) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // realistic future item (below the smallest plausible item size) are pure
    // waste. Penalize them super-linearly.
    let dead_threshold = 9.0f64; // items >= 10 in classic streams; below ~10 nothing fits
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else {
        // Mild reward for leaving a usable, well-shaped gap.
        score -= 4.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Mean residual coupling: if this bin is much emptier than average, it is
    // a good "garbage collector" bin; if much fuller than average, placing
    // here may strand the emptier bins.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, this is
    // an excellent chaining placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here: slightly penalize leaving a gap the
            // next item cannot use.
            score += 3.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when no open bin offers a decent fit (i.e., when the best open fit
    // would waste a lot). Since we only see this bin's own call, make the
    // empty bin's score a moderate constant that tight fits can beat, but
    // poor fits cannot.
    if bin_residual == bin_capacity {
        // Baseline for opening a new bin: post_residual == capacity here.
        score = (bin_capacity as f64) * 0.55
            + (open_bins_count as f64).ln().max(0.0) * 2.0
            - 10.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin always fits the next item too; slight bonus early on.
            score -= 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // last item: minimize waste directly
        score += 10.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual as f64 > mean_residual {
            score += 20.0; // even worse if open bins are already loose
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Penalize large unusable residuals (dead space below minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly (dead space minimization).
    if post == 0.0 {
        score -= cap * 0.75;
    } else if post <= 10.0 {
        score -= cap * 0.30;
    } else if post <= 20.0 {
        score -= cap * 0.12;
    }

    // Penalize leaving a residual that is unusable for typical items (1..100):
    // a leftover gap g is "waste potential" if small and odd-ish relative to item sizes.
    let waste = if post > 0.0 && post < 10.0 { cap * 0.20 } else { 0.0 };
    score += waste;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 1.0 {
            score -= cap * 0.60;
        } else if nxt <= post {
            // next item can still fit here: mild reward scaled by how well it fills
            score -= 0.35 * nxt * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here: penalize tight fits that strand the lookahead
            let gap = nxt - post;
            if gap < 20.0 {
                score += 0.25 * gap;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= cap * 0.45;
        if post > cap * 0.5 {
            score += cap * 0.15; // but not if it wastes more than half the bin
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when no open bin offers a good fit.
    let is_new_bin = (residual - cap).abs() < 1.0;
    if is_new_bin {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (early on, opening bins is cheap and gives flexibility).
        score = cap * (0.85 - 0.35 * progress) + post;
        if fitting_bins_count == 0 {
            score -= cap * 0.5; // must open a bin anyway
        }
        if next_item_size > 0 && (next_item_size as f64) > post {
            score -= cap * 0.10; // new bin guarantees lookahead fits too
        }
    } else {
        // Reward using existing bins proportionally to how full they already are.
        let fill_ratio = 1.0 - residual / cap;
        score -= cap * 0.10 * fill_ratio;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > cap * 0.5 && !is_new_bin {
        score -= 0.05 * mean_residual;
    }
    // Fragmentation pressure: many open bins favor packing into existing ones.
    score += 0.5 * open_bins_count as f64 * (if is_new_bin { 1.0 } else { 0.0 });

    // Mild time-horizon term: late in the stream, be greedier about tight fits.
    score -= progress * (cap - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: post-residual scaled by non-linear stream progress coupling
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more as stream progresses (dead space matters more later)
    score += 0.6 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: quadratic bonus for small post-residual
    score -= 1.2 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Lookahead: if next item fits in post-residual, strongly favor this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 1.5 * (1.0 - slack * slack);
        } else {
            score += 0.4 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 0.9 * (1.0 + progress);
    }

    // Mild penalty for many open bins relative to mean residual
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f / (10.0 + mean_residual / cap * 20.0);

    // New-bin candidate: neutral-ish baseline, penalize slightly unless current fits are terrible
    if bin_residual == bin_capacity {
        score = 0.9 + 0.5 * progress - 0.3 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let post = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class: f64 = if post_residual == 0 {
        -30.0 // perfect fill, best possible outcome
    } else if post_residual < eighth {
        12.0 // dead space: too small for most items (min size 1, but typical items larger)
    } else if post_residual < quarter {
        4.0
    } else if post_residual < 2 * quarter {
        -3.0
    } else {
        -8.0 // half empty or more: very reusable
    };
    score += post_class;

    // Modulo-arithmetic harmonic check: can post_residual host a "harmonic" chunk
    // of the next item (next item splits into post_residual via integer division)?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits exactly here: strong reward, scaled by tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 + 8.0 * tight;
        } else {
            // Harmonic divisibility: does post_residual divide into the next item
            // cleanly (next_item_size % post_residual small)? Penalize leftovers
            // that don't align with the incoming demand.
            let r = next_item_size % post_residual.max(1);
            let div = (r as f64) / nxt;
            score += 6.0 * div;
            // If next item cannot fit anywhere else, this bin is last chance.
            if fitting_bins_count <= 1 && next_item_size <= bin_residual {
                score -= 15.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits the current item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Tightness reward relative to current residual (favor snug fits).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Penalize opening a new bin when good open capacity exists.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin penalty grows with number of open bins and stream progress,
        // but relaxes if the mean residual across open bins is too small to matter.
        let usable = mean_residual / cap;
        score += 14.0 + 3.0 * open_f.sqrt() + 10.0 * progress - 12.0 * usable.min(1.0);
        // If current item is huge relative to mean residual, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Mild phase coupling: early in the stream, be frugal with open bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * (1.0 - phase) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead_zone = 12.0; // smallest plausible item is ~1..10; gaps below this are near-useless
        if (post_residual as f64) < dead_zone {
            score += 60.0 + (dead_zone - post_residual as f64) * 6.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.35;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post-residual won't fit the next item: mild dead-space penalty scaled by gap size
        score += (post_residual as f64) * 0.4;
    }

    // Mean-residual coupling: if this bin is far below the mean residual, it is a good
    // "garbage absorber"; if far above, filling it is less critical.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin is a fresh resource; only choose it when
    // the item is large relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits too: reward tight chain
            score -= 0.5 * (post_residual as f64 - next_item_size as f64);
        } else {
            // next item won't fit here: penalize wasted potential
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins)
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 0.25 * next_item_size as f64;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 100.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual already helps; amplify it).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize large dead space non-linearly.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * waste * waste;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let slack = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 40.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward gaps.
        let gap = post_residual as f64 / next_item_size.max(1) as f64;
        score += 15.0 * gap.min(2.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (open_bins_count as f64).ln().max(0.0) * mean_residual / bin_capacity as f64;
    score += 10.0 * consolidation * (0.5 + progress);

    // New-bin candidate handling: an empty bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_alternatives = if fitting_bins_count <= 1 { 0.5 } else { 0.0 };
        // Base cost of opening a new bin grows with stream progress.
        score += 80.0 - 60.0 * desperation - 30.0 * poor_alternatives - 20.0 * progress;
        // If next item is small, a fresh bin is more useful.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (keeps residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 5.0 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space is increasingly costly.
    let progress_coupling = norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0);
    score += 12.0 * progress_coupling;

    // Reward near-perfect fits, smoothly (peak at norm_pr -> 0).
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)) * 0.5);
    } else if next_item_size > 0 {
        // penalize leaving residual that likely becomes dead space
        score += 3.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: penalize slightly so it is chosen only for poor fits elsewhere,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - 0.5 * progress) + 4.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "nice" fractions of
    // capacity are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Reward residuals that are small but not uselessly tiny.
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else {
        // Harmonic class via integer division thresholds on post_residual.
        let cls = post_residual / 10; // 10-wide harmonic buckets
        let bucket_center = (cls * 10 + 5) as f64;
        // Penalize dead space: smaller residual better, but residue 1..9 is
        // nearly dead space — add a modulo-based penalty.
        let residue = post_residual % 10;
        score += residue as f64 * 0.6;
        score += (post_residual as f64 - bucket_center).abs() * 0.15;
    }

    // Coupling with next item (lookahead k=2): if next item fits exactly into
    // post_residual, strongly reward; if it nearly fits, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score += leftover as f64 * 0.35;
            // modulo harmony: leftover in a low harmonic class is good
            if leftover % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: slight penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize relative to how full open bins are.
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.12 + (open_bins_count as f64) * 0.4;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // reward using bins that are already relatively full
        let used = (bin_capacity - bin_residual) as f64 / cap;
        score -= used * 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fuller bins).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Reward tight fits (small but usable residual).
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual was already fragmented (low residual = nearly full bin).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing.
    let open_pressure = open_bins_count as f64 / 20.0;
    score += open_pressure * post_residual as f64 * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    // or the next item would fit the fresh bin much better.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 85.0;
        if post_residual >= 0 {
            // lookahead synergy: opening fresh bin helps if next item fits the
            // post-placement residual of this bin poorly but fits a fresh bin.
            if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
                new_bin_score -= 70.0;
            }
            // late in stream, prefer closing out bins tightly.
            let progress = step_index as f64 / total_items.max(1) as f64;
            new_bin_score += 40.0 * progress;
        }
        score = score.max(new_bin_score);
    }

    // Mean-residual coupling: if average residual is small, protect tight fits more.
    score -= (mean_residual / 10.0).min(5.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // closely matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus: subtract when post_residual ~ next_item_size
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match: huge reward
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a residual too small for the next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * post_residual as f64;
        }
    } else {
        // Last item: minimize leftover as usual
        score += 0.1 * post_residual as f64;
    }

    // Prefer tight fits overall
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Relative-to-mean coupling: bins tighter than the mean are better hosts
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 35.0 + 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins with more residual when many bins are open (consolidation)
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / cap;

    // Lookahead: if the next item fits in the post-residual, reward this bin
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0;
        // extra reward if next item fills bin almost exactly
        let combo_gap = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * (1.0 - combo_gap / cap).max(0.0);
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize leaving medium dead space
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 4.0 * (dead / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual close to mean (balance load), mild effect
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Time horizon: later in the stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Penalize opening new bins when many bins already fit the item mildly
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, reduced when few fitting bins exist
        score += 15.0 + 3.0 * (fitting_bins_count as f64);
        // late in stream, opening new bins is more acceptable for large items
        score -= 5.0 * progress;
    } else {
        // favor reusing already-open bins slightly
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized wasted space, non-linearly amplified with stream progress.
    let norm_waste = pr / cap;
    let mut score = norm_waste * (1.0 + 3.0 * progress * progress);

    // Smooth quadratic coupling between post_residual and mean residual:
    // favor bins whose leftover stays near the fleet mean (balanced packing),
    // penalize outliers.
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev * (1.0 + progress);

    // Reward tight fits: subtract a smooth function of small post_residual.
    let tight = (1.0 - norm_waste).max(0.0);
    score -= 1.5 * tight * tight * tight;

    // Penalize creating dead space that could fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_gap = (pr - nx) / cap;
            score += 1.2 * slack_gap * slack_gap; // leftover barely larger than next item = waste
            score -= 0.6 * (nx / cap); // but keeping room for next item is mildly good
        } else {
            // post_residual too small for next item: dead space penalty grows with progress
            score += 0.5 * (1.0 - pr / nx) * (1.0 + progress);
        }
    }

    // Scarcity bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin when a fit exists).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 1.5 * progress;
    }

    // Mild penalty per open bin to encourage consolidation, stronger late in stream.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: make it unattractive unless post_residual of alternatives
    // would be terrible; scale penalty with progress (late items should reuse bins).
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // modular classes (multiples of 10, and small residuals) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -5.0
    } else {
        4.0
    };
    score += class_bonus;

    // Integer-division thresholds: small residuals (< 10) are dead space.
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let fit_gap = (pr - next_item_size) as f64;
            score -= 20.0 - fit_gap * 0.5;
        } else {
            // next item cannot use this residual: mild penalty proportional to waste
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave ugly residual while the new bin keeps flexibility.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Fraction-of-capacity coupling: prefer residuals that are small fractions.
    score += 8.0 * (pr as f64 / cap);

    // Mean-residual divergence: bins far below mean residual are already tight;
    // prefer them to consolidate fragmentation.
    score -= 0.3 * (mean_residual - pr as f64).max(0.0);

    // Stream progression: early on, be conservative with new bins; late, allow
    // tighter packing (penalize large residuals more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64) * 0.15;

    // Harmonic modulo threshold on item_size: large items (>50) prefer bins
    // where they nearly fill the bin.
    if item_size > 50 {
        score += 0.2 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (especially tight fits); discourage opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to pressure and mean residual
        // of open bins (if open bins still have slack, opening is wasteful).
        score += 40.0 + pressure * 2.0 + mean_residual * 0.5;
    } else {
        // Slight reward for placing into open bins scales with pressure.
        score -= pressure * 0.3;
        // Prefer bins tighter than the average residual (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Aggressive 2-step lookahead: reward exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward leaving room for the next item, penalize large leftover gap
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            score += gap * 0.4;
        } else {
            // next item cannot fit here; dead space penalty grows with waste
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // last item: just minimize waste
        score += post_residual as f64 * 0.1;
    }

    // Relative to mean residual: prefer bins already below-average residual (denser bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // but allow new bin if lookahead chain works well there (post_residual == next_item_size handled above)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild penalty for many open bins: encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can fit: new bin is the only viable option.
            score -= 1000.0;
        } else {
            // Opening a new bin wastes capacity; penalize more for smaller items
            // (large residual left behind) and when alternatives exist.
            score += 35.0 + 0.4 * item_size as f64 - 0.2 * mean_residual;
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // Lookahead: reward if the next item can also fit in the leftover space.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 10.0 + 0.3 * next_item_size as f64;
            } else {
                // Penalize leftovers that the next item cannot use.
                score += 0.15 * (next_item_size - post_residual) as f64;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        score -= 5.0 * progress;
        // Reward bins that are tighter than the fleet average (good fits).
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let norm_post = pr / cap;
    let coupling = norm_post * (1.0 - progress * progress);
    score -= 12.0 * coupling;

    // Quadratic penalty on small post_residuals (dead space), amplified late in stream
    let dead = (1.0 - norm_post) * (1.0 - norm_post);
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) super-linearly
    score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);

    // Penalize deviation from mean residual (smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let fits_next = pr as f64 >= next_item_size as f64;
        if fits_next {
            score -= 5.0;
        } else {
            score += 4.0 * (next_item_size as f64 - pr).max(0.0) / cap;
        }
    }

    // New-bin candidate handling: mildly penalize early, allow late
    let is_new = bin_residual == bin_capacity && item_size == 0;
    if is_new {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (C/8 granularity). Residuals in "small" classes
    // (near 0) are dead space; penalize them, reward large usable leftovers.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1); // 0..=8
    score += (8 - class) as f64 * 2.5;

    // Exact-fit harmony: post_residual divisible by common item granularities
    // (mod arithmetic on harmonic classes) leaves room for typical small items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 5 == 0 { score -= 2.0; }
        if post_residual % 3 == 0 { score -= 1.0; }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100, min 1).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64 / bin_capacity as f64) * 4.0;
        } else {
            // Next item won't fit here either: mild penalty proportional to overshoot class.
            score += ((next_item_size - post_residual) / eighth.max(1)) as f64 * 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (item_size as f64 / bin_capacity as f64) * 6.0;
    }

    // New-bin candidate: penalize opening a new bin when the stream is early
    // (many items remain to consolidate) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + (1.0 - progress) * 10.0 + (open_bins_count as f64).sqrt() * 2.0;
        // But if mean residual across open bins is tiny, a fresh bin is attractive.
        score -= mean_residual.min(bin_capacity as f64) * 0.12;
    }

    // Tight-fit reward: filling a large fraction of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for dead space: gaps too small for the minimum item size (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0; // risky small gap, only tiny items can use it
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual as f64 <= (item_size as f64) * 0.15 {
        score -= 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins already open
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins and stream progress
        score += 15.0 + 3.0 * open_bins_count as f64 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if no open bin leaves a good gap, allow new bin more readily
        if post_residual == bin_capacity && mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Reward placing into bins whose residual is above-average (consolidate)
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        }
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if post-residual is just barely below the next item (awkward gap)
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: leftover exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // leftover can still hold next item: mild reward proportional to fit quality
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * gap.min(60.0);
        } else {
            // leftover too small for next item: dead-space penalty, worse when very small
            let dead = post_residual as f64;
            score += 40.0 * (1.0 - dead / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual already does this).
        score += 10.0;
    }

    // Reward last-chance bins (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless current bins are very full / unusable.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 {
            // opening a fresh bin is attractive if next item is large and current
            // residuals are small
            score -= (next_item_size as f64) * 0.3;
        }
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins below mean residual (compact the fuller bins).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Slight preference for reusing bins over growing the open set.
    score += 2.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 6.0 * tightness * tightness * (bin_residual as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty for awkward leftovers (classic bad gaps like 1..9 relative to item range)
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 4.0;
    }

    // Lookahead: if the next item can use the post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (next_item_size as f64) / (bin_capacity as f64));
        } else {
            // residual too small for next item -> penalize proportionally to wasted space
            score += 5.0 * ((next_item_size as f64 - post_residual as f64) / 100.0);
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation (favor filling existing bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = 1.5 + 2.0 * progress;
    score += consolidation * open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is below the mean residual (filling emptier bins less)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // New-bin candidate logic: an empty bin should only win when the fit is poor
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    if bin_residual == bin_capacity {
        // Opening a new bin is good for large items or when existing fit would leave big gaps
        if fill_ratio > 0.75 {
            score -= 20.0;
        } else {
            score += 12.0 * (1.0 - fill_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Non-linear waste penalty: small residuals are dead space, penalize quadratically
    let dead_penalty = (1.0 - x).powi(3) * 12.0;
    score += dead_penalty * (0.5 + progress);

    // Reward tight fits (post_residual near zero) more strongly over time
    let tight_reward = (1.0 - x).powi(2) * 20.0;
    score -= tight_reward;

    // Polynomial coupling of post_residual with progress
    let coupling = post * post / cap * (0.3 + 0.7 * progress * (1.0 - progress) * 4.0);
    score += coupling * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward scaled by how well next item uses the leftover
        let use_frac = next_item_size as f64 / post.max(1.0) as f64;
        score -= 8.0 * use_frac * use_frac;
    } else if next_item_size > post_residual {
        // leftover too small for next item: penalize
        score += 6.0 * (1.0 - x);
    }

    // Prefer filling bins when many bins are open (consolidation pressure)
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post / cap) * 3.0;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 4.0;

    // New-bin candidate: penalize mildly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual > 0 && post_residual < 15 {
            score -= 5.0; // opening a fresh bin is fine if this item would strand space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // (0, 25, 50, 75) are the most reusable "harmonics" of C=100.
    let r = post_residual;
    let harmonic = if r == 0 { 0.0 }
        else if r <= 5 { 0.0 }
        else if r % 25 == 0 { 1.0 }
        else if r % 10 == 0 { 2.0 }
        else if r % 5 == 0 { 4.0 }
        else { 8.0 };

    // Dead-space penalty: small non-harmonic residuals are wasted space.
    if r > 0 && r < 10 {
        score += 40.0 - (r as f64) * 2.0; // strongly penalize 1..9 slivers
    }

    score += harmonic * 3.0;

    // Perfect fit is always excellent.
    if r == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Reward proportional to how "harmonically" the next item lands.
            let nr = r - next_item_size;
            let next_harmonic = if nr == 0 { 0.0 } else if nr % 25 == 0 { 2.0 }
                else if nr % 10 == 0 { 4.0 } else if nr % 5 == 0 { 6.0 } else { 10.0 };
            score -= 15.0 - next_harmonic;
        } else {
            // Next item cannot follow here: mild penalty, worse if residual tiny.
            score += 5.0 + (10 - r.min(10)) as f64;
        }
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only open a fresh bin when the item is large
    // relative to capacity or current open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = open_bins_count as f64 * 1.5;
        // Base cost of a new bin: high, so it is chosen only for good reasons.
        score = 90.0 + item_size as f64 * 0.2 + open_penalty + fragmentation * 0.1 - progress * 5.0;
        if item_size >= 60 {
            score -= 25.0; // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 20.0; // reserve space logic for huge follower
        }
    }

    // Mild normalization pressure toward mean residual keeps bin set balanced.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..100),
    // i.e. near-zero, or if it is a tiny sliver (< 10) that likely never fits.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: strong penalty.
        score += 45.0;
    } else if post_residual <= 20 {
        // Small gap: mildly risky, penalize proportionally.
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    } else {
        // Larger usable gap: reward keeping usable space, decay with size.
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Open-bins pressure: prefer filling existing bins when many are open,
    // but allow opening new bins when few are open (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    // New empty bin candidate: it has maximal residual, so give it a fixed
    // opening cost that grows with open_bins_count pressure.
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * pressure;
    } else {
        // Reward using an existing bin more when pressure is high.
        score -= 2.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid wasting it
    // on a small item unless the fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 25.0 * tightness;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly prefer this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: mild penalty for leaving a gap
            // that the known next item cannot use.
            score += 8.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "leftover" bin; prefer concentrating items into it to close it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev.min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 5 {
                score -= 300.0;
            } else {
                // Favor bins where the two-item chain leaves small residue.
                score -= (chain_residual as f64).recip() * 60.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space relative to mean residual.
            let dead = post_residual as f64;
            score += dead * 0.3 + (dead - mean_residual).abs() * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize choosing a fresh bin unless the fit is excellent (encourage consolidation).
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual as f64 > mean_residual {
            score += 30.0;
        }
    }

    // Prefer tighter bins: deviation from mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: exact or near-exact fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);
    }

    // Penalize small unusable leftovers that can't host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if the post-residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (lots of stream left), penalize late.
        score += 40.0 * (1.0 - progress);
        // If many bins can fit, definitely don't open a new one.
        if fitting_bins_count > 1 {
            score += 120.0;
        }
        // If mean residual across open bins is large, avoid new bin.
        score += 0.4 * mean_residual;
        // If only one fitting bin and its post-residual would be tiny, new bin ok.
        if fitting_bins_count == 1 && post_residual < 5 {
            score -= 30.0;
        }
    } else {
        // Mild bonus for filling already-open bins to keep bin count low.
        score -= 5.0 + 0.1 * open_bins_count as f64;
    }

    // Fragmentation guard: penalize leaving residual just below common item sizes.
    let r = post_residual;
    if r > 0 && r < 20 {
        score += (20 - r) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;
    // Penalize dead space late in the stream, quadratically
    score += progress * norm_pr * norm_pr * (cap * 0.5);
    // Reward tight fits (small post_residual) more as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 3.0 * progress);
    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }
    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 5.0 * (1.0 - nd / cap).max(0.0);
    }
    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln1p() * (norm_pr - mean_residual / cap).abs();
    // New-bin candidate: penalize opening a bin unless current residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress - (mean_residual / cap).max(0.0) * 15.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact division classes of capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonic" — divisible-friendly small classes
    let harmonic_class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if harmonic_class == 0 {
        score -= 25.0; // multiple of 10: easy to fill later
    } else if harmonic_class <= 3 {
        score += 8.0 + 3.0 * harmonic_class as f64; // tiny dead space, penalize
    } else if harmonic_class >= 7 {
        score += 5.0; // awkward class
    }

    // Fraction-of-capacity thresholds via integer division
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score += 12.0; // nearly-full bin: good, but keep it slightly less attractive than exact multiples
        if post_residual <= quarter / 2 {
            score -= 6.0; // very tight bin, pack it out
        }
    } else if post_residual >= half {
        score += 15.0; // leaving a big hole is bad
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0; // chaining two items is excellent
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 && slack > 0 {
                score -= 8.0; // chain leaves harmonic residue
            }
        } else if next_item_size <= post_residual + 5 {
            score += 4.0; // near miss: bin will be stranded
        }
    } else {
        // last item: strongly prefer zero residual
        score -= pr * 0.5;
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // only bin that fits: avoid opening a new bin
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open a new bin only if existing bins are crowded or this is a poor fit elsewhere
        score = cap * 0.55 + mean_residual * 0.3 - 20.0 * progress;
        if item_size > half {
            score -= 10.0; // big items do well in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host a pair
        }
    }

    // Mild preference to fill bins tighter than the mean residual
    if (pr - mean_residual).abs() < 5.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Tie-break noise-free harmonic offset on item size class
    score - (item_size % 5) as f64 * 0.2
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small waste relative to item size).
    if item_size > 0 {
        score -= 30.0 * (item_size as f64 / (item_size as f64 + post_residual as f64));
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates below the mean (avoid wasting large residuals).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    // Open-bin pressure: discourage proliferation of bins, more so early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 - 0.3 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item would leave a big dead gap or barely fits anywhere).
    if bin_residual == bin_capacity {
        // Baseline penalty so it loses against decent fits.
        score += 30.0;
        // But relax the penalty when the item is large (few bins can host it anyway).
        score -= 0.25 * item_size as f64;
        // And when next item is large, a fresh bin offers flexibility.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving a residual that cannot host the (bounded) next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize wasted space
            score += 50.0;
        }
    }

    // Penalize small unusable dead space (< 10 minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare residual against mean residual: prefer bins with below-average residual (tighter fit)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for consolidating into fewer bins early vs late
    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * 10.0;

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 120.0;
        score += 200.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor bins where the item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize tiny post-residuals that are too small for the smallest item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 40 {
        score -= 10.0; // usable residual zone
    }

    // Lookahead coupling: reward if the next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    } else {
        // Last item: any bin that fits is fine, prefer most filled
        score -= 5.0;
    }

    // Last-chance bin bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding pressure: with many open bins, prefer reusing tight ones
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual anchoring: prefer bins below mean residual (tighter than average)
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to residual or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let openness = (item_size as f64 / bin_capacity as f64);
        score += 45.0 - 40.0 * openness * (1.0 - progress) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    // Mild time-decay on dead-space penalty: late in the stream, close bins tightly
    if post_residual < item_size && post_residual > 0 {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual, quadratic coupling with stream progress.
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear dead-space penalty: small residuals are penalized more as stream advances.
    let dead = (-pr_norm.ln().abs() + 1.0).max(0.0);
    score += 12.0 * dead * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (low post_residual relative to item), smoothly scaled.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: if next item fits into post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when only one fitting bin remains.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when this bin is far below the mean residual (fragmentation avoidance).
    score += 0.5 * (mean_residual - pr).abs() / cap * open_bins_count as f64;

    // New-bin candidate: penalize slightly unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score += if frag > 0.4 { 5.0 + 10.0 * frag } else { 25.0 - 20.0 * progress };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong bonus.
    let tight = (post_residual as f64) / cap_f;
    score -= (1.0 - tight) * 40.0;

    // Harmonic classes: post_residual divisible by small integers is more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.0; }
        else { score += 4.0; } // odd residuals pair poorly with even-ish items
    } else {
        score -= 25.0; // perfect closure
    }

    // Dead-space penalty: residual too small for typical items (harmonic class of 20).
    if pr > 0 && pr < 10 { score += 30.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 35.0; }
        else if next_item_size <= pr {
            score -= 8.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 6.0; // next item won't fit here; bin effectively dead
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 { score -= 20.0; }

    // Penalize opening new bins when many open bins exist with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        if mean_residual > cap_f * 0.3 { score += 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..min item size)
    // are pure waste; penalize them super-linearly.
    let min_item = 1u32;
    if post_residual < min_item.max(1) * 1 {
        score += 500.0; // perfect fit
    } else if post_residual <= 10 {
        // unusable dead space (nothing in 1..=10 range... but sizes can be 1..100, so
        // small gaps < 1 are impossible; treat tiny gaps as near-dead)
        score += 40.0 * (1.0 - post_residual as f64 / 11.0);
    } else {
        // Usable residual: reward proportionally to how "deep" it stays for future items,
        // but penalize moderate gaps less than dead gaps.
        score -= 0.0;
    }

    // Dead-space zone: gaps that can only fit very small items are risky.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Tight-fit reward: the smaller the leftover relative to the item, the better.
    if item_size > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness * tightness;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins
    // (penalize the new-bin candidate more when open_bins_count is high).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 6.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Reward using existing bins, more so as bins accumulate.
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, this is a great pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_tight / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: penalize slightly (dead space ahead).
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (close out fuller bins first, keep big gaps for big future items).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how well it fits
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 0.6 * post_residual as f64;
        }
    }

    // Reward tight fits relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 200.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Many fitting bins: mild penalty to prefer consolidating into fuller bins
    if fitting_bins_count > 1 {
        score += 20.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Compare against mean residual: bins below mean residual (fuller) preferred
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when open bins could fit (empty-bin candidate)
    if bin_residual == bin_capacity {
        // new bin is fine if no other bin fits or item is large
        if fitting_bins_count > 1 || (fitting_bins_count == 1 && bin_residual == bin_capacity) {
            score += 250.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty: small unusable remainders are wasted capacity
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.08 * snug;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But if mean residual is high (open bins are fragmented), new bin less bad
        score -= 0.05 * mean_residual;
    }

    // Time horizon: as stream progresses, be more conservative (favor existing bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // Mild preference for bins tighter than average
    score -= 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize large residuals more strongly
    score += 30.0 * progress * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small for any plausible item (1..100) are wasted
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 2.5 } else { 0.0 };
    score += dead;

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference against opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual deviates strongly from mean, mild penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Item-size interaction: large items prefer bins with moderate residual
    score += 6.0 * norm_it * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual divisible by 10 is "clean" residual
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 8.0;
    } else {
        // penalize awkward residues, worst near multiples of 5 but not 10
        let r = pr % 10;
        if r == 5 {
            score += 3.0;
        } else if r <= 3 || r >= 7 {
            score += 6.0;
        } else {
            score += 2.0;
        }
    }

    // Integer division thresholds on post_residual: dead space classes
    if pr < 10 {
        score += 15.0; // unusable sliver (min item 1..100, but small residual risky)
    } else if pr < 25 {
        score += 5.0;
    } else if pr < 50 {
        score -= 2.0;
    } else {
        score -= 4.0; // large residual is flexible
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0;
            // exact harmonic fit: pr % next_item_size == 0
            if pr % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it neutral-ish, slightly penalized
    // so it only wins when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.05 * open_bins_count as f64;
        // early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (good packing)
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
