pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the NEXT item exactly fills this bin after placement.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - lookahead_gap / (bin_capacity as f64)).max(0.0);
        // Exact 2-step match: huge bonus (post_residual becomes zero after next item).
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving residual too small for the next item (dead space trap).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0;
    }

    // Penalize large dead space relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Reward tight fits (small post_residual) more aggressively.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin when open bins fit well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Opening a new bin is attractive if it enables an exact 2-step match later
        // (residual 100 vs next item) — mild discount.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 10.0;
        }
    }

    // Compare against mean residual: bins with residual far above mean waste space.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to bin capacity (good fill).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * fill_ratio * fill_ratio;

    // Penalize dead space that next item could still use; reward if next item fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // Perfect pairing: current + next exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    } else {
        // Last item: maximize fill aggressively.
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 15.0 * (1.0 - progress);
        // If mean residual is small, opening new bin is more acceptable.
        score -= 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving post_residual in awkward low range (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Prefer bins with residual already below average (consolidate emptier bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Encourage using many open bins early (avoid hoarding one bin with big gaps).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: reward tight fit quadratically.
    let mut score = post * post / cap;

    // Smooth coupling: as stream progresses, tighten tolerance for wasted space.
    score += 0.8 * post * (0.5 + progress);

    // Penalize bins whose residual is far larger than the item (poor fill) —
    // smooth polynomial in normalized fill ratio.
    let fill_ratio = item_size as f64 / resid.max(1.0);
    score -= 6.0 * fill_ratio * (1.0 - fill_ratio * 0.5);

    // Lookahead: if the next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 4.0 + 6.0 * (1.0 - (post - nx) / cap);
        } else {
            // Next item won't fit; mild penalty scaled by leftover dead space.
            score += 1.5 * (post / cap) * (nx / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 5.0 * progress;
    }

    // New-bin candidate handling: opening a bin wastes capacity; only allow it
    // when no open bin fits well. Give it a smooth baseline penalty.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += pressure * (8.0 + 10.0 * (1.0 - progress)) + 3.0 * (mean_residual / cap);
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    score += 0.3 * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in the smallest classes (tiny dead
    // space) are good; large leftovers mean we "wasted" a big bin slot.
    let frac = post_residual as f64 / bin_capacity as f64;
    // integer-division thresholds on post_residual (harmonic classes k/8 of capacity)
    let class = post_residual / (bin_capacity / 8).max(1); // 0..=8
    let class_penalty = match class {
        0 => -30.0, // near-perfect fill: strongly reward
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,   // half-empty bin: mildly bad
        5 => 12.0,
        6 => 20.0,
        7 => 26.0,
        _ => 30.0,  // barely used bin: very bad
    };
    score += class_penalty;

    // Modulo arithmetic: residuals that are "compatible" with common small item
    // sizes (multiples of 10) are more reusable than awkward ones.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual >= 10 && post_residual <= 80 {
        score -= 2.0; // leftover falls in plausible item-size range
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // smooth reward proportional to how well next item fits
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: slight penalty scaled by gap
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post residual would be huge).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when stream is young or many
        // items remain (amortization) and when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 45.0 - 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            open_cost = -100.0; // nothing else available
        }
        score += open_cost;
        // an empty bin leaves a fresh full residual: neutralize base score
        score -= 0.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // filling below-average-residual bins keeps a spread of usable bins.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Small global pressure: slightly prefer tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible follow-up item) are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 40.0 * (10.0 - gap); // tiny slivers are pure waste
        } else if gap < 25.0 {
            score += 15.0 * (25.0 - gap) / 15.0; // likely dead space
        } else {
            // usable gap: mildly reward larger remaining flexibility
            score -= 0.15 * gap;
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to the bin's current residual (fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item can't use the gap: penalize proportionally
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (below-mean residual bins are closer to completion; finish them off).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate baseline: keep it attractive only when open bins are crowded
    // or the current fit is poor; otherwise make fresh bins slightly worse.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.4 * open_bins_count as f64 - 20.0 * (1.0 - fill_ratio);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when the next item fits snugly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Tightness relative to mean residual: prefer bins that stay below mean residual
    // (packing into the emptiest bins keeps tight bins available for small items).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when a decent fit exists (new bin has full residual).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Late in the stream, favor aggressive consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large or all open bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        score += 18.0 - 22.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can host a pair
        }
    }

    // Prefer bins below mean residual (preserving roomier bins for larger items).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // Mild consolidation pressure as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Discourage fragmenting when many bins are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (minimize post_residual). Late: tolerate
    // moderate residuals to keep large residuals available for big items.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let norm_post = post / cap;
    let np2 = norm_post * norm_post;
    let np3 = np2 * norm_post;

    // Cubic residual shaping modulated by progress: penalty grows
    // superlinearly in residual early, relaxes later.
    score += norm_post * np2 * cap * (0.8 - 0.5 * p3);

    // Dead-space risk: residual too small to fit any plausible item.
    // Smooth gate via polynomial in post_residual.
    let dead = if post > 0.0 {
        let t = (cap - post) / cap; // fill fraction
        (1.0 - t * t * t) * (post / 10.0).min(1.0)
    } else {
        0.0
    };
    score += dead * (8.0 - 4.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic).
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = post - n;
        let g = gap / cap;
        score -= 5.0 * (1.0 - g * g).max(0.0) * (1.0 - progress * 0.5);
    }

    // Spread pressure: penalize bins far from mean residual (polynomial).
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1 * (1.0 - progress);

    // Mild new-bin discouragement when many bins are open and fit exists.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes (mod 10) are favored.
    let class = post_residual % 10;
    score -= match class {
        0 => 12.0,          // perfectly harmonious leftover
        1 | 2 => 8.0,       // nearly tight
        3..=6 => 3.0,       // moderately useful
        _ => -4.0,          // awkward sliver class, penalize
    };

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless the fit is bad or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 0.45 * bin_capacity as f64;
        if poor_fit {
            score -= 10.0 + 20.0 * (1.0 - progress);
        } else {
            score += 18.0;
        }
    }

    // Lookahead coupling: if the next item would fit the post residual exactly
    // (harmonic complement), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to excess
            score += 2.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Encourage consolidation when many bins are open: prefer filling bins
    // below the mean residual (larger-than-average fill).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, prefer minimizing bin count aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items are nearly worthless. Penalize unusable gaps hard.
    if post_residual > 0 {
        // Dead-space severity: a gap that cannot hold even the smallest
        // plausible item (or the known next item) is heavily penalized.
        let min_useful = if next_item_size > 0 && next_item_size <= bin_capacity {
            next_item_size.min(30)
        } else {
            30
        };
        if post_residual < min_useful {
            // Gap too small to be useful: dead space penalty grows
            // as the gap shrinks relative to what is needed.
            score += (min_useful - post_residual) as f64 * 3.0;
        } else {
            // Usable gap: mild reward proportional to how much of the
            // gap remains exploitable.
            score -= (post_residual - min_useful) as f64 * 0.15;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit in the residual, the gap risks becoming dead.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating
    // into existing bins; a new empty bin should only win when it
    // offers a perfect or near-perfect start.
    let bin_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New bin candidate: attractive only when item is large relative
        // to capacity and many bins are open (packing fresh space).
        score += 20.0 + bin_pressure;
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward filling it deeply (small post_residual
        // relative to capacity) to close bins out.
        let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 15.0;
    }

    // Mean-residual coupling: when mean residual is large, packing
    // tightly matters more (avoid wasting collective space).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight late-stream tightening: as the stream progresses, be more
    // eager to fill bins fully rather than leaving scattered gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less when item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // 2-step lookahead: strongly reward bins where the NEXT item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits perfectly-ish: reward proportional to how snug the pair is
            let pair_slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - pair_slack / bin_capacity as f64);
            // perfect chain: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: penalize leftover dead space that is too small
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 20.0 * (10.0 - dead);
            } else {
                score += 0.5 * dead;
            }
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average
    score -= 3.0 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) / 20.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 30.0 - 10.0 * crowded.min(3.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big item first in fresh bin helps lookahead
        }
    }

    // Slight preference late in the stream to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (low post-residual), with quadratic decay
    // so that near-perfect fits are dramatically preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.035 * post * post / cap;

    // Dead-space penalty: residual too small to ever hold a plausible future item.
    let min_item = 1.0;
    if post > 0.0 && post < min_item * 3.0 {
        score += 40.0;
    } else if post > 0.0 && post < 10.0 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.25 * (item_size as f64);
    }

    // Lookahead: penalize bins whose post-residual can no longer fit the next item
    // if they currently could have (blocking penalty); reward bins that keep room
    // for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && (bin_residual as f64) >= nxt {
            score += 18.0;
        }
        if (post_residual as f64) >= nxt {
            score -= 6.0 + 0.05 * nxt;
        }
        // Perfect chain: post-residual exactly matches next item size
        if post_residual as f64 == nxt {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when existing
    // bins fit poorly. Penalize opening new bins when decent fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin: moderate so it only wins on bad fits.
        score += 30.0;
        // Early in the stream, opening bins is cheaper (build a spread of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins but mean residual is large (fragmented), new bin is fine.
        if mean_residual > 0.5 * cap {
            score -= 10.0;
        }
        // If next item is large, a fresh bin offers flexibility.
        if next_item_size as f64 > 0.6 * cap {
            score -= 12.0;
        }
    } else {
        // Prefer using bins whose residual deviates from the mean in a useful way:
        // bins with below-average residual are closer to closure; favor them.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev;
        // Slight penalty per extra open bin to encourage consolidation.
        score += 0.15 * open_bins_count as f64;
    }

    // Time-horizon modulation: late in the stream, prioritize closing bins tightly
    // (minimize leftover) since fewer future items remain to use residual space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * (bin_residual as f64 / cap);

    // Mild item-size coupling: large items should prefer large-residual bins.
    let size_frac = item_size as f64 / cap;
    score -= 10.0 * size_frac * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = post / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + 0.5 * pr_norm * (1.0 - progress);

    let mut score = post + 40.0 * poly;

    // Reward tight fits more aggressively as stream progresses
    score -= 8.0 * (1.0 - pr_norm).powi(3) * (1.0 + progress);

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 <= post_residual {
            score -= 12.0 * (1.0 - nd / cap);
        } else {
            score += 4.0 * (nd / cap);
        }
    }

    // Penalize opening a new bin when open bins exist and fit well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 && post_residual < bin_capacity / 4 {
            score -= 35.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter)
    score += 0.15 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover mod 10 classes.
    // Leftovers that are multiples of 10 are "harmonic" and more likely
    // to be filled by future items (sizes 1..100 often cluster on decades).
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // harmonic leftover: very reusable
    } else if class <= 3 {
        score += 3.0; // sliver leftover: near-dead space
    } else if class >= 7 {
        score += 1.5; // awkward leftover
    }

    // Integer-division thresholds on post_residual: big chunks stay usable.
    if post_residual >= 50 {
        score -= 4.0;
    } else if post_residual >= 30 {
        score -= 2.0;
    } else if post_residual <= 5 && post_residual > 0 {
        score += 5.0; // nearly full bin is fine only if we actually close it out
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fit: strongly reward
    }

    // Lookahead coupling: if the next item fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 8.0 - (slack as f64) * 0.15;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 2.0; // leftover likely wasted for the next item
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: residual == capacity. Only attractive when the item
    // is large (poor fit elsewhere) or few bins are open. Penalize otherwise
    // so we prefer packing into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 14.0                       // base cost of opening a bin
                 - size_frac * 10.0         // large items justify new bins
                 - (open_bins_count as f64) * 0.8
                 - (1.0 - progress) * 2.0;
        // If it would leave a harmonic half-empty bin, soften a bit.
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 3.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=15) are heavily penalized,
    // unless post_residual is 0 (perfect fit) which gets a large reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 6.0;
    } else if post_residual <= 25 {
        score += 12.0;
    }

    // Reward a fit that also accommodates the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // lookahead item forces a new bin anyway; prefer filling current bin more fully
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer packing existing bins tightly
    // over opening new ones; new-bin candidate gets a mild handicap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + (open_bins_count as f64).ln().max(0.0) * 0.5 + progress * 0.5;
    if bin_residual == bin_capacity {
        score += 5.0 * pressure;
    } else {
        score -= 2.0 * pressure;
    }

    // Prefer bins with residual close to mean (balance), slight tie-breaker.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Reward opening a new bin when the item leaves an awkwardly small post residual
        // in existing bins or when few bins can fit the item.
        if post_residual < 10 {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Early in stream, new bins are fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        return score;
    }

    // Core: reward tight fits (small post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward proportional closeness.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow in this bin; slight penalty scaled by mismatch.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize leaving dead space too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny dead space is fine (bin nearly full)
    } else if post_residual < 20 {
        score += 5.0; // awkward zone
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly: small post-residuals are fine,
    // large ones waste capacity.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect or near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin
    // (keeps a chain of pairings in one bin); otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
            // If next item cannot even fit an empty bin's worth of pairing,
            // slightly prefer tighter fills.
            if next_item_size + item_size > bin_capacity {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when the item is large (little dead space risk) or
    // when no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items: opening a fresh bin is fine (residual after is small).
        score -= 20.0 * fill_ratio;
        // Early in the stream, having many bins is cheaper later.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins are already open and fragmented, discourage more bins.
        score += 0.4 * open_bins_count as f64 * (0.3 + progress);
        // If mean residual is high (fragmentation), opening new bins wastes more.
        score += 0.05 * mean_residual;
    } else {
        // Prefer bins with residuals close to the item (tight fit), i.e. low
        // bin_residual relative to item size is good.
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 8.0 * tightness;
        // Slight preference for filling older/fuller bins to consolidate.
        score -= 0.02 * mean_residual;
        // Late in the stream, close bins aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);
    }

    // Discourage leaving residuals that are in the awkward 20-45 range
    // (too big to ignore, too small for typical items).
    if pr > 20.0 && pr < 45.0 {
        score += 10.0 * ((pr - 32.5) / 12.5).abs().min(1.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling: post-residual shaped by stream progress.
    // Later in the stream, waste (post_residual) becomes progressively more costly.
    let progress_waste = pr * (0.5 + 1.5 * progress * progress);
    score += progress_waste * 0.5;

    // Quadratic penalty on very small residuals (dead space), smoothed by a logistic gate.
    let dead = (1.0 - x) * (1.0 - x);
    score += dead * cap * 0.3 * (progress + 0.2);

    // Cubic interaction: near-perfect fills (x near 0) get strongly rewarded late.
    score -= cap * 0.4 * (1.0 - x).powi(3) * (0.3 + progress);

    // Lookahead coupling: reward if next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * snug * (1.0 + progress);
        } else {
            score += 4.0 + 8.0 * progress;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Slight penalty for proliferation of open bins relative to mean residual.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0) * 2.0;
    }

    // Smooth sigmoid tilt: bins that are neither full nor empty are mildly preferred
    // when many bins are open (consolidation pressure).
    let mid = 4.0 * x * (1.0 - x);
    score += mid * 1.5 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: tiny leftovers are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize leftovers in awkward harmonic classes (mod 10 bands).
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.35;

    // Reward near-perfect fits strongly (post_residual small => subtract).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Integer-division thresholds: leftover divisible into likely future items
    // (items often in multiples of 10). Reward post_residual in {20,30,...}.
    if post_residual >= 20 && post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space band
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; relax late in stream if bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 45.0 - 15.0 * progress;
        if mean_residual < item_size as f64 {
            open_cost -= 20.0; // existing bins are too full anyway
        }
        if fitting_bins_count == 0 {
            open_cost -= 40.0;
        }
        // Perfect-fit bonus for new bin when item is large
        if item_size >= bin_capacity - 10 {
            open_cost -= 30.0;
        }
        score = open_cost + (bin_capacity - item_size) as f64 * 0.5;
    }

    // Mild tightness preference: prefer fuller bins overall.
    score -= (bin_residual as f64 / cap) * 5.0;

    // Slight penalty for spreading across many bins when mean residual is high.
    if mean_residual > 40.0 && post_residual > 30 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64.min((item_size - 1) as f64);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins;
    // penalize opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 10.0;
    }

    // Mean residual coupling: bins far below mean residual are less attractive late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit bonus: strongly favor bins that end (nearly) empty.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward residuals that match the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post - next).abs();
        if next <= post {
            // Next item fits exactly into the leftover space -> chain bonus.
            score -= 25.0 * (1.0 - diff / cap.max(1.0));
        } else {
            // Next item would not fit: penalize proportionally to wasted potential.
            score += 10.0 * (next - post) / cap.max(1.0);
        }
        // Dead-space penalty: leftover too small for typical items (1..100).
        if post > 0.0 && post < next.min(20.0) {
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins that keep residual distribution tight,
    // and avoid leaving far more space than average (fragmentation risk).
    let dev = post - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    // (post_residual large relative to item size) and many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = post / (item_size.max(1) as f64);
        let pressure = open_bins_count as f64 / 10.0;
        score += 35.0 - 10.0 * pressure - 5.0 * (poor_fit - 1.0).min(3.0);
        // Late in the stream, slightly discourage opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * item_size as f64;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just minimize waste.
        score = post_residual as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual → prefer consolidating
    // into bins below the mean residual (filling the emptiest bins).
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 10.0 * dev;
        // If bin count is high, discourage opening new bins.
        if bin_residual == bin_capacity {
            score += 5.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Time horizon: late in the stream, be conservative — prefer filling existing
    // bins tightly rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild preference for bins that are already partially loaded (avoid bin sprawl).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Reward tight fits: non-linear coupling of post_residual with progress
    score -= (1.0 - pr / cap).powi(3) * (30.0 + 40.0 * progress);

    // Penalize large dead space, amplified later in the stream
    score += (pr / cap).powi(2) * (10.0 + 60.0 * progress * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 35.0 * progress;
    }

    // Lookahead: if next item can use the post residual, reward leaving useful space
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }

    // New-bin candidate handling: empty bin has pr == cap
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing fits are poor (large post residual)
        // and there are already many open bins with slack
        let poor_fit = pr / cap; // == 1.0 for new bin
        score = cap * 0.9 + (pr - mean_residual).max(0.0) * 0.5 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        let _ = poor_fit;
    }

    // Mild preference to consolidate: more open bins -> slightly favor filling existing ones
    score += open_bins_count as f64 * 0.05 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are "usable" classes; reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always ideal
    } else {
        let mut usable_bonus = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                usable_bonus += (d as f64) * 0.15;
            }
        }
        score -= usable_bonus;
        // Penalize residuals in awkward classes (prime-ish / tiny slivers)
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64;
        }
        // Integer-division threshold: residual that could host a mid item
        let class = pr / 10;
        score -= (class as f64).powi(2) * 0.4;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            score -= 20.0 + 0.5 * (pr - next_item_size) as f64;
        } else {
            // next item won't fit here; mild penalty for hoarding space
            score += 5.0;
        }
        // Harmonic coupling: next item size shares a divisor class with residual
        if pr % 10 == 0 && next_item_size % 10 == 0 && next_item_size <= pr {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer tighter bins: closeness of fit relative to capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // New-bin candidate handling: opening a bin is only attractive early in
    // the stream or when no open bin fits well (large post_residual penalty
    // above already discourages it). Make fresh bin neutral-ish otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference to fill bins when many are open (bin consolidation).
    score += 0.05 * open_bins_count as f64;

    // Mean-residual coupling: bins far below mean residual are less attractive.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score -= 500.0; // perfectly full bin is ideal
    } else {
        // Penalize gaps too small for any plausible future item relative to post_residual size.
        score += (dead_threshold - (post_residual as f64).min(dead_threshold)).abs() * 2.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 60.0;

    // Open-bin pressure: prefer existing bins when many are open; encourage consolidation.
    if bin_residual != bin_capacity {
        // existing bin: reward using it, more so as open bins accumulate
        score -= (open_bins_count as f64) * 8.0;
        // last-chance bin: strongly favor using the only bin that fits
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    } else {
        // new-bin candidate: penalize opening a new bin unless current bins are crowded
        score += 120.0 + (open_bins_count as f64) * 4.0;
        // but if item barely fits anywhere (tight fits absent), allow new bin
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good squeeze.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 1.5;
    } else {
        score += (bin_res_f - mean_residual) * 0.5;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 40.0;
    } else {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits perfectly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize post residuals that the next item cannot use.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly penalize so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly prefer minimal waste (superlinear).
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tight) * (1.0 - tight) * (item_size as f64 / bin_capacity as f64);

    // Exact fit gets a massive bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual (chaining),
    // penalize if this placement leaves a residual that is useless for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < 10 {
            // small dead space below min item size is nearly worthless
            score += 6.0;
        }
        // Bonus if residual after placing both would be tiny
        if post_residual >= next_item_size {
            let two_step = post_residual - next_item_size;
            if two_step == 0 {
                score -= 20.0;
            }
        }
    }

    // Last chance: this is the only bin that fits; strongly avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer filling fuller bins
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    // or the item is large and would leave badly fragmented residuals elsewhere.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (item_size as f64) / (bin_residual as f64)
        };
        // Default new bin is moderately expensive; discount when item is huge
        // (large items fragment open bins) or late in the stream (fewer future synergies).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_score = 45.0 - 20.0 * (item_size as f64 / 100.0) - 10.0 * progress;
        if fitting_bins_count == 1 {
            new_score += 35.0; // don't abandon the only fitting bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            new_score -= 10.0; // new bin pairs well with next item
        }
        score = score.max(new_score);
        return new_score;
    }

    // Global fragmentation penalty: if mean residual is small, conserve space aggressively.
    score += 0.05 * mean_residual * (1.0 - tight);

    // Slight preference for touching bins with larger residuals when item is small.
    if item_size <= 30 {
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let it = item_size as f64 / cap;

    // Base: penalize residual, scaled smoothly by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear polynomial coupling of residual with progress
    let coupling = pr_norm * pr_norm * (progress - 0.5) + pr_norm * (1.0 - pr_norm) * (1.0 - 2.0 * progress);
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual) more aggressively as stream advances
    score -= (1.0 - pr_norm).powi(3) * 15.0 * (0.5 + progress);

    // Penalize leaving dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (nx - pr) / cap;
        } else {
            score -= 6.0 * (pr - nx).min(nx) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    // Mean-residual deviation term (smooth quadratic)
    let dev = pr_norm - mean_residual / cap;
    score += 10.0 * dev * dev;

    // Item-size interaction: bigger items prefer fuller bins
    score -= it * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" sizes
    // (multiples of 10 or small enough to be fillable by typical items).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is king
    } else if pr % 10 == 0 {
        score -= 12.0; // aligned residual, likely reusable
    } else if pr < 10 {
        score += 25.0; // dead space below minimum item size
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 20; // 0..=5 harmonic class
    score += class as f64 * 4.0;

    // Coupling with next item: reward leaving room for the lookahead item
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 8.0 * (slack / cap).tanh();
            // exact pair fit bonus
            if pr == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 6.0; // lookahead item won't fit here
        }
    } else {
        score -= 15.0; // last item: any fit is fine
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing well-fitting open
    // bins, but allow opening when open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * open_bins_count as f64;
        // open a fresh bin if current item is large and would fragment open bins
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's
    // nearly full — finishing it is good.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 8.0 * (mean_residual - resid_f) / cap;
    } else {
        score += 4.0 * (resid_f - mean_residual) / cap;
    }

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are "dead space" — penalize heavily.
    let min_item = 1.0f64;
    let dead = if post_residual > 0 && (post_residual as f64) < 10.0 {
        60.0 + (post_residual as f64) // tiny unusable slivers are worst
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits: the smaller post_residual relative to item, the better.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus: exact fill of the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to capacity: unusable gap that no item 1..100
    // typically fills well (e.g. 1..9 or awkward mid gaps).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Open-bins pressure: when many bins are open, prefer reusing existing
    // bins (subsidize reuse); the new-bin candidate has bin_residual == capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but less when nothing fits well.
        score += 30.0 + 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, opening a bin is fine
        }
    } else {
        // Reuse subsidy grows with pressure.
        score -= 6.0 + 4.0 * pressure;
        // Last-chance bin: strongly favor using the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item won't fit here; mild penalty proportional to waste
            score += 5.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already well-utilized; finishing it is good.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with small slack.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.15);
    }
    // Next item cannot use this residual: penalize proportionally to wasted space.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Reward tight fits relative to mean residual across open bins.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55;
        score += base;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if open_bins_count > 3 {
            score += 15.0 * open_bins_count as f64;
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - residual_f / bin_capacity as f64);

    // Penalize leaving tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tight = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - lookahead_tight / bin_capacity as f64);
    }
    // Penalize if next item is large and would be stranded by small residual.
    if next_item_size > post_residual && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty for opening a new bin
        // If no existing bin fits well, opening is attractive.
        if item_size > 0 && bin_capacity - item_size < post_residual {
            score -= 20.0;
        }
        // Late in stream with many open bins, prefer consolidation instead.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        if open_bins_count > 3 {
            score += 2.0 * open_bins_count as f64;
        }
    }

    // Global state coupling: bins with residual far from mean residual are
    // attractive targets if this item brings residual closer to the mean.
    let new_gap = (post_residual as f64 - mean_residual).abs();
    let old_gap = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (new_gap - old_gap);

    // Prefer filling bins that already have moderate load (avoid many half-empty bins).
    let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * load_frac * load_frac;

    // Early stream: keep flexibility by mildly penalizing very small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && progress < 0.5 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // Tight fit reward (smooth, no piecewise): penalize large residuals more as stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead coupling: reward if next item can fit into post residual (smooth bonus)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let fit_quality = 1.0 - (fits_next / cap);
        score -= 18.0 * fit_quality * (1.0 - (nx / cap));
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: keep it neutral-ish, slightly penalized so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 5.0 * (open_bins_count as f64).sqrt();
        // But if the item fills a fresh bin well, smooth discount
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: avoid worsening already-fragmented state
    score += 0.15 * mean_residual * norm_pr;

    // Slight penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space penalty for residuals that are too small for any item (sizes >= 1)
    // but awkwardly small relative to typical item sizes (10..80 range and unknown dist).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Harmonic band rewards: residuals matching "nice" capacity fractions are reusable
    let bands: [f64; 6] = [0.0, 0.125, 0.25, 0.5, 0.75, 1.0];
    let mut best_band_dist = f64::INFINITY;
    for b in bands.iter() {
        let d = (frac - b).abs();
        if d < best_band_dist {
            best_band_dist = d;
        }
    }
    score += best_band_dist * 20.0;

    // Integer-division threshold on post_residual: multiples of common item classes
    if post_residual >= 10 {
        let class = post_residual / 10; // harmonic decade class
        score -= (class as f64) * 2.5;
    }

    // Exact-fit reward: post_residual is a multiple of item_size or zero
    if post_residual == 0 {
        score -= 60.0;
    } else if item_size > 0 && post_residual % item_size == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // harmonic match: post_residual equals next item size exactly
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless it's early
    // in the stream or open bins are congested (low mean residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - post; // = 0 for empty bin, baseline
        score += 15.0 + 20.0 * (1.0 - progress); // prefer new bins early
        if mean_residual > 40.0 {
            score -= (mean_residual - 40.0) * 0.5; // open bins congested -> new bin ok
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading too thin when many bins are open
    score += (open_bins_count as f64) * 0.3;

    // Modulo coupling with capacity: residual that divides capacity evenly is valuable
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are unusable dead space; penalize them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 3.0;
        // If the lookahead item could combine with the residual left here,
        // opening a new bin is slightly more attractive.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (future packing freedom).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // but only mildly, so dead-space logic dominates.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight preference for fuller bins when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly (creates a perfect two-item chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect lookahead match: strong bonus (subtract heavily).
        if gap == 0.0 {
            score -= 60.0;
        } else if gap <= 5.0 {
            score -= 40.0 - gap * 6.0;
        } else {
            // Penalize leaving a residual the next item cannot use.
            score += gap * 0.35;
        }
        // If next item fits into the post-residual, mild reward.
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: minimize leftover waste strongly.
        score += post_residual as f64 * 0.5;
    }

    // Compare post_residual relative to mean residual of open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.25;

    // Last-chance bin: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can fit the item,
    // unless the fit would be terrible (large dead space).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of consuming fresh capacity.
        score += 15.0;
        // If this bin would leave little waste, opening is attractive.
        if post_residual <= 10 {
            score -= 30.0;
        }
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 20.0;
        }
    } else {
        // Tight fit reward: small post residual is good.
        if post_residual <= 5 {
            score -= 12.0;
        } else if post_residual > 40 {
            // Large unusable-looking leftover: penalize.
            score += (post_residual as f64 - 40.0) * 0.4;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    } else {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize large leftover gaps that small future items could still use.
    if post_residual > 0 {
        let gap = post_residual as f64;
        score += 0.02 * gap * (gap / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let mut penalty = 20.0 + 10.0 * (1.0 - progress);
        // If item is large relative to capacity, new bin is more acceptable.
        penalty -= 12.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is huge, saving residual space is valuable -> soften penalty.
        if next_item_size > 0 && next_item_size >= bin_residual {
            penalty -= 8.0;
        }
        // Many open bins with slack: discourage adding another.
        penalty += 1.5 * (open_bins_count as f64).sqrt();
        score += penalty;
    } else {
        // Existing bin: mild bonus when its residual is below average (using slack efficiently).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 10.0;
        } else if diff <= 10 {
            score -= 5.0;
        } else {
            score -= 2.0 * (1.0 - diff as f64 / bin_capacity as f64);
        }
    }

    // Late in stream: consolidate, avoid wasting near-full bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize small residuals mildly);
    // later, squeeze aggressively (reward small residuals).
    let coupling = (progress - 0.5) * (1.0 - x) * (1.0 - x);
    score -= 30.0 * coupling;

    // Dead-space penalty: residuals too small to ever fit typical items.
    let min_item = 1.0f64;
    let dead = ((min_item - x).max(0.0) / cap) * 40.0;
    score += dead;

    // Lookahead: reward leaving room for the next item if it fits nicely.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score -= 12.0 * (-fit_gap / 25.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x * cap;

    // Mean-residual alignment: prefer bins close to the mean residual (balanced use).
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by progress
    // and how poorly the item would otherwise fit.
    if bin_residual == bin_capacity {
        let new_bin_cost = 60.0 - 25.0 * progress - 0.2 * (fitting_bins_count as f64);
        score += new_bin_cost.max(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Harmonic class of post_residual: residual divisible by common item sizes is reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = 0.0;
        if pr % 10 == 0 { reusable += 1.0; }
        if pr % 20 == 0 { reusable += 0.8; }
        if pr % 25 == 0 { reusable += 0.8; }
        if pr % 50 == 0 { reusable += 0.6; }
        score -= 4.0 * reusable;
        // Dead zone: tiny unusable slivers (1..10) are wasted space.
        if pr < 10 {
            score += 6.0;
        } else if pr < 20 {
            score += 2.0;
        }
    } else {
        // Perfect fill.
        score -= 15.0;
    }

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 20.0; // chain completion
        } else if pr - next_item_size < 10 {
            score -= 6.0; // next item nearly fills
        } else {
            score -= 3.0;
        }
    }
    // Next item cannot fit this bin after placement: mild penalty if bin becomes stranded.
    if next_item_size > pr && pr > 0 {
        score += 1.5;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins only win when all fits are poor.
        score += 8.0;
        // More open bins with slack -> avoid opening yet another.
        score += (open_bins_count as f64).sqrt() * 1.5;
        // Late in stream, prefer packing into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
    } else {
        // Existing-bin bonus scaled by how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 4.0 * fill;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is an outlier worth filling.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful item (below the typical minimum item size) are
    // pure waste. Penalize them super-linearly.
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    } else {
        // Reward near-perfect fits: the tighter the remaining gap,
        // the better the utilization of this bin.
        score -= (item_size as f64 / bin_residual as f64) * 15.0;
    }

    // If the leftover gap exactly accommodates the lookahead item,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If the leftover gap cannot fit the lookahead item but the bin
    // residual could, mildly penalize (lookahead may prefer this bin now).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure
        // unless the item fits terribly everywhere (large post_residual elsewhere).
        score += pressure * 6.0;
        // But allow a new bin when the item is large and mean residual is small.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: small reward for keeping bin count low.
        score -= pressure * 0.5;
        // Prefer bins with residuals close to the item (tight fit) over
        // bins with huge residual when many bins are open.
        if (bin_residual - item_size) as f64 > mean_residual {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match => big bonus (subtract)
        if diff == 0.0 {
            score -= 60.0;
        } else if next_item_size as u32 <= post_residual {
            // next item still fits after this placement: mild reward scaled by closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit in the residual: penalize wasted space
            score += 15.0 + diff * 0.2;
        }
    } else {
        // last item: prefer tightest fit
        score -= 40.0;
    }

    // tightness: reward small post_residual relative to item size
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // penalize leaving residual far below mean (fragmentation) only when many bins open
    if open_bins_count > 1 {
        let dev = post_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.1 * dev;
        }
    }

    // discourage opening a new bin when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 35.0; // big next item: better to start fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is highly desirable
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                score -= 8.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // Dead space relative to the next item's needs
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    } else {
        // Last item: prefer tightest fit only
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 40.0;
        // More open bins with slack -> opening new bins is less attractive
        score += 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds options)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual is large, existing bins have room: discourage new bin
        score += 0.3 * mean_residual;
        // If the item is large, a fresh bin is fine (keeps big-item flexibility)
        score -= 0.2 * item_size as f64;
        // If no other bin can fit, new bin is the only option: soften penalty
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins with residual close to item size (tight fit reward)
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 5.0 * tightness;
        // Slight preference for bins below mean residual (consolidate emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    // Mild penalty for very small post-residuals that are dead space (< 10 unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // smooth polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * (1.0 + 2.0 * progress * progress) * (1.0 - 0.5 * fill * progress);

    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // reward tight fits, more strongly late in the stream
    score -= fill * fill * (30.0 + 50.0 * progress);

    // penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs();

    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 30.0 * progress;
    }

    // lookahead: if next item fits into the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
    }

    // many open bins: prefer filling existing ones over opening new
    score -= (open_bins_count as f64).ln() * (1.0 + progress) * 2.0;

    // new-bin candidate should look expensive unless residuals are badly fragmented
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 0.5 * mean_residual;
    }

    score * coupling.max(0.1)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    // Classes via integer division thresholds on post_residual (capacity 100).
    let post_class = match post_residual {
        0 => 0u32,          // perfect fill
        1..=5 => 1,         // near-perfect
        6..=15 => 2,        // small dead space
        16..=30 => 3,       // medium
        31..=50 => 4,       // half-ish
        _ => 5,             // large leftover
    };

    // Modulo arithmetic: residuals that are multiples of common item sizes are
    // "harmonic" — future items can tile them exactly. Reward those.
    let harmonic_bonus: f64 = if post_residual == 0 {
        -40.0
    } else if post_residual % 10 == 0 {
        -12.0
    } else if post_residual % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Class-based additive penalty (non-linear escalation of dead space).
    score += match post_class {
        0 => -25.0,
        1 => -10.0,
        2 => 0.0,
        3 => 8.0,
        4 => 18.0,
        _ => 30.0,
    };

    // Lookahead coupling: if the next item fits the post residual exactly or
    // nearly, this bin is a great choice — chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to wasted harmony
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.25;
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: empty bin. Penalize it so we prefer good existing fits,
    // but allow it when post_residual of existing fits would be large (its own
    // score already reflects that via class penalty).
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheap-ish; late, conserve bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Slight preference for tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Prefer using many open bins well rather than fragmenting.
    if open_bins_count > 0 {
        score -= (open_bins_count.min(20) as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit any future item
    // (sizes 1..=100) are pure waste. Penalize small unusable gaps heavily.
    if post_residual > 0 {
        // gap smaller than the smallest plausible item => dead space
        if post_residual < 10 {
            score += 60.0;
        } else {
            // smooth penalty growing as residual shrinks toward unusability
            let gap = post_residual as f64;
            score += 12.0 * (10.0 / gap).powf(1.5);
        }
    }

    // Reward tight fills (best-fit flavor): subtract for small post_residual.
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.9;

    // Mean-residual coupling: if average residual is large, we can afford loose fits;
    // if residuals are scarce, be pickier (amplify dead-space penalty).
    score += (mean_residual - post_residual as f64).abs() * 0.25;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: baseline cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well.
        // Give it a moderate default score; it wins only when all fits are bad.
        score = 100.0 + open_bins_count as f64 * 0.5;
        if post_residual == bin_capacity {
            // fresh bin keeps full capacity: slightly better than a wasted fit
            score -= 5.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: the gap is likely dead space
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is disproportionately bad).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0 + (5.0 - post_residual as f64) * 8.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // can exactly fill the post residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 300.0; // perfect 2-chain: item + next item fills bin
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 120.0 - lookahead_gap * 10.0;
        } else if next_item_size as u32 <= post_residual {
            // next item fits, but imperfectly: mild reward scaled by snugness
            score -= 20.0 * (1.0 - lookahead_gap / 100.0);
        } else {
            // next item does NOT fit into this bin's residual: penalize
            // leaving a gap that strands the lookahead item.
            score += 25.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    // (consume the fullest bins first, keep loose bins flexible).
    let diff = mean_residual - post_residual as f64;
    score += diff * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when good open bins exist and lookahead is small.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size <= item_size && fitting_bins_count > 0 {
            score += 30.0;
        }
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Slight preference for new bins early in the stream (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual after placement is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small for typical future items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (within small gap), mild reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 4.0;
        }
    }
    // Penalize if post-residual is large but next item can't use it (waste risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 20 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is penalized unless the item fits
    // nowhere well or open bins are very full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_tight = 1.0 - mean_residual / (bin_capacity as f64);
        // Base penalty for wasting a fresh bin.
        score += 25.0;
        // If existing bins are nearly full on average, opening a new bin is fine.
        score -= 30.0 * mean_tight * mean_tight;
        // Late in the stream, avoid opening bins for small items.
        if item_size < 30 {
            score += 10.0 * progress;
        }
        // Large items with no good home: allow new bin more readily.
        if item_size > 60 {
            score -= 8.0;
        }
    } else {
        // Prefer using fuller existing bins (waste less capacity).
        let fill_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill_frac;
    }

    // Slight preference to keep number of open bins manageable when many are open.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.05;
    }

    // Mild noise-free tie-breaking via residual parity structure.
    score += (post_residual % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear penalty on wasted residual: quadratic coupling with capacity
    let waste_norm = post / cap;
    score += 18.0 * waste_norm * waste_norm * cap * (0.5 + 0.5 * progress);

    // Reward tight fits: sigmoid-like bonus when post_residual is small
    let tightness = (-post / (0.08 * cap)).exp();
    score -= 12.0 * tightness;

    // Favor bins whose residual is close to the item size (good fill ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * (fit_ratio * fit_ratio);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly early, more when open bins are already empty-ish
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 + 10.0 * (1.0 - mean_norm) - 6.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-gap / (0.1 * cap)).exp();
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "usable" is the leftover space?
    // Class residuals into buckets of 10 (capacity fractions of C=100).
    let residual_class = post_residual / 10;
    let harmonic_waste = (post_residual % 10) as f64;
    score += harmonic_waste * 0.15;

    // Reward small residuals strongly (tight fits), with a non-linear bump.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize mid-range dead space quadratically.
    if post_residual > 20 && post_residual < 50 {
        let r = post_residual as f64;
        score += 0.008 * (50.0 - r) * (50.0 - r);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // fits well (post_residual would be large) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (1.0 + progress);
        // Opening a bin is cheap early, expensive later.
        score += 30.0 + pressure * 12.0;
        // But if this item is huge and lookahead is also large, fresh bin is fine.
        if item_size >= bin_capacity / 2 && next_item_size >= bin_capacity / 3 {
            score -= 35.0;
        }
        // Penalize new bin if an open bin would leave a harmonically small residual.
        let pr_class = post_residual / 10;
        if pr_class <= 2 {
            score += 50.0; // don't open new bin when a tight fit exists
        }
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this bin heavily (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Modulo-10 harmonic alignment between item and residual classes.
    let item_class = item_size % 10;
    let res_class = bin_residual % 10;
    if item_class == res_class && post_residual % 10 == 0 {
        score -= 8.0; // aligned classes yield clean leftovers
    }

    // Mean residual context: if this bin's post residual is far below the
    // mean, it's a good consolidation; penalize being far above.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.10 * (mean_residual - pr);
    } else {
        score += 0.05 * (pr - mean_residual);
    }

    // Encourage closing nearly-full bins: fewer open bins is better.
    if post_residual <= 5 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (assumed ~10) are unusable -> hard penalty scaled by how "dead" they are.
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual in small usable range).
    if post_residual <= 20 && post_residual >= 1 {
        score -= 12.0 * (20 - post_residual) as f64 / 20.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit relative to current residual: favor bins where the item
    // consumes a large fraction of the available space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Dead-space relative penalty: post_residual as fraction of capacity.
    score += 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / (1.0 + progress * 4.0)) * 0.35;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere
    // are very small (i.e., existing bins are nearly full).
    if bin_residual == bin_capacity {
        let consolidation_urgency = (mean_residual - item_size as f64).max(0.0);
        score += 25.0 - consolidation_urgency.min(25.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item could have fit in this bin but won't fit after placement.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits here afterwards: reward tight chains.
            score -= (bin_capacity as f64 - gap.max(0.0)) * 0.35;
            if gap == 0.0 {
                score -= 25.0; // perfect two-item chain
            }
        } else {
            // Post-residual too small for next item: dead space penalty scaled by tightness.
            let waste = post_residual as f64;
            score += waste * 0.6;
        }
    } else {
        // Last item: minimize residual as usual.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.1;
    }

    // Prefer bins tighter than the mean (best-fit style).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 12.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let base = 18.0 + item_size as f64 * 0.15;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += base + scarcity;
    }

    // Slight preference for consolidating into fewer bins mid-stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    if post_residual > 0 {
        score -= (item_size as f64 / post_residual as f64) * 4.0;
    } else {
        score -= 20.0; // perfect fill
    }

    // Penalize post_residual that is too small to ever be useful (dead space).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 12.0 - (gap as f64 * 0.15);
    }
    // If next item would NOT fit here, mild penalty (this bin's residual is a dead end).
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when open bins are
    // fragmented (high mean residual but none fit well) or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin, discounted when many bins are open/fragmented.
        let mut open_cost = 25.0;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        open_cost -= fragmentation * 10.0;
        open_cost -= progress * 5.0;
        // If the item leaves a large residual in a fresh bin (small item), penalize slightly.
        open_cost += (post_residual as f64) * 0.1;
        // If no existing bin fits, opening is the only option: make it cheap.
        if fitting_bins_count == 0 {
            open_cost -= 40.0;
        }
        // Lookahead: fresh bin can host the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            open_cost -= 5.0;
        }
        score = open_cost + (post_residual as f64) * 0.05;
    }

    // Global pressure: when many bins are open, prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.3;

    // Time horizon: late in the stream, avoid spreading items; reward filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    }

    // Mild penalty for using a bin whose residual deviates far from mean (keep diversity).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr.powf(1.5) * (1.0 + 0.5 * progress);

    // Polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 50.0
                 + norm_pr * progress * progress * 30.0;
    score += coupling;

    // Penalize residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - (pr - ns) / cap);
        }
    }

    // Reward scarce fitting capacity
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.5 * progress;

    // New-bin candidate: keep it available but not dominant unless nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) - 10.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item classes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // Dead space: small unusable residuals are penalized quadratically.
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
    }

    // Lookahead coupling: reward residuals that can host the next item,
    // penalize residuals that nearly-but-not-quite fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size { score -= 6.0; }
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere in this bin anyway; slight relief
            score -= 1.0;
        } else {
            score += 5.0; // teases but fails
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are
    // fragmented (high mean residual spread) or none fit well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 { score -= 40.0; }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 { score -= 10.0 * (1.0 - progress); }
    }

    // Mild best-fit sharpening relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 9.0f64;
    if post_residual >= 1 && (post_residual as f64) <= dead_zone_max {
        score += (dead_zone_max - post_residual as f64 + 1.0) * 25.0;
    }

    // Reward near-perfect fits (post_residual <= 10 but still usable).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual tightly matches the item (tight fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits in the post residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for next item -> mild penalty.
        score += 5.0;
    }

    // New-bin candidate baseline: neutral anchor so it's chosen only when
    // every open bin scores worse (poor fits / dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 2.0 - (mean_residual / 10.0);
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // 2-step perfect chain: item + next item exactly fills the bin.
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.5 * chain_slack;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space more if it's large relative to mean.
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Reward near-exact fits of the current item.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins early or when next item is big and current item small.
        let big_next = next_item_size as f64 >= 0.6 * bin_capacity as f64;
        if big_next && item_size <= 40 {
            score -= 10.0;
        } else {
            score += 8.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many bins (consolidation pressure).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating small unusable dead space (below min item size 1..10 zone).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fit_ratio < 0.5 {
            score += 15.0 * (0.5 - fit_ratio);
        }
        // Late in the stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Few open bins relative to stream: new bins are cheaper early.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty for wasting space.
            score += 5.0;
        }
    }

    // Global state: when mean residual is high, be pickier about wasteful placements.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // 0..1
    let progress_weight = 0.5 + 1.5 * t * t; // tighter packing demanded later
    score += progress_weight * norm_pr * norm_pr * cap * 0.6;

    // Reward near-perfect fits (small post residual) with cubic discount
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight;

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - gap * gap);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (nxt / cap);
        }
    } else {
        // last item: prefer zero residual aggressively
        score -= 8.0 * tight;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with less residual among many candidates
        score += 0.15 * (fitting_bins_count as f64).ln() * norm_pr * cap;
    }

    // Mean residual context: penalize bins far above mean residual (avoid stranding space)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.1;

    // New-bin candidate handling: empty bin gets baseline so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * t;
        // but if item is large relative to capacity, new bin is more acceptable
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Slight penalty for spreading across many open bins late in stream
    score += 0.02 * (open_bins_count as f64) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: prefer leftovers that are "usable" residue classes.
    let pr = post_residual;
    // Zero residual is perfect.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Class bins by residue modulo 10 (harmonic granularity of typical item sizes).
        let r10 = (pr % 10) as f64;
        score += r10 * 2.5; // penalize non-aligned leftovers

        // Small unusable slivers are dead space.
        if pr < 10 {
            score += 30.0;
        } else if pr <= 20 {
            score -= 10.0; // a small item could still land here
        }

        // Integer-division thresholds: leftover big enough for medium items is valuable.
        if pr >= 50 {
            score -= 15.0;
        } else if pr >= 30 {
            score -= 7.0;
        }

        // Lookahead coupling: does the next item fit exactly / at all in the post residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 500.0; // perfect chaining
            } else if next_item_size <= pr {
                let slack = (pr - next_item_size) as f64;
                score -= 20.0 - slack * 0.3;
            } else {
                score += 12.0; // next item cannot use this leftover
            }
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Opening a bin is more attractive early when many placements remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // Attractive if next item is large and current bin can't chain it.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64) * 0.5;

    // Tie-break: prefer bins whose residual is close to item size (tight fits).
    score += ((bin_residual as f64) - (item_size as f64)).abs() * 0.1;

    // Mean residual coupling: if this bin is far from mean, slight penalty.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any future item
    // (1..=10 range) are "lost" capacity. Penalize them quadratically.
    if post_residual < 10 {
        score += (11.0 - post_residual as f64) * 20.0;
    }

    // "Almost-full" bonus: exact or near-exact fits are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item leaves a large, reusable residual AND open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Neutral baseline: a fresh bin with the item inside.
        score += 8.0;
        // Pressure: more open bins => discourage opening yet another one.
        score += open_bins_count as f64 * 3.0;
        // If the next item could combine with this item's residual, opening
        // a fresh bin is more attractive (residual = capacity - item).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in the stream, fresh bins are cheaper; late, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Existing bin: reward tight fits relative to the item size.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Slight penalty if this bin is much emptier than average (save big
        // residual bins for larger future items).
        if (bin_residual as f64) > mean_residual + 25.0 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if the post-residual exactly matches the next item,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (zero dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable residuals (dead space)
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits too: reward tighter chain packing
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            let overhang = next_item_size as f64 - post_residual as f64;
            score += 40.0 * (overhang / 100.0).min(1.0);
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are "normal";
    // prefer placing into bins whose residual is small (tight bins) when fit is tight.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Mild preference to keep many bins consolidated when stream is early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: penalize opening a new bin unless it enables a perfect
    // two-item pairing with the lookahead item.
    if bin_residual == bin_capacity {
        score = 100.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let pair_waste = bin_capacity - item_size - next_item_size;
            score -= (100.0 - pair_waste as f64) * 0.9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where item nearly fills residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small post-residuals that are too small for typical future items,
    // reward residuals that remain usable (>= next item or >= ~20).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if post_residual < 10 {
            score += 8.0 * (1.0 - post_residual as f64 / 10.0);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = cap - item_size as f64; // residual of fresh bin
        nb -= 4.0; // mild bonus so new bin isn't auto-losing
        // As stream matures or many bins open, discourage proliferation.
        nb += 10.0 * progress;
        nb += 1.5 * open_bins_count as f64;
        // If mean residual of open bins is large, prefer reusing them.
        nb += 0.3 * mean_residual;
        // If lookahead item fits in fresh-bin residual, slight bonus.
        if next_item_size > 0 && (nb + 4.0) >= next_item_size as f64 {
            nb -= 3.0;
        }
        return nb;
    }

    // Discourage leaving residuals in the awkward 1..=9 band after placement.
    if post_residual >= 1 && post_residual <= 9 {
        score += 10.0;
    }

    // Global state coupling: many open bins with small mean residual -> prefer tight reuse.
    if open_bins_count > 3 && mean_residual < 25.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // normalized post residual
    let npr = pr / cap;
    // smooth non-linear coupling: tight fits rewarded more as stream progresses
    let tight = (1.0 - npr).powi(3);
    score -= tight * (2.0 + 6.0 * progress) * cap * 0.05;
    // penalize large dead space quadratically
    score += 0.6 * npr * npr * cap;
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx) / cap;
        if slack >= 0.0 {
            score -= 1.5 * (1.0 - slack.abs()) * (0.5 + progress);
        } else {
            score += 2.0 * (-slack) * cap * 0.05;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }
    // mild penalty for spreading across many bins late in stream
    score += 0.1 * (open_bins_count as f64) * progress;
    // pull toward mean residual balance
    score += 0.2 * (pr - mean_residual).abs() * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "usable" classes.
    let r = post_residual % 10;
