    // match a plausible future item size class.
    match r {
        0 => score -= 25.0,
        1 | 2 | 3 => score += 6.0 + 2.0 * r as f64,
        4 | 5 | 6 => score += 1.5 * r as f64,
        _ => {} // 7..9 residues are relatively reusable, no penalty
    }

    // Integer-division threshold on post_residual: how many "typical" chunks fit.
    let chunks = post_residual / 10;
    score -= 3.0 * chunks as f64;

    // Coupling with lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if it nearly fits, penalize the near-miss.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            score -= 10.0 + (next_post % 10) as f64 * -0.5;
        } else {
            // next item cannot use this residual: residual value decays
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it less
    // attractive than a good fit but attractive when fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Open a new bin early in the stream or when few bins fit the item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count <= 1 || progress < 0.1 {
            score -= 55.0;
        }
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Tight fit reward: fraction of capacity filled.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // when the stream is mature.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual && progress > 0.3 {
        score -= 4.0;
    }

    // Modulo threshold on item size: large items (harmonic class >= 50) should
    // preferentially consume big-residual bins.
    if item_size >= 50 {
        score += (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
