        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64) as f64;
        if lookahead_gap == 0.0 {
            score -= 60.0; // exact two-item closure: ideal
        } else if lookahead_gap > 0.0 {
            // next item fits, but leaves further slack: mild reward scaled by tightness
            score -= 30.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize, worse if gap is large
            score += 0.35 * (-lookahead_gap) as f64;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize leaving residual far below the mean (creating unusable dead space).
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would equal a full empty bin's residual).
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in the stream, prefer closing bins tightly to reduce final waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize bins that leave awkward gaps.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 15.0 + gap;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: only attractive when the item is large and
    // existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let mean_gap = (mean_residual - item_size as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 120.0 * fit_ratio * fit_ratio
            - 30.0 * (1.0 - progress)
            - 0.5 * open_bins_count as f64;
        // Prefer new bin if mean residual barely exceeds the item (poor fits elsewhere).
        if mean_gap < 15.0 {
            score -= 50.0 + new_bin_bonus;
        } else {
            score += 150.0 - new_bin_bonus;
        }
    }

    // Mild global pressure: many open bins -> discourage spreading, favor filling.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight time decay: late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: bins deviating far below mean are good fill targets.
    let deviation = mean_residual - bin_residual as f64;
    if deviation > 0.0 {
        score -= 5.0 * deviation.min(50.0) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Early stream: keep bins tight; late stream: tolerate larger residuals
    let early = (1.0 - progress).max(0.0);
    score += 12.0 * early * norm_pr * norm_pr;

    // Lookahead coupling: reward post_residual that can fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let snug = 1.0 - ((pr - ns) / cap).powf(1.5);
            score -= 10.0 * snug * (1.0 + 0.5 * progress);
        } else {
            // penalize residuals that waste the next item's fit potential
            score += 4.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist; encourage best-fit only
        score += 2.0 * ((fitting_bins_count as f64).ln()) * norm_pr;
    }

    // Mean-residual coupling: penalize deviating badly from the fleet mean
    score += 1.5 * (pr - mean_residual).abs() / cap;

    // Slight preference for filling existing bins as bins accumulate
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr;

    // New-bin candidate: empty bin gets a mild baseline penalty so it's
    // chosen only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes (or large enough) are valuable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Class A: post residual divisible by 10 -> highly reusable, reward.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post residual divisible by 5 but not 10 -> mild reward.
    else if pr % 5 == 0 {
        score -= 2.5;
    }

    // Dead-space penalty via integer division thresholds:
    // leftover in (0, 10) is nearly unusable (min item is 10 in classic case, 1 here).
    if pr < 10 {
        score += 14.0;
    } else if pr < 20 {
        score += 5.0;
    }

    // Coupling with lookahead: if the next item fits exactly in post_residual,
    // this is a perfect pairing -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size <= pr {
            // next item fits but leaves a residue; penalize proportionally to new dead space
            let nxt_post = pr - next_item_size;
            score += (nxt_post as f64) * 0.15;
            if nxt_post < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot use this residual: mildly penalize large leftovers
            score += (pr as f64) * 0.08;
        }
    }

    // Fraction-of-capacity harmonic classes on the fill level.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    if (fill * 4.0).round() as u32 == (fill * 4.0) as u32 * 1 {
        // near quarter-marks of capacity are natural checkpoints
        score -= 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are very full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 8.0 + 20.0 * pressure;
    }

    // Slight preference to pack into bins that are already well-filled.
    score -= fill * 4.0;

    // Progress-dependent tightening: late in the stream, minimize dead space harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100, assume ~10).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0; // severe penalty for creating tiny dead space
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin usage / spreading).
    score += (open_bins_count as f64) * 1.5;

    // If this is the ONLY bin that fits, strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item can still fit after this placement
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // penalizing placement into already-loose bins when alternatives exist.
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin has high residual; make it moderately
    // attractive only when it beats creating dead space in open bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin grows with stream progression
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - post_residual as f64 - 20.0 * (1.0 - progress);
    }

    // Slight tie-break: prefer bins with larger residual (less fragmentation risk) generally.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect chain: post_residual == next_item_size -> strong bonus.
        if diff < 0.5 {
            score -= 40.0;
        } else if nxt <= post {
            // Next item still fits in this bin afterwards: mild reward scaled by tightness.
            let tight = 1.0 - (diff / post.max(1.0));
            score -= 15.0 * tight;
        } else {
            // Next item cannot fit: penalize proportional to wasted lookahead potential.
            score += 8.0 * ((nxt - post) / nxt).min(1.0);
        }
        // Bonus if post_residual + next item chains into a near-full bin.
        if post + nxt <= bin_capacity as f64 {
            score -= 6.0 * (1.0 - (post + nxt) / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // favor them (low post_residual relative to mean residual).
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = post / mean_residual;
        score += 10.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.5;
        // Late in the stream, discourage opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight reward for high fill ratio of this placement.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}
